#requires -Version 7.0
<#
    EC-021..EC-111 independent scratch fixture. The first record is written through
    real Collect/Prepare/CodeSave, then derived, self-hashed historical records
    exercise the read-only Sequence math. Derived entries are synthetic input
    for test coverage, not authenticated evidence or proof of defect history.
    The fixture never touches a user business repository.
#>
[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$cli = Join-Path (Split-Path -Parent $PSScriptRoot) 'scripts/ces.ps1'
if (-not (Get-Command git -CommandType Application -ErrorAction SilentlyContinue)) { throw 'Git unavailable.' }
$script:checks = 0
function Check { param([bool] $Ok, [string] $Reason)
    if (-not $Ok) { throw $Reason }
    $script:checks++
}
function Git-Fixture { param([string[]] $Argv)
    $out = @(& git @Argv 2>&1)
    if ($LASTEXITCODE -ne 0) { throw "Git fixture failed ($($Argv -join ' ')): $out" }
    return ($out -join "`n").Trim()
}
function Run-CES { param([string] $Action, [string] $Repo, [int] $Exit, [string[]] $More = @())
    $out = @(& pwsh -NoProfile -File $cli -Action $Action -RepoPath $Repo -Json @More)
    Check ($LASTEXITCODE -eq $Exit) "Wrong $Action exit ($LASTEXITCODE vs $Exit): $out"
    Check ($out.Count -eq 1) 'Expected exactly one JSON envelope.'
    $result = $out[0] | ConvertFrom-Json -Depth 32
    Check ($result.product_version -eq '1.0.0' -and $result.build -eq '1.0.0') 'Wrong version/build.'
    Check ($result.next_step -eq 'none') 'Unimplemented handoff incorrectly advertised.'
    Check ($result.read_only -eq ($Action -ne 'CodeSave')) 'Incorrect read-only flag.'
    return $result
}
function Clone-Record { param([System.Collections.IDictionary] $Record)
    return ($Record | ConvertTo-Json -Depth 32 -Compress | ConvertFrom-Json -Depth 32 -AsHashtable)
}
function Store-Record { param([System.Collections.IDictionary] $Record, [string] $Folder)
    $bytes = [System.Text.UTF8Encoding]::new($false).GetBytes(($Record | ConvertTo-Json -Depth 32 -Compress))
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $hex = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-','').ToLowerInvariant() }
    finally { $sha.Dispose() }
    $id = 'ci-' + $hex
    [System.IO.File]::WriteAllBytes((Join-Path $Folder ($id + '.json')), $bytes)
    return $id
}
function New-Finding { param([System.Collections.IDictionary] $Original, [string] $Id, [string] $Path, [string] $Sha, [string] $Severity)
    $copy = Clone-Record -Record $Original
    $copy.id = $Id
    $copy.path = $Path
    $copy.quote_sha256 = $Sha
    $copy.severity = $Severity
    return $copy
}
$fixture = Join-Path ([System.IO.Path]::GetTempPath()) ('ces sequence ec040 ' + [guid]::NewGuid().ToString('N'))
$repo = Join-Path $fixture 'Project with spaces'
$collectPath = Join-Path $fixture 'collect.json'
$draftPath = Join-Path $fixture 'draft.json'
$missing = 'ci-' + ('f' * 64)
try {
    [void][System.IO.Directory]::CreateDirectory($repo)
    [void](Git-Fixture -Argv @('init','-q','-b','main',$repo))
    [System.IO.File]::WriteAllText((Join-Path $repo 'base.txt'), 'base')
    [void](Git-Fixture -Argv @('-C',$repo,'add','base.txt'))
    [void](Git-Fixture -Argv @('-C',$repo,'-c','user.name=CES Fixture','-c','user.email=fixture@example.invalid','commit','-qm','base'))
    $headBefore = Git-Fixture -Argv @('-C',$repo,'rev-parse','HEAD')
    $indexPath = Git-Fixture -Argv @('-C',$repo,'rev-parse','--git-path','index')
    if (-not [System.IO.Path]::IsPathRooted($indexPath)) { $indexPath = Join-Path $repo $indexPath }
    $indexBefore = (Get-FileHash -LiteralPath $indexPath -Algorithm SHA256).Hash

    $empty = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @('-Mode','Sequence','-SequenceRecordIds',"$missing,ci-$('a'*64)")
    Check ($empty.reason_code -eq 'CODE_SHOW_NOT_FOUND' -and $null -eq $empty.data) 'Absent store was not an explicit missing-record result.'
    Check (-not (Test-Path -LiteralPath (Join-Path $repo '.codex'))) 'Read-only Sequence created state.'
    $required = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @('-Mode','Sequence')
    Check ($required.reason_code -eq 'CODE_SHOW_SEQUENCE_RECORD_IDS_INVALID') 'Missing selection was accepted.'

    [System.IO.File]::WriteAllText((Join-Path $repo 'file Ω.txt'), "private sequence quote`n")
    $collect = Run-CES -Action Collect -Repo $repo -Exit 0 -More @('-Mode','WorkingTree','-IncludeUntrackedContent')
    [System.IO.File]::WriteAllText($collectPath, ($collect | ConvertTo-Json -Depth 32 -Compress), [System.Text.UTF8Encoding]::new($false))
    $prepared = Run-CES -Action CodePrepare -Repo $repo -Exit 0 -More @('-Mode','Snapshot','-EvidencePath',$collectPath,'-IncludeUntrackedContent')
    Check ($prepared.reason_code -eq 'CODE_PREPARE_READY') 'Real fixture preparation did not succeed.'
    $draft = [ordered]@{
        schema_version = 'ces.code_insight_draft.v1'; task_kind = 'code_analysis'
        packet_sha256 = $prepared.data.packet_sha256
        saved_collect_sha256 = $prepared.data.preparation.saved_collect_sha256
        summary = 'Synthetic historical sequence seed.'
        findings = @([ordered]@{
            id = 'F1'; title = 'Fixture local text'; severity = 'info'; confidence = 'medium'
            layer = 'untracked'; path = 'file Ω.txt'; evidence_quote = 'private sequence quote'
            reasoning = 'The temporary untracked text may disappear after fixture cleanup.'
            impact = 'The local fixture could lose its untracked note during cleanup.'
            recommendation = 'Review if this note needs to be committed after review.'
        })
        limitations = @('A controlled fixture is not a report of defects.')
    }
    [System.IO.File]::WriteAllText($draftPath, ($draft | ConvertTo-Json -Depth 32 -Compress), [System.Text.UTF8Encoding]::new($false))
    $saved = Run-CES -Action CodeSave -Repo $repo -Exit 0 -More @('-Mode','Snapshot','-EvidencePath',$collectPath,'-InputPath',$draftPath,'-IncludeUntrackedContent','-ApprovePersist')
    Check ($saved.reason_code -eq 'CODE_SAVE_OK') 'Could not create authentic CodeSave seed.'
    $store = Join-Path $repo '.codex/ces/code-insights'
    $seed = Get-Content -LiteralPath (Join-Path $store ($saved.data.record_id + '.json')) -Raw -Encoding utf8 | ConvertFrom-Json -AsHashtable -Depth 32
    $orig = $seed.checked_findings[0]

    $a = Clone-Record -Record $seed
    $a.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'file Ω.txt' -Sha $orig.quote_sha256 -Severity 'info'),
        (New-Finding -Original $orig -Id 'F2' -Path 'file Ω.txt' -Sha $orig.quote_sha256 -Severity 'high'),
        (New-Finding -Original $orig -Id 'F3' -Path 'src/A.txt' -Sha ('a'*64) -Severity 'high'),
        (New-Finding -Original $orig -Id 'F4' -Path 'src/C.txt' -Sha ('c'*64) -Severity 'low')
    ); $a.finding_count = 4; $a.summary = 'A: one repeated anchor plus two unique anchors.'
    $aId = Store-Record -Record $a -Folder $store

    $b = Clone-Record -Record $seed
    $b.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'file Ω.txt' -Sha $orig.quote_sha256 -Severity 'high'),
        (New-Finding -Original $orig -Id 'F2' -Path 'src/a.txt' -Sha ('a'*64) -Severity 'high'),
        (New-Finding -Original $orig -Id 'F3' -Path 'src/B.txt' -Sha ('b'*64) -Severity 'medium')
    ); $b.finding_count = 3; $b.summary = 'B: changed reported severity mix and two different anchors.'
    $bId = Store-Record -Record $b -Folder $store

    $c = Clone-Record -Record $b
    $c.checked_findings = @($b.checked_findings[0], $b.checked_findings[1])
    $c.finding_count = 2; $c.summary = 'C: B without one historical observation.'
    $cId = Store-Record -Record $c -Folder $store

    $zero = Clone-Record -Record $seed
    $zero.checked_findings = @(); $zero.finding_count = 0; $zero.summary = 'Zero reported findings.'
    $zeroId = Store-Record -Record $zero -Folder $store

    # EC-022: A/B/C/D support exact-anchor trajectory patterns. Case-sensitive
    # src/A and src/a are different; src/A vanishes from B/C and returns in D.
    $d = Clone-Record -Record $seed
    $d.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'file Ω.txt' -Sha $orig.quote_sha256 -Severity 'info'),
        (New-Finding -Original $orig -Id 'F2' -Path 'src/A.txt' -Sha ('a'*64) -Severity 'medium'),
        (New-Finding -Original $orig -Id 'F3' -Path 'src/Z.txt' -Sha ('d'*64) -Severity 'low')
    ); $d.finding_count = 3; $d.summary = 'D: exact src/A anchor returns after two unreported positions.'
    $dId = Store-Record -Record $d -Folder $store

    $zero2 = Clone-Record -Record $zero
    $zero2.summary = 'Another unique zero Finding observation.'
    $zero2Id = Store-Record -Record $zero2 -Folder $store

    # EC-027: materially identical anchor/severity profiles can be saved as
    # different content-addressed bodies with different free-form prose.
    $aReturn = Clone-Record -Record $a
    $aReturn.summary = 'A again, with different prose but the same anchored severity distribution.'
    $aReturnId = Store-Record -Record $aReturn -Folder $store
    $aReturnRepeat = Clone-Record -Record $a
    $aReturnRepeat.summary = 'Another independently saved return-to-A profile.'
    $aReturnRepeatId = Store-Record -Record $aReturnRepeat -Folder $store

    # Existing but unselected malformed JSON must not be opened by Sequence.
    $invalidUnselected = 'ci-' + ('0' * 64)
    [System.IO.File]::WriteAllText((Join-Path $store ($invalidUnselected + '.json')), '{bad json')
    $query = "$aId,$bId,$cId"
    $result = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @('-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','1')
    Check ($result.reason_code -eq 'CODE_SHOW_OK') 'Valid sequence was not accepted.'
    Check (($result.data.sequence_record_ids -join ',') -ceq $query) 'Sequence reordered caller-provided record IDs.'
    Check ($result.data.selected_record_count -eq 3 -and $result.data.scanned_record_count -eq 3 -and $result.data.step_count -eq 2) 'Selected scan and step count incorrect.'
    Check ($result.data.record_count -ge 5) 'Whole filename inventory count was not reported.'
    # EC-027: first-to-every-later is not just N-1 adjacent comparisons.
    # A/C omits B's transient anchor and still detects retained severity mix.
    $drift3 = $result.data.baseline_drift
    Check ($drift3.baseline_position -eq 1 -and
        $drift3.baseline_record_id -ceq $aId -and $drift3.comparison_count -eq 2 -and
        $drift3.comparisons.Count -eq 2 -and
        $drift3.counts.differs_from_baseline_profile_position_count -eq 2 -and
        $drift3.counts.matches_baseline_profile_position_count -eq 0 -and
        $drift3.counts.returns_to_baseline_profile_after_previous_difference_position_count -eq 0 -and
        -not $drift3.last_position_matches_baseline_profile) 'Baseline comparison failed nonadjacent scope and full position counts.'
    $abBase = $drift3.comparisons[0]
    $acBase = $drift3.comparisons[1]
    Check ($abBase.compared_position -eq 2 -and
        $abBase.compared_record_id -ceq $bId -and
        $abBase.counts.baseline_only_exact_anchor_count -eq 2 -and
        $abBase.counts.compared_only_exact_anchor_count -eq 2 -and
        $abBase.counts.retained_severity_distribution_changed_count -eq 1 -and
        $abBase.counts.changed_path_count -eq 5 -and
        $abBase.counts.exact_anchor_symmetric_difference_count -eq 4 -and
        $abBase.changed_paths.Count -eq 1 -and
        $abBase.omitted_changed_paths -eq 4 -and $abBase.changed_paths_truncated) 'First baseline pair did not retain full adjacent counts under Top=1.'
    Check ($acBase.compared_position -eq 3 -and
        $acBase.compared_record_id -ceq $cId -and
        $acBase.counts.baseline_only_exact_anchor_count -eq 2 -and
        $acBase.counts.compared_only_exact_anchor_count -eq 1 -and
        $acBase.counts.retained_exact_anchor_count -eq 1 -and
        $acBase.counts.retained_severity_distribution_changed_count -eq 1 -and
        $acBase.counts.changed_path_count -eq 4 -and
        $acBase.counts.exact_anchor_symmetric_difference_count -eq 3 -and
        $acBase.changed_paths[0].path -ceq 'src/A.txt' -and
        $acBase.changed_paths[0].comparison_status -ceq 'baseline_only' -and
        $acBase.omitted_changed_paths -eq 3 -and $acBase.changed_paths_truncated -and
        $drift3.counts.maximum_changed_path_count -eq 5 -and
        $drift3.counts.maximum_exact_anchor_symmetric_difference_count -eq 4) 'Nonadjacent baseline-to-C comparison fabricated an intervening B anchor or clipped totals.'
    # EC-028: selected baseline path profiles differ per position, not per
    # adjacent step. B-only src/B is a 010 report while the other four
    # paths remain different from A in both B and C. Case is significant.
    $p3 = $drift3.path_persistence
    Check ($p3.selected_record_count -eq 3 -and $p3.compared_position_count -eq 2 -and
        $p3.counts.distinct_saved_path_union_count -eq 5 -and
        $p3.counts.paths_ever_deviating_from_baseline_count -eq 5 -and
        $p3.counts.paths_deviating_in_multiple_comparisons_count -eq 4 -and
        $p3.counts.paths_deviating_in_every_comparison_count -eq 4 -and
        $p3.counts.paths_deviating_at_last_selected_position_count -eq 4 -and
        $p3.counts.paths_returning_to_baseline_after_previous_difference_count -eq 1 -and
        $p3.counts.return_to_baseline_path_position_occurrences -eq 1 -and
        $p3.counts.paths_with_severity_histogram_only_deviation_count -eq 1 -and
        $p3.counts.severity_histogram_only_deviation_path_position_occurrences -eq 2 -and
        $p3.counts.deviating_path_position_occurrences -eq 9 -and
        $p3.counts.cumulative_exact_anchor_symmetric_difference_across_baseline_pairs_count -eq 7) 'Path persistence miscounted nonadjacent A/B/C baseline differences.'
    Check ($p3.deviation_comparison_count_distribution.Count -eq 3 -and
        $p3.deviation_comparison_count_distribution[0].saved_path_count -eq 0 -and
        $p3.deviation_comparison_count_distribution[1].saved_path_count -eq 1 -and
        $p3.deviation_comparison_count_distribution[2].saved_path_count -eq 4 -and
        $p3.comparison_totals.Count -eq 2 -and
        $p3.comparison_totals[0].changed_path_count -eq 5 -and
        $p3.comparison_totals[1].changed_path_count -eq 4 -and
        $p3.comparison_totals[0].severity_histogram_only_changed_path_count -eq 1 -and
        $p3.comparison_totals[1].severity_histogram_only_changed_path_count -eq 1 -and
        $p3.hotspots.Count -eq 1 -and $p3.hotspots[0].path -ceq 'src/A.txt' -and
        $p3.hotspots[0].deviation_from_baseline_pattern -ceq '011' -and
        $p3.hotspots[0].reporting_pattern -ceq '100' -and
        $p3.hotspots[0].longest_consecutive_deviation_run -eq 2 -and
        $p3.omitted_hotspots -eq 4 -and $p3.hotspots_truncated) 'Path persistence distribution, ordinal Top=1 rank or complete column counts failed.'

    # EC-029: all unordered pairs are compared, including B/C which is
    # neither an adjacent baseline pair from A nor a first-vs-later-only row.
    # Exact profile classes are derived from the full equality relation.
    $pair3 = $result.data.pairwise_profile
    Check ($pair3.selected_record_count -eq 3 -and $pair3.pair_count -eq 3 -and
        $pair3.pairs.Count -eq 3 -and $pair3.counts.matching_profile_pair_count -eq 0 -and
        $pair3.counts.differing_profile_pair_count -eq 3 -and
        $pair3.counts.severity_histogram_only_difference_pair_count -eq 0 -and
        $pair3.counts.path_presence_difference_pair_count -eq 3 -and
        $pair3.counts.exact_anchor_presence_difference_pair_count -eq 3 -and
        $pair3.counts.changed_path_pair_occurrences -eq 10 -and
        $pair3.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 8 -and
        $pair3.counts.retained_severity_distribution_changed_anchor_pair_occurrences -eq 2 -and
        $pair3.counts.maximum_changed_path_count -eq 5 -and
        $pair3.counts.maximum_exact_anchor_symmetric_difference_count -eq 4) 'All-pairs profile totals for A/B/C are incomplete or double counted.'
    Check ($pair3.pairs[0].left_position -eq 1 -and $pair3.pairs[0].right_position -eq 2 -and
        $pair3.pairs[0].counts.changed_path_count -eq 5 -and
        $pair3.pairs[1].left_position -eq 1 -and $pair3.pairs[1].right_position -eq 3 -and
        $pair3.pairs[1].counts.changed_path_count -eq 4 -and
        $pair3.pairs[2].left_position -eq 2 -and $pair3.pairs[2].right_position -eq 3 -and
        $pair3.pairs[2].counts.changed_path_count -eq 1 -and
        $pair3.pairs[2].counts.exact_anchor_symmetric_difference_count -eq 1) 'All-pairs rows lost caller-position order or the nonbaseline B/C pair.'
    Check ($pair3.counts.distinct_profile_class_count -eq 3 -and
        $pair3.counts.repeated_profile_class_count -eq 0 -and
        $pair3.counts.positions_in_repeated_profile_classes_count -eq 0 -and
        $pair3.counts.singleton_profile_class_count -eq 3 -and
        $pair3.profile_classes.Count -eq 3 -and
        $pair3.changed_path_count_distribution.Count -eq 6 -and
        $pair3.changed_path_count_distribution[0].record_pair_count -eq 0 -and
        $pair3.changed_path_count_distribution[1].record_pair_count -eq 1 -and
        $pair3.changed_path_count_distribution[4].record_pair_count -eq 1 -and
        $pair3.changed_path_count_distribution[5].record_pair_count -eq 1) 'Pairwise profile classes or complete changed-path distance distribution are wrong.'

    # EC-030: every EC-029 unordered pair must be attributable to saved
    # paths, including a pair that omits a path on BOTH sides. Top=1 caps
    # only displayed hotspots, not any pair/path sums or frequency bins.
    $pathPairs = $pair3.path_disagreement
    Check ($pathPairs.selected_record_count -eq 3 -and $pathPairs.pair_count -eq 3 -and
        $pathPairs.counts.distinct_saved_path_union_count -eq 5 -and
        $pathPairs.counts.paths_differing_in_at_least_one_pair_count -eq 5 -and
        $pathPairs.counts.paths_matching_in_all_pairs_count -eq 0 -and
        $pathPairs.counts.changed_path_pair_occurrences -eq 10 -and
        $pathPairs.counts.matching_path_pair_occurrences -eq 5 -and
        $pathPairs.counts.one_sided_path_pair_occurrences -eq 8 -and
        $pathPairs.counts.retained_path_anchor_churn_pair_occurrences -eq 0 -and
        $pathPairs.counts.retained_path_severity_change_pair_occurrences -eq 2 -and
        $pathPairs.counts.severity_histogram_only_difference_path_pair_occurrences -eq 2 -and
        $pathPairs.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 8 -and
        $pathPairs.counts.retained_severity_changed_anchor_pair_occurrences -eq 2) 'Path-wise all-pairs totals lost a one-sided path, B/C omission, or severity-only difference.'
    Check ($pathPairs.differing_pair_count_distribution.Count -eq 4 -and
        $pathPairs.differing_pair_count_distribution[0].saved_path_count -eq 0 -and
        $pathPairs.differing_pair_count_distribution[1].saved_path_count -eq 0 -and
        $pathPairs.differing_pair_count_distribution[2].saved_path_count -eq 5 -and
        $pathPairs.differing_pair_count_distribution[3].saved_path_count -eq 0 -and
        $pathPairs.preview_top -eq 1 -and $pathPairs.hotspots.Count -eq 1 -and
        $pathPairs.omitted_hotspots -eq 4 -and $pathPairs.hotspots_truncated -and
        $pathPairs.hotspots[0].path -ceq 'src/A.txt' -and
        $pathPairs.hotspots[0].reporting_position_count -eq 1 -and
        $pathPairs.hotspots[0].differing_pair_count -eq 2 -and
        $pathPairs.hotspots[0].matching_pair_count -eq 1 -and
        $pathPairs.hotspots[0].differing_pairs.Count -eq 2 -and
        $pathPairs.hotspots[0].differing_pairs[0].left_position -eq 1 -and
        $pathPairs.hotspots[0].differing_pairs[0].right_position -eq 2 -and
        $pathPairs.hotspots[0].differing_pairs[1].left_position -eq 1 -and
        $pathPairs.hotspots[0].differing_pairs[1].right_position -eq 3) 'Pair-path frequency bins, ordinal ranking, full displayed pair list or zero-distance B/C handling failed.'

    # EC-031: all five A/B/C paths have TWO local profile classes, yet
    # the report-wide classes remain three. The difference-frequency
    # atlas and each historical path partition must agree on every pair.
    $pathClasses3 = $pair3.path_profile_classes
    Check ($pathClasses3.selected_record_count -eq 3 -and $pathClasses3.pair_count -eq 3 -and
        $pathClasses3.counts.distinct_saved_path_union_count -eq 5 -and
        $pathClasses3.counts.paths_with_single_profile_class_count -eq 0 -and
        $pathClasses3.counts.paths_with_multiple_profile_classes_count -eq 5 -and
        $pathClasses3.counts.paths_with_all_positions_distinct_profile_count -eq 0 -and
        $pathClasses3.counts.paths_with_unreported_positions_count -eq 4 -and
        $pathClasses3.counts.paths_with_reused_reported_profile_count -eq 2 -and
        $pathClasses3.counts.total_path_profile_class_count -eq 10 -and
        $pathClasses3.counts.reported_path_profile_class_count -eq 6 -and
        $pathClasses3.counts.unreported_path_profile_class_count -eq 4 -and
        $pathClasses3.counts.matching_path_pair_occurrences -eq 5 -and
        $pathClasses3.counts.differing_path_pair_occurrences -eq 10 -and
        $pathClasses3.distinct_profile_class_count_distribution.Count -eq 3 -and
        $pathClasses3.distinct_profile_class_count_distribution[0].saved_path_count -eq 0 -and
        $pathClasses3.distinct_profile_class_count_distribution[1].saved_path_count -eq 5 -and
        $pathClasses3.distinct_profile_class_count_distribution[2].saved_path_count -eq 0) 'Per-path class partition A/B/C totals did not reconcile to the complete pair atlas.'
    Check ($pathClasses3.preview_top -eq 1 -and $pathClasses3.hotspots.Count -eq 1 -and
        $pathClasses3.omitted_hotspots -eq 4 -and $pathClasses3.hotspots_truncated -and
        $pathClasses3.hotspots[0].path -ceq 'file Ω.txt' -and
        $pathClasses3.hotspots[0].distinct_profile_class_count -eq 2 -and
        $pathClasses3.hotspots[0].differing_pair_count -eq 2 -and
        $pathClasses3.hotspots[0].profile_classes.Count -eq 2 -and
        $pathClasses3.hotspots[0].profile_classes[0].representative_position -eq 1 -and
        $pathClasses3.hotspots[0].profile_classes[0].finding_statement_count -eq 2 -and
        ($pathClasses3.hotspots[0].profile_classes[1].positions -join ',') -ceq '2,3' -and
        ($pathClasses3.hotspots[0].profile_classes[1].record_ids -join ',') -ceq "$bId,$cId" -and
        ($pathClasses3.hotspots[0].position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,2') 'Per-path classes must show every selected position and every exact class member without clipping.'

    # B/C keeps two identical saved path profiles and changes only src/B;
    # the zero bin must COUNT real saved paths, not be an empty placeholder.
    $bcOnly = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$bId,$cId",'-SequenceTop','1')
    $bcAtlas = $bcOnly.data.pairwise_profile.path_disagreement
    Check ($bcAtlas.counts.distinct_saved_path_union_count -eq 3 -and
        $bcAtlas.counts.paths_matching_in_all_pairs_count -eq 2 -and
        $bcAtlas.counts.paths_differing_in_at_least_one_pair_count -eq 1 -and
        $bcAtlas.counts.changed_path_pair_occurrences -eq 1 -and
        $bcAtlas.differing_pair_count_distribution[0].saved_path_count -eq 2 -and
        $bcAtlas.differing_pair_count_distribution[1].saved_path_count -eq 1 -and
        $bcAtlas.hotspots[0].path -ceq 'src/B.txt' -and
        $bcAtlas.hotspots[0].differing_pairs[0].path_presence_difference) 'Stable saved paths were misclassified as pairwise disagreement.'

    $bcClasses = $bcOnly.data.pairwise_profile.path_profile_classes
    Check ($bcClasses.counts.distinct_saved_path_union_count -eq 3 -and
        $bcClasses.counts.paths_with_single_profile_class_count -eq 2 -and
        $bcClasses.counts.paths_with_multiple_profile_classes_count -eq 1 -and
        $bcClasses.counts.paths_with_unreported_positions_count -eq 1 -and
        $bcClasses.counts.paths_with_reused_reported_profile_count -eq 2 -and
        $bcClasses.counts.total_path_profile_class_count -eq 4 -and
        $bcClasses.distinct_profile_class_count_distribution[0].saved_path_count -eq 2 -and
        $bcClasses.distinct_profile_class_count_distribution[1].saved_path_count -eq 1 -and
        $bcClasses.hotspots[0].path -ceq 'src/B.txt' -and
        $bcClasses.hotspots[0].profile_classes[1].path_reported -eq $false) 'B/C should separate one missing saved path while preserving both fully equal paths.'

    # EC-032: A/B/C carries five exact paths. Four change once; src/B
    # is unreported, then reported, then unreported again (class 1->2->1).
    $pathJourneys3 = $result.data.pairwise_profile.path_profile_transitions
    Check ($pathJourneys3.counts.distinct_saved_path_union_count -eq 5 -and
        $pathJourneys3.counts.paths_with_profile_transitions_count -eq 5 -and
        $pathJourneys3.counts.paths_with_multiple_profile_transitions_count -eq 1 -and
        $pathJourneys3.counts.paths_with_return_to_prior_profile_count -eq 1 -and
        $pathJourneys3.counts.paths_with_return_to_unreported_profile_count -eq 1 -and
        $pathJourneys3.counts.return_to_prior_profile_occurrences -eq 1 -and
        $pathJourneys3.counts.return_to_reported_profile_occurrences -eq 0 -and
        $pathJourneys3.counts.adjacent_profile_transition_occurrences -eq 6 -and
        $pathJourneys3.counts.total_profile_run_count -eq 11 -and
        $pathJourneys3.profile_transition_count_distribution.Count -eq 3 -and
        $pathJourneys3.profile_transition_count_distribution[0].saved_path_count -eq 0 -and
        $pathJourneys3.profile_transition_count_distribution[1].saved_path_count -eq 4 -and
        $pathJourneys3.profile_transition_count_distribution[2].saved_path_count -eq 1 -and
        $pathJourneys3.adjacent_steps[0].changed_path_profile_count -eq 5 -and
        $pathJourneys3.adjacent_steps[1].changed_path_profile_count -eq 1 -and
        $pathJourneys3.adjacent_steps[1].both_unreported_matching_path_count -eq 2 -and
        $pathJourneys3.adjacent_steps[1].return_to_unreported_profile_count -eq 1 -and
        $pathJourneys3.hotspots.Count -eq 1 -and $pathJourneys3.omitted_hotspots -eq 4 -and
        $pathJourneys3.hotspots[0].path -ceq 'src/B.txt' -and
        ($pathJourneys3.hotspots[0].position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,1' -and
        $pathJourneys3.hotspots[0].profile_runs.Count -eq 3 -and
        $pathJourneys3.hotspots[0].transition_events[1].returns_to_unreported_profile) 'EC-032 lost explicit missing->reported->missing class transitions.'

    # Preview size must not change full pair/path accounting. All five
    # changed saved paths become visible at Top=20, with no pair omissions.
    $allPathsPreview = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','20')
    $allPathsAtlas = $allPathsPreview.data.pairwise_profile.path_disagreement
    Check (($allPathsAtlas.counts | ConvertTo-Json -Depth 16 -Compress) -ceq
        ($pathPairs.counts | ConvertTo-Json -Depth 16 -Compress) -and
        ($allPathsAtlas.differing_pair_count_distribution | ConvertTo-Json -Depth 16 -Compress) -ceq
        ($pathPairs.differing_pair_count_distribution | ConvertTo-Json -Depth 16 -Compress) -and
        $allPathsAtlas.hotspots.Count -eq 5 -and
        $allPathsAtlas.omitted_hotspots -eq 0 -and
        -not $allPathsAtlas.hotspots_truncated -and
        $allPathsAtlas.hotspots[4].path -ceq 'file Ω.txt' -and
        $allPathsAtlas.hotspots[4].severity_histogram_only_difference_pair_count -eq 2 -and
        $allPathsAtlas.hotspots[4].differing_pairs.Count -eq 2) 'SequenceTop altered complete path-pair statistics or omitted saved severity-only path observations.'

    $allClassPreview = $allPathsPreview.data.pairwise_profile.path_profile_classes
    Check (($allClassPreview.counts | ConvertTo-Json -Depth 16 -Compress) -ceq
        ($pathClasses3.counts | ConvertTo-Json -Depth 16 -Compress) -and
        ($allClassPreview.distinct_profile_class_count_distribution | ConvertTo-Json -Depth 16 -Compress) -ceq
        ($pathClasses3.distinct_profile_class_count_distribution | ConvertTo-Json -Depth 16 -Compress) -and
        $allClassPreview.hotspots.Count -eq 5 -and
        $allClassPreview.omitted_hotspots -eq 0 -and -not $allClassPreview.hotspots_truncated -and
        ($allClassPreview.hotspots | ForEach-Object { $_.path }) -join ',' -ceq
        'file Ω.txt,src/A.txt,src/B.txt,src/C.txt,src/a.txt') 'SequenceTop clipped complete EC-031 counts or changed ordinal hot-spot ordering.'

    $wideJourneys3 = $allPathsPreview.data.pairwise_profile.path_profile_transitions
    Check (($wideJourneys3.counts | ConvertTo-Json -Depth 16 -Compress) -ceq
        ($pathJourneys3.counts | ConvertTo-Json -Depth 16 -Compress) -and
        ($wideJourneys3.profile_transition_count_distribution | ConvertTo-Json -Depth 16 -Compress) -ceq
        ($pathJourneys3.profile_transition_count_distribution | ConvertTo-Json -Depth 16 -Compress) -and
        ($wideJourneys3.adjacent_steps | ConvertTo-Json -Depth 16 -Compress) -ceq
        ($pathJourneys3.adjacent_steps | ConvertTo-Json -Depth 16 -Compress) -and
        $wideJourneys3.hotspots.Count -eq 5 -and $wideJourneys3.omitted_hotspots -eq 0 -and
        ($wideJourneys3.hotspots | ForEach-Object { $_.path }) -join ',' -ceq
        'src/B.txt,file Ω.txt,src/A.txt,src/C.txt,src/a.txt' -and
        $wideJourneys3.hotspots[0].transition_events.Count -eq 2 -and
        $wideJourneys3.hotspots[0].profile_runs.Count -eq 3) 'EC-032 Top clipping modified complete statistics or changed class-transition hotspot order.'

    $returned = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$aReturnId,$aReturnRepeatId",'-SequenceTop','1')
    $returnDrift = $returned.data.baseline_drift
    Check ($returnDrift.comparison_count -eq 3 -and
        $returnDrift.counts.differs_from_baseline_profile_position_count -eq 1 -and
        $returnDrift.counts.matches_baseline_profile_position_count -eq 2 -and
        $returnDrift.counts.returns_to_baseline_profile_after_previous_difference_position_count -eq 1 -and
        $returnDrift.comparisons[1].matches_baseline_profile -and
        $returnDrift.comparisons[1].returns_to_baseline_profile_after_previous_difference -and
        $returnDrift.comparisons[1].counts.changed_path_count -eq 0 -and
        $returnDrift.comparisons[1].changed_paths.Count -eq 0 -and
        $returnDrift.comparisons[1].omitted_changed_paths -eq 0 -and
        $returnDrift.comparisons[2].matches_baseline_profile -and
        -not $returnDrift.comparisons[2].returns_to_baseline_profile_after_previous_difference -and
        $returnDrift.last_position_matches_baseline_profile -and
        -not $returnDrift.last_position_returns_to_baseline_profile_after_previous_difference) 'A/B/A/A saved-profile return was counted more than once or compared model prose.'
    $returnPairs = $returned.data.pairwise_profile
    Check ($returnPairs.pair_count -eq 6 -and
        $returnPairs.counts.matching_profile_pair_count -eq 3 -and
        $returnPairs.counts.differing_profile_pair_count -eq 3 -and
        $returnPairs.counts.distinct_profile_class_count -eq 2 -and
        $returnPairs.counts.repeated_profile_class_count -eq 1 -and
        $returnPairs.counts.positions_in_repeated_profile_classes_count -eq 3 -and
        $returnPairs.counts.singleton_profile_class_count -eq 1 -and
        $returnPairs.profile_classes[0].representative_position -eq 1 -and
        $returnPairs.profile_classes[0].member_count -eq 3 -and
        ($returnPairs.profile_classes[0].positions -join ',') -ceq '1,3,4' -and
        $returnPairs.profile_classes[1].representative_position -eq 2 -and
        $returnPairs.profile_classes[1].member_count -eq 1) 'A/B/A/A did not collapse exact A profiles into one all-pairs equivalence class.'

    $returnAtlas = $returnPairs.path_disagreement
    Check ($returnAtlas.pair_count -eq 6 -and
        $returnAtlas.counts.distinct_saved_path_union_count -eq 5 -and
        $returnAtlas.counts.changed_path_pair_occurrences -eq 15 -and
        $returnAtlas.counts.matching_path_pair_occurrences -eq 15 -and
        $returnAtlas.counts.one_sided_path_pair_occurrences -eq 12 -and
        $returnAtlas.counts.severity_histogram_only_difference_path_pair_occurrences -eq 3 -and
        $returnAtlas.differing_pair_count_distribution.Count -eq 7 -and
        $returnAtlas.differing_pair_count_distribution[3].saved_path_count -eq 5 -and
        $returnAtlas.hotspots[0].differing_pairs.Count -eq 3 -and
        $returnAtlas.hotspots[0].differing_pairs[2].left_position -eq 2 -and
        $returnAtlas.hotspots[0].differing_pairs[2].right_position -eq 4) 'Repeated A profile classes did not yield exactly three cross-class disagreements per path.'

    $returnClasses = $returnPairs.path_profile_classes
    Check ($returnClasses.counts.distinct_saved_path_union_count -eq 5 -and
        $returnClasses.counts.paths_with_multiple_profile_classes_count -eq 5 -and
        $returnClasses.counts.total_path_profile_class_count -eq 10 -and
        $returnClasses.counts.differing_path_pair_occurrences -eq 15 -and
        $returnClasses.hotspots[0].profile_classes[0].member_count -eq 3 -and
        ($returnClasses.hotspots[0].profile_classes[0].positions -join ',') -ceq '1,3,4' -and
        $returnClasses.hotspots[0].profile_classes[1].member_count -eq 1 -and
        ($returnClasses.hotspots[0].position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,1,1') 'Repeated A report profiles did not retain the exact per-path nonconsecutive class memberships.'

    $returnJourneys = $returned.data.pairwise_profile.path_profile_transitions
    Check ($returnJourneys.counts.distinct_saved_path_union_count -eq 5 -and
        $returnJourneys.counts.paths_with_multiple_profile_transitions_count -eq 5 -and
        $returnJourneys.counts.paths_with_return_to_prior_profile_count -eq 5 -and
        $returnJourneys.counts.paths_with_return_to_reported_profile_count -eq 3 -and
        $returnJourneys.counts.paths_with_return_to_unreported_profile_count -eq 2 -and
        $returnJourneys.counts.paths_reported_again_after_unreported_gap_count -eq 2 -and
        $returnJourneys.counts.adjacent_profile_transition_occurrences -eq 10 -and
        $returnJourneys.counts.return_to_prior_profile_occurrences -eq 5 -and
        $returnJourneys.counts.reported_again_after_unreported_gap_occurrences -eq 2 -and
        $returnJourneys.counts.total_profile_run_count -eq 15 -and
        $returnJourneys.profile_transition_count_distribution[2].saved_path_count -eq 5 -and
        $returnJourneys.adjacent_steps[0].changed_path_profile_count -eq 5 -and
        $returnJourneys.adjacent_steps[1].changed_path_profile_count -eq 5 -and
        $returnJourneys.adjacent_steps[2].changed_path_profile_count -eq 0 -and
        $returnJourneys.hotspots[0].transition_events[1].returns_to_reported_profile -and
        $returnJourneys.hotspots[0].profile_runs[2].end_position -eq 4) 'EC-032 A/B/A/A did not distinguish repeated profiles, missing-to-reported gaps and stable runs.'

    # Different saved bytes/prose but identical nonempty A reporting
    # profiles: real saved paths all fall into frequency bin zero.
    $aMatched = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$aReturnId",'-SequenceTop','1')
    $aMatchedAtlas = $aMatched.data.pairwise_profile.path_disagreement
    Check ($aMatched.data.pairwise_profile.pairs[0].matches_profile -and
        $aMatchedAtlas.counts.distinct_saved_path_union_count -eq 3 -and
        $aMatchedAtlas.counts.paths_differing_in_at_least_one_pair_count -eq 0 -and
        $aMatchedAtlas.counts.paths_matching_in_all_pairs_count -eq 3 -and
        $aMatchedAtlas.counts.changed_path_pair_occurrences -eq 0 -and
        $aMatchedAtlas.counts.matching_path_pair_occurrences -eq 3 -and
        $aMatchedAtlas.differing_pair_count_distribution[0].saved_path_count -eq 3 -and
        $aMatchedAtlas.differing_pair_count_distribution[1].saved_path_count -eq 0 -and
        $aMatchedAtlas.hotspots.Count -eq 0 -and -not $aMatchedAtlas.hotspots_truncated) 'Two equal nonempty saved report profiles created spurious path disagreements.'

    $aMatchedClasses = $aMatched.data.pairwise_profile.path_profile_classes
    Check ($aMatchedClasses.counts.paths_with_single_profile_class_count -eq 3 -and
        $aMatchedClasses.counts.paths_with_multiple_profile_classes_count -eq 0 -and
        $aMatchedClasses.counts.paths_with_reused_reported_profile_count -eq 3 -and
        $aMatchedClasses.counts.matching_path_pair_occurrences -eq 3 -and
        $aMatchedClasses.counts.differing_path_pair_occurrences -eq 0 -and
        $aMatchedClasses.distinct_profile_class_count_distribution[0].saved_path_count -eq 3 -and
        $aMatchedClasses.hotspots.Count -eq 0 -and -not $aMatchedClasses.hotspots_truncated) 'Same saved anchor profiles with different summary prose formed spurious classes.'

    $matchedJourneys = $aMatched.data.pairwise_profile.path_profile_transitions
    Check ($matchedJourneys.counts.distinct_saved_path_union_count -eq 3 -and
        $matchedJourneys.counts.paths_with_no_profile_transitions_count -eq 3 -and
        $matchedJourneys.counts.paths_with_profile_transitions_count -eq 0 -and
        $matchedJourneys.counts.adjacent_profile_transition_occurrences -eq 0 -and
        $matchedJourneys.counts.total_profile_run_count -eq 3 -and
        $matchedJourneys.counts.longest_stable_run_in_selected_positions -eq 2 -and
        $matchedJourneys.profile_transition_count_distribution[0].saved_path_count -eq 3 -and
        $matchedJourneys.hotspots.Count -eq 0 -and -not $matchedJourneys.hotspots_truncated) 'EC-032 falsely marked same-content different-prose profiles as changes.'

    $pReturn = $returnDrift.path_persistence
    Check ($pReturn.counts.distinct_saved_path_union_count -eq 5 -and
        $pReturn.counts.paths_ever_deviating_from_baseline_count -eq 5 -and
        $pReturn.counts.paths_deviating_in_multiple_comparisons_count -eq 0 -and
        $pReturn.counts.paths_deviating_at_last_selected_position_count -eq 0 -and
        $pReturn.counts.paths_returning_to_baseline_after_previous_difference_count -eq 5 -and
        $pReturn.counts.return_to_baseline_path_position_occurrences -eq 5 -and
        $pReturn.counts.deviating_path_position_occurrences -eq 5 -and
        $pReturn.deviation_comparison_count_distribution[1].saved_path_count -eq 5 -and
        $pReturn.comparison_totals[0].changed_path_count -eq 5 -and
        $pReturn.comparison_totals[1].changed_path_count -eq 0 -and
        $pReturn.comparison_totals[2].changed_path_count -eq 0 -and
        $pReturn.hotspots[0].deviation_from_baseline_pattern -ceq '0100' -and
        $pReturn.hotspots[0].returns_to_baseline_after_previous_difference_count -eq 1 -and
        -not $pReturn.hotspots[0].deviates_at_last_selected_position -and
        $pReturn.hotspots[0].compared_positions_in_caller_order.Count -eq 3) 'A/B/A/A must restore each of five baseline path profiles exactly once.'

    # Two distinct B-like saved bodies yield A/B/A/B/A, with two
    # independent per-path 1->0 returns; the distinct *record IDs* are
    # real while prose variations do not change exact report profiles.
    $bRepeat = Clone-Record -Record $b
    $bRepeat.summary = 'The same B anchor/severity profile with new prose.'
    $bRepeatId = Store-Record -Record $bRepeat -Folder $store
    $doubleReturn = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$aReturnId,$bRepeatId,$aReturnRepeatId",'-SequenceTop','1')
    $doublePersistence = $doubleReturn.data.baseline_drift.path_persistence
    Check ($doublePersistence.compared_position_count -eq 4 -and
        $doublePersistence.counts.distinct_saved_path_union_count -eq 5 -and
        $doublePersistence.counts.paths_ever_deviating_from_baseline_count -eq 5 -and
        $doublePersistence.counts.paths_deviating_in_multiple_comparisons_count -eq 5 -and
        $doublePersistence.counts.paths_deviating_in_every_comparison_count -eq 0 -and
        $doublePersistence.counts.paths_returning_to_baseline_after_previous_difference_count -eq 5 -and
        $doublePersistence.counts.return_to_baseline_path_position_occurrences -eq 10 -and
        $doublePersistence.counts.deviating_path_position_occurrences -eq 10 -and
        $doublePersistence.deviation_comparison_count_distribution[2].saved_path_count -eq 5 -and
        $doublePersistence.hotspots[0].deviation_from_baseline_pattern -ceq '01010' -and
        $doublePersistence.hotspots[0].longest_consecutive_deviation_run -eq 1 -and
        $doublePersistence.hotspots[0].returns_to_baseline_after_previous_difference_count -eq 2 -and
        $doublePersistence.comparison_totals[0].changed_path_count -eq 5 -and
        $doublePersistence.comparison_totals[1].changed_path_count -eq 0 -and
        $doublePersistence.comparison_totals[2].changed_path_count -eq 5 -and
        $doublePersistence.comparison_totals[3].changed_path_count -eq 0) 'Path persistence must count two real 1-to-0 profile returns, not only distinct returned paths.'

    $wideBaseline = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','20')
    Check ($wideBaseline.data.baseline_drift.comparisons[1].counts.changed_path_count -eq 4 -and
        $wideBaseline.data.baseline_drift.comparisons[1].changed_paths.Count -eq 4 -and
        $wideBaseline.data.baseline_drift.comparisons[1].omitted_changed_paths -eq 0 -and
        -not $wideBaseline.data.baseline_drift.comparisons[1].changed_paths_truncated) 'Widening baseline previews did not restore all changed paths.'
    $wideP = $wideBaseline.data.baseline_drift.path_persistence
    Check ($wideP.hotspots.Count -eq 5 -and $wideP.omitted_hotspots -eq 0 -and
        -not $wideP.hotspots_truncated -and
        $wideP.hotspots[0].path -ceq 'src/A.txt' -and
        $wideP.hotspots[1].path -ceq 'src/C.txt' -and
        $wideP.hotspots[2].path -ceq 'src/a.txt' -and
        $wideP.hotspots[3].path -ceq 'file Ω.txt' -and
        $wideP.hotspots[3].severity_histogram_only_deviation_comparison_count -eq 2 -and
        $wideP.hotspots[3].cumulative_exact_anchor_symmetric_difference_count -eq 0 -and
        $wideP.hotspots[4].path -ceq 'src/B.txt' -and
        $wideP.hotspots[4].deviation_from_baseline_pattern -ceq '010' -and
        $wideP.hotspots[4].returns_to_baseline_after_previous_difference_count -eq 1 -and
        $wideP.hotspots[4].first_deviating_position -eq 2 -and
        $wideP.hotspots[4].last_deviating_position -eq 2) 'Top=20 should show all deviations, ordinal path ties, B-only restoration and severity-only path.'

    $s1 = $result.data.steps[0]
    Check ($s1.counts.retained_exact_anchor_count -eq 1 -and $s1.counts.previous_only_exact_anchor_count -eq 2 -and $s1.counts.next_only_exact_anchor_count -eq 2) 'A to B exact anchor delta incorrect.'
    Check ($s1.counts.retained_severity_distribution_changed_count -eq 1) 'Retained anchor changed-severity histogram was missed.'
    Check ($s1.previews.previous_only.Count -eq 1 -and $s1.previews.next_only.Count -eq 1) 'Preview cap did not apply independently per category.'
    Check ($s1.omitted_previews.previous_only -eq 1 -and $s1.omitted_previews.next_only -eq 1 -and $s1.previews_truncated) 'Omission counts incorrect.'
    $s2 = $result.data.steps[1]
    Check ($s2.counts.retained_exact_anchor_count -eq 2 -and $s2.counts.previous_only_exact_anchor_count -eq 1 -and $s2.counts.next_only_exact_anchor_count -eq 0) 'B to C comparison incorrect.'
    Check ($s2.counts.retained_severity_distribution_changed_count -eq 0) 'Unchanged severity distribution was fabricated as a difference.'

    $t3 = $result.data.anchor_trajectory
    Check ($t3.counts.distinct_exact_anchor_union_count -eq 5 -and
        $t3.counts.reported_in_every_record_count -eq 1 -and
        $t3.counts.reported_once_count -eq 3 -and
        $t3.counts.reported_in_multiple_but_not_every_record_count -eq 1) 'Three-record anchor support partition is wrong.'
    Check ($t3.counts.reappeared_after_at_least_one_unreported_position_count -eq 0 -and
        $t3.counts.reported_in_first_and_last_count -eq 1 -and
        $t3.counts.severity_distribution_varied_across_reported_positions_count -eq 1 -and
        $t3.counts.presence_transitions_across_adjacent_pairs_count -eq 5) 'Three-record trajectory totals diverge from checked pairwise deltas.'
    Check ($t3.reporting_record_count_distribution.Count -eq 3 -and
        $t3.reporting_record_count_distribution[0].distinct_exact_anchor_count -eq 3 -and
        $t3.reporting_record_count_distribution[1].distinct_exact_anchor_count -eq 1 -and
        $t3.reporting_record_count_distribution[2].distinct_exact_anchor_count -eq 1) 'Support histogram omitted or duplicated an anchor.'
    Check ($t3.previews.reported_in_every_record[0].presence_pattern -ceq '111' -and
        $t3.previews.reported_in_every_record[0].observations_in_caller_order[0].severity_counts.info -eq 1 -and
        $t3.previews.reported_in_every_record[0].observations_in_caller_order[0].severity_counts.high -eq 1) 'Multiple Finding severities on one retained anchor were not preserved.'
    Check ($t3.omitted_previews.reported_once -eq 2 -and $t3.previews.reported_once.Count -eq 1 -and
        $t3.previews_truncated) 'Trajectory preview cap or truthful omissions incorrect.'

    $trajectoryFour = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @('-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",'-SequenceTop','1')
    $t4 = $trajectoryFour.data.anchor_trajectory
    Check ($t4.counts.distinct_exact_anchor_union_count -eq 6 -and
        $t4.counts.reported_in_every_record_count -eq 1 -and $t4.counts.reported_once_count -eq 3 -and
        $t4.counts.reported_in_multiple_but_not_every_record_count -eq 2) 'Four-record complete anchor partition is wrong.'
    Check ($t4.counts.reappeared_after_at_least_one_unreported_position_count -eq 1 -and
        $t4.counts.reported_in_first_and_last_count -eq 2 -and
        $t4.counts.severity_distribution_varied_across_reported_positions_count -eq 2 -and
        $t4.counts.presence_transitions_across_adjacent_pairs_count -eq 8) 'Gap-return and severity variation are not calculated over all reports.'
    Check ($t4.reporting_record_count_distribution.Count -eq 4 -and
        $t4.reporting_record_count_distribution[0].distinct_exact_anchor_count -eq 3 -and
        $t4.reporting_record_count_distribution[1].distinct_exact_anchor_count -eq 2 -and
        $t4.reporting_record_count_distribution[2].distinct_exact_anchor_count -eq 0 -and
        $t4.reporting_record_count_distribution[3].distinct_exact_anchor_count -eq 1) 'Four-record support histogram incorrect.'
    Check ($t4.previews.reappeared_after_gap.Count -eq 1 -and
        $t4.previews.reappeared_after_gap[0].presence_pattern -ceq '1001' -and
        $t4.previews.reappeared_after_gap[0].anchor.path -ceq 'src/A.txt' -and
        $t4.previews.reappeared_after_gap[0].observations_in_caller_order[1].severity_counts -eq $null -and
        $t4.previews.reappeared_after_gap[0].observations_in_caller_order[3].severity_counts.medium -eq 1) 'Reappeared exact anchor preview lost an unreported position or severity.'
    Check ($t4.omitted_previews.reported_once -eq 2 -and
        $t4.omitted_previews.severity_distribution_varied -eq 1 -and $t4.previews_truncated) 'Four-record preview omissions misrepresent full counts.'
    # A/B/C/D has three distinct local profiles for file Ω and src/A,
    # including B/C repeated membership and one shared unreported class.
    $classes4 = $trajectoryFour.data.pairwise_profile.path_profile_classes
    Check ($classes4.counts.distinct_saved_path_union_count -eq 6 -and
        $classes4.counts.paths_with_single_profile_class_count -eq 0 -and
        $classes4.counts.paths_with_multiple_profile_classes_count -eq 6 -and
        $classes4.counts.paths_with_all_positions_distinct_profile_count -eq 0 -and
        $classes4.counts.paths_with_unreported_positions_count -eq 5 -and
        $classes4.counts.paths_with_reused_reported_profile_count -eq 2 -and
        $classes4.counts.total_path_profile_class_count -eq 14 -and
        $classes4.counts.reported_path_profile_class_count -eq 9 -and
        $classes4.counts.unreported_path_profile_class_count -eq 5 -and
        $classes4.counts.differing_path_pair_occurrences -eq 23 -and
        $classes4.counts.matching_path_pair_occurrences -eq 13 -and
        $classes4.distinct_profile_class_count_distribution.Count -eq 4 -and
        $classes4.distinct_profile_class_count_distribution[0].saved_path_count -eq 0 -and
        $classes4.distinct_profile_class_count_distribution[1].saved_path_count -eq 4 -and
        $classes4.distinct_profile_class_count_distribution[2].saved_path_count -eq 2 -and
        $classes4.distinct_profile_class_count_distribution[3].saved_path_count -eq 0 -and
        $classes4.hotspots.Count -eq 1 -and $classes4.omitted_hotspots -eq 5 -and
        $classes4.hotspots[0].path -ceq 'file Ω.txt' -and
        $classes4.hotspots[0].distinct_profile_class_count -eq 3 -and
        ($classes4.hotspots[0].profile_classes[1].positions -join ',') -ceq '2,3' -and
        $classes4.hotspots[0].profile_classes[2].representative_position -eq 4 -and
        ($classes4.hotspots[0].position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,2,3') 'Four-position per-path class diversity, missing class or histogram was lost.'

    $fourJourneys = $trajectoryFour.data.pairwise_profile.path_profile_transitions
    Check ($fourJourneys.counts.distinct_saved_path_union_count -eq 6 -and
        $fourJourneys.counts.paths_with_profile_transitions_count -eq 6 -and
        $fourJourneys.counts.paths_with_multiple_profile_transitions_count -eq 4 -and
        $fourJourneys.counts.paths_with_return_to_prior_profile_count -eq 2 -and
        $fourJourneys.counts.paths_with_return_to_unreported_profile_count -eq 2 -and
        $fourJourneys.counts.paths_reported_again_after_unreported_gap_count -eq 1 -and
        $fourJourneys.counts.adjacent_profile_transition_occurrences -eq 10 -and
        $fourJourneys.counts.total_profile_run_count -eq 16 -and
        $fourJourneys.counts.longest_stable_run_in_selected_positions -eq 3 -and
        $fourJourneys.profile_transition_count_distribution.Count -eq 4 -and
        $fourJourneys.profile_transition_count_distribution[1].saved_path_count -eq 2 -and
        $fourJourneys.profile_transition_count_distribution[2].saved_path_count -eq 4 -and
        $fourJourneys.adjacent_steps[2].changed_path_profile_count -eq 4 -and
        $fourJourneys.hotspots[0].path -ceq 'src/B.txt' -and
        $fourJourneys.hotspots[0].transition_events[1].returns_to_unreported_profile) 'EC-032 four-position runs, absence/profile returns or step distribution are incorrect.'

    $threeDistinct = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$dId",'-SequenceTop','2')
    $threeDistinctClasses = $threeDistinct.data.pairwise_profile.path_profile_classes
    Check ($threeDistinctClasses.counts.paths_with_all_positions_distinct_profile_count -eq 2 -and
        $threeDistinctClasses.hotspots.Count -eq 2 -and
        $threeDistinctClasses.hotspots[0].path -ceq 'file Ω.txt' -and
        $threeDistinctClasses.hotspots[1].path -ceq 'src/A.txt' -and
        $threeDistinctClasses.hotspots[1].profile_classes[1].path_reported -eq $false -and
        $threeDistinctClasses.hotspots[1].profile_classes[2].path_reported -eq $true -and
        $threeDistinctClasses.hotspots[1].distinct_profile_class_count -eq 3) 'All-distinct severity/absence/reappearance classes did not preserve caller ordering.'

    # Resumed reporting is NOT necessarily a return to the earlier reported
    # path profile. A and D both cite two paths, but their severities differ.
    $newAfterGap = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$zeroId,$dId",'-SequenceTop','2')
    $newJourneys = $newAfterGap.data.pairwise_profile.path_profile_transitions
    Check ($newJourneys.counts.distinct_saved_path_union_count -eq 4 -and
        $newJourneys.counts.paths_with_return_to_prior_profile_count -eq 0 -and
        $newJourneys.counts.paths_reported_again_after_unreported_gap_count -eq 2 -and
        $newJourneys.counts.reported_again_after_unreported_gap_occurrences -eq 2 -and
        $newJourneys.counts.adjacent_profile_transition_occurrences -eq 6 -and
        $newJourneys.hotspots.Count -eq 2 -and
        $newJourneys.hotspots[0].path -ceq 'file Ω.txt' -and
        $newJourneys.hotspots[1].path -ceq 'src/A.txt' -and
        $newJourneys.hotspots[0].transition_events[1].reported_after_unreported_gap -and
        -not $newJourneys.hotspots[0].transition_events[1].returns_to_prior_profile -and
        $newJourneys.hotspots[0].transition_events[1].first_seen_destination_class_at_position -eq 3 -and
        ($newJourneys.hotspots[1].position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,3') 'EC-032 mistakenly treated a DIFFERENT saved profile after a reporting gap as an exact-profile return.'

    $pairwiseTransitions = 0
    foreach ($step in $trajectoryFour.data.steps) {
        $pairwiseTransitions += $step.counts.previous_only_exact_anchor_count + $step.counts.next_only_exact_anchor_count
    }
    Check ($t4.counts.presence_transitions_across_adjacent_pairs_count -eq $pairwiseTransitions) 'Global transitions disagree with adjacent-step entries.'

    # EC-024: a complete, Top-bounded discovery index must be available even
    # without specifying a known path. Verify both coverage and rank semantics.
    $index3 = $result.data.path_index
    Check ($index3.counts.distinct_saved_path_count -eq 5 -and
        $index3.counts.distinct_exact_anchor_union_count -eq 5 -and
        $index3.counts.finding_statement_count_across_selected_records -eq 9 -and
        $index3.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 5 -and
        $index3.counts.path_presence_transitions_across_adjacent_pairs_count -eq 5) 'Three-record path index totals do not partition checked anchors and statements.'
    Check ($index3.paths.Count -eq 1 -and $index3.paths[0].path -ceq 'src/B.txt' -and
        $index3.paths[0].presence_pattern -ceq '010' -and
        $index3.paths[0].exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 2 -and
        $index3.omitted_paths -eq 4 -and $index3.paths_truncated) 'Three-record path rank, Top cap or exact omissions incorrect.'

    $index4 = $trajectoryFour.data.path_index
    Check ($index4.counts.distinct_saved_path_count -eq 6 -and
        $index4.counts.reported_in_every_record_path_count -eq 1 -and
        $index4.counts.reported_once_path_count -eq 3 -and
        $index4.counts.reported_in_multiple_but_not_every_record_path_count -eq 2 -and
        $index4.counts.reappeared_after_unreported_position_path_count -eq 1 -and
        $index4.counts.finding_statement_count_across_selected_records -eq 12) 'Four-record path support partition or Finding multiplicity incorrect.'
    Check ($index4.counts.path_presence_transitions_across_adjacent_pairs_count -eq 8 -and
        $index4.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq $t4.counts.presence_transitions_across_adjacent_pairs_count -and
        $index4.counts.distinct_exact_anchor_union_count -eq $t4.counts.distinct_exact_anchor_union_count -and
        $index4.paths.Count -eq 1 -and $index4.omitted_paths -eq 5 -and
        $index4.paths[0].path -ceq 'src/A.txt' -and $index4.paths[0].presence_pattern -ceq '1001' -and
        $index4.paths[0].observations_in_caller_order.Count -eq 4) 'Four-record rank tie-break, coverage or trajectory cross-check incorrect.'
    Check ($index4.reporting_record_count_distribution.Count -eq 4 -and
        $index4.reporting_record_count_distribution[0].saved_path_count -eq 3 -and
        $index4.reporting_record_count_distribution[1].saved_path_count -eq 2 -and
        $index4.reporting_record_count_distribution[2].saved_path_count -eq 0 -and
        $index4.reporting_record_count_distribution[3].saved_path_count -eq 1) 'Path support histogram missing its zero bin or confusing paths with statements.'

    # EC-025: path-attributed adjacent deltas identify WHICH caller position
    # changed, including severity-only changes under an unchanged exact anchor.
    # Every full counter is independent of the Top=1 changed-path preview cap.
    $adj3 = $index3.step_deltas
    Check ($adj3.Count -eq 2 -and $adj3[0].step -eq 1 -and
        $adj3[0].previous_record_id -ceq $aId -and $adj3[0].next_record_id -ceq $bId -and
        $adj3[1].step -eq 2 -and $adj3[1].next_record_id -ceq $cId) 'Per-step saved path delta lost caller order.'
    $abPaths = $adj3[0]
    Check ($abPaths.counts.previous_reported_path_count -eq 3 -and
        $abPaths.counts.next_reported_path_count -eq 3 -and
        $abPaths.counts.retained_path_count -eq 1 -and
        $abPaths.counts.previous_only_path_count -eq 2 -and
        $abPaths.counts.next_only_path_count -eq 2 -and
        $abPaths.counts.changed_path_count -eq 5 -and
        $abPaths.counts.retained_path_with_severity_distribution_change_count -eq 1 -and
        $abPaths.counts.retained_path_with_anchor_churn_count -eq 0) 'A/B path partition or severity-only path change attribution failed.'
    Check ($abPaths.counts.retained_exact_anchor_count -eq $s1.counts.retained_exact_anchor_count -and
        $abPaths.counts.previous_only_exact_anchor_count -eq $s1.counts.previous_only_exact_anchor_count -and
        $abPaths.counts.next_only_exact_anchor_count -eq $s1.counts.next_only_exact_anchor_count -and
        $abPaths.counts.retained_severity_distribution_changed_count -eq 1 -and
        $abPaths.counts.previous_finding_statement_count -eq 4 -and
        $abPaths.counts.next_finding_statement_count -eq 3) 'A/B path delta failed full anchor or multiplicity reconciliation.'
    Check ($abPaths.changed_paths.Count -eq 1 -and
        $abPaths.changed_paths[0].path -ceq 'src/A.txt' -and
        $abPaths.changed_paths[0].path_status -ceq 'previous_only' -and
        $abPaths.changed_paths[0].previous_only_exact_anchor_count -eq 1 -and
        $abPaths.omitted_changed_paths -eq 4 -and $abPaths.changed_paths_truncated) 'A/B changed-path ordinal tie or bounded preview was incorrect.'
    $bcPaths = $adj3[1]
    Check ($bcPaths.counts.retained_path_count -eq 2 -and
        $bcPaths.counts.previous_only_path_count -eq 1 -and
        $bcPaths.counts.next_only_path_count -eq 0 -and
        $bcPaths.counts.changed_path_count -eq 1 -and
        $bcPaths.changed_paths.Count -eq 1 -and
        $bcPaths.changed_paths[0].path -ceq 'src/B.txt' -and
        -not $bcPaths.changed_paths_truncated) 'B/C path delta included an unchanged saved path or hid a changed one.'
    $fourDeltas = $index4.step_deltas
    $cdPaths = $fourDeltas[2]
    Check ($fourDeltas.Count -eq 3 -and
        $cdPaths.counts.previous_reported_path_count -eq 2 -and
        $cdPaths.counts.next_reported_path_count -eq 3 -and
        $cdPaths.counts.retained_path_count -eq 1 -and
        $cdPaths.counts.previous_only_path_count -eq 1 -and
        $cdPaths.counts.next_only_path_count -eq 2 -and
        $cdPaths.counts.changed_path_count -eq 4 -and
        $cdPaths.counts.retained_path_with_severity_distribution_change_count -eq 1) 'C/D path entrance, exit or retained changed-severity accounting failed.'
    $pathTransitionsFromSteps = 0
    $anchorTransitionsFromSteps = 0
    foreach ($attributed in $fourDeltas) {
        $pathTransitionsFromSteps += $attributed.counts.previous_only_path_count + $attributed.counts.next_only_path_count
        $anchorTransitionsFromSteps += $attributed.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count
    }
    Check ($pathTransitionsFromSteps -eq $index4.counts.path_presence_transitions_across_adjacent_pairs_count -and
        $anchorTransitionsFromSteps -eq $index4.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -and
        $anchorTransitionsFromSteps -eq $t4.counts.presence_transitions_across_adjacent_pairs_count) 'Path step totals diverged from full path/anchor index or trajectory.'

    # EC-026: cross-step path change recurrence ranks by HOW MANY distinct
    # adjacent steps changed, not by total one-step anchor transitions.
    # A/B/C/D: five changed paths in step 1, one in step 2 and four in
    # step 3. Four paths changed twice, two changed once, none unchanged.
    $profile3 = $index3.change_profile
    Check ($profile3.counts.distinct_saved_path_count -eq 5 -and
        $profile3.counts.paths_with_any_changed_step_count -eq 5 -and
        $profile3.counts.paths_changed_in_multiple_steps_count -eq 1 -and
        $profile3.counts.changed_path_step_occurrences -eq 6 -and
        $profile3.changed_step_count_distribution.Count -eq 3 -and
        $profile3.changed_step_count_distribution[0].saved_path_count -eq 0 -and
        $profile3.changed_step_count_distribution[1].saved_path_count -eq 4 -and
        $profile3.changed_step_count_distribution[2].saved_path_count -eq 1) 'Three-record change profile double-counted paths or clipped step frequencies.'
    Check ($profile3.hotspots.Count -eq 1 -and
        $profile3.hotspots[0].path -ceq 'src/B.txt' -and
        $profile3.hotspots[0].changed_step_count -eq 2 -and
        $profile3.hotspots[0].longest_consecutive_changed_step_run -eq 2 -and
        $profile3.hotspots[0].changes_in_caller_order[0].step -eq 1 -and
        $profile3.hotspots[0].changes_in_caller_order[1].step -eq 2 -and
        $profile3.hotspots[0].changes_in_caller_order[0].kind -ceq 'started_reporting' -and
        $profile3.hotspots[0].changes_in_caller_order[1].kind -ceq 'stopped_reporting' -and
        $profile3.omitted_hotspots -eq 4 -and $profile3.hotspots_truncated) 'Repeated-step ranking, consecutive runs, kind or exact clipping is wrong.'
    $profile4 = $index4.change_profile
    Check ($profile4.adjacent_step_count -eq 3 -and
        $profile4.counts.distinct_saved_path_count -eq 6 -and
        $profile4.counts.paths_with_any_changed_step_count -eq 6 -and
        $profile4.counts.paths_changed_in_multiple_steps_count -eq 4 -and
        $profile4.counts.paths_changed_in_every_adjacent_step_count -eq 0 -and
        $profile4.counts.changed_path_step_occurrences -eq 10 -and
        $profile4.counts.path_presence_transition_step_occurrences -eq 8 -and
        $profile4.counts.anchor_churn_path_step_occurrences -eq 8 -and
        $profile4.counts.retained_severity_changed_path_step_occurrences -eq 2 -and
        $profile4.counts.retained_severity_only_path_step_occurrences -eq 2 -and
        $profile4.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 8) 'Four-record profile failed full step / severity-only / anchor accounting.'
    Check ($profile4.changed_step_count_distribution.Count -eq 4 -and
        $profile4.changed_step_count_distribution[0].saved_path_count -eq 0 -and
        $profile4.changed_step_count_distribution[1].saved_path_count -eq 2 -and
        $profile4.changed_step_count_distribution[2].saved_path_count -eq 4 -and
        $profile4.changed_step_count_distribution[3].saved_path_count -eq 0 -and
        $profile4.hotspots.Count -eq 1 -and
        $profile4.hotspots[0].path -ceq 'src/A.txt' -and
        $profile4.hotspots[0].presence_pattern -ceq '1001' -and
        $profile4.hotspots[0].changed_step_count -eq 2 -and
        $profile4.hotspots[0].longest_consecutive_changed_step_run -eq 1 -and
        $profile4.hotspots[0].changes_in_caller_order.Count -eq 2 -and
        $profile4.hotspots[0].changes_in_caller_order[0].step -eq 1 -and
        $profile4.hotspots[0].changes_in_caller_order[1].step -eq 3 -and
        $profile4.omitted_hotspots -eq 5 -and $profile4.hotspots_truncated) 'Path change histogram, top ranking or nonconsecutive change steps are wrong.'
    $profileWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",'-SequenceTop','20')
    Check ($profileWide.data.path_index.change_profile.hotspots.Count -eq 6 -and
        $profileWide.data.path_index.change_profile.omitted_hotspots -eq 0 -and
        -not $profileWide.data.path_index.change_profile.hotspots_truncated -and
        $profileWide.data.path_index.change_profile.hotspots[3].path -ceq 'file Ω.txt' -and
        $profileWide.data.path_index.change_profile.hotspots[3].anchor_churn_step_count -eq 0 -and
        $profileWide.data.path_index.change_profile.hotspots[3].retained_severity_only_step_count -eq 2 -and
        $profileWide.data.path_index.change_profile.hotspots[3].changes_in_caller_order[0].kind -ceq 'retained_severity_only' -and
        $profileWide.data.path_index.change_profile.hotspots[3].changes_in_caller_order[1].step -eq 3) 'The full path hotspot ranking dropped repeated severity-only reports.'

    # A path first reported at D was absent from both A and B/C. It must
    # not be misclassified as a compared-only path for the A/B or A/C pair.
    $p4Wide = $profileWide.data.baseline_drift.path_persistence
    $newAtLast = @($p4Wide.hotspots | Where-Object { $_.path -ceq 'src/Z.txt' })
    Check ($p4Wide.counts.distinct_saved_path_union_count -eq 6 -and
        $p4Wide.counts.deviating_path_position_occurrences -eq 13 -and
        $p4Wide.comparison_totals[0].changed_path_count -eq 5 -and
        $p4Wide.comparison_totals[1].changed_path_count -eq 4 -and
        $p4Wide.comparison_totals[2].changed_path_count -eq 4 -and
        $p4Wide.hotspots.Count -eq 6 -and
        $newAtLast.Count -eq 1 -and
        $newAtLast[0].reporting_pattern -ceq '0001' -and
        $newAtLast[0].deviation_from_baseline_pattern -ceq '0001' -and
        $newAtLast[0].compared_positions_in_caller_order[0].profile_deviates_from_baseline -eq $false -and
        $newAtLast[0].compared_positions_in_caller_order[1].profile_deviates_from_baseline -eq $false -and
        $newAtLast[0].compared_positions_in_caller_order[2].profile_deviates_from_baseline -eq $true) 'Later-only path must not contaminate earlier baseline pair counts.'

    # EC-023: a path focus must be an independent, exact, case-sensitive
    # projection, leaving every unfiltered total and step unchanged.
    $aFocus = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",'-SequenceTop','1',
        '-SequencePath','src/A.txt')
    $focused = $aFocus.data.path_focus
    Check ($focused.path -ceq 'src/A.txt' -and $focused.path_found_in_selected_records -and
        $focused.matching_record_count -eq 2 -and $focused.matching_finding_statement_count -eq 2) 'Focus lost exact case-sensitive path membership.'
    Check ($focused.record_summaries.Count -eq 4 -and
        $focused.record_summaries[0].matching_exact_anchor_count -eq 1 -and
        $focused.record_summaries[1].matching_exact_anchor_count -eq 0 -and
        $focused.record_summaries[2].matching_exact_anchor_count -eq 0 -and
        $focused.record_summaries[3].matching_exact_anchor_count -eq 1) 'Focused per-record counts are not ordinal and path-exact.'
    Check ($focused.steps.Count -eq 3 -and
        $focused.steps[0].counts.previous_only_exact_anchor_count -eq 1 -and
        $focused.steps[1].counts.retained_exact_anchor_count -eq 0 -and
        $focused.steps[2].counts.next_only_exact_anchor_count -eq 1 -and
        $focused.steps[0].previous_finding_statement_count -eq 1 -and
        $focused.steps[0].next_finding_statement_count -eq 0) 'Focused deltas or Finding statement counts include other paths.'
    # EC-033: path drilldown is COMPLETE even though Top=1 ranks this
    # literal path below a globally different changing-path hotspot.
    $fj = $focused.profile_journey
    Check ($fj.path -ceq 'src/A.txt' -and $fj.path_found_in_selected_records -and
        $fj.independent_of_sequence_top -and -not $fj.included_in_global_transition_hotspots -and
        $fj.counts.reporting_position_count -eq 2 -and
        $fj.counts.unreported_position_count -eq 2 -and
        $fj.counts.distinct_profile_class_count -eq 3 -and
        $fj.counts.profile_transition_count -eq 2 -and
        $fj.counts.profile_run_count -eq 3 -and
        $fj.counts.return_to_prior_profile_count -eq 0 -and
        $fj.counts.reported_after_unreported_gap_count -eq 1 -and
        ($fj.position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,2,3') 'EC-033 lost omitted-path profile class transitions or miscounted a different-profile return.'
    Check ($fj.profile_classes.Count -eq 3 -and
        $fj.profile_classes[0].representative_record_id -ceq $aId -and
        $fj.profile_classes[0].severity_statement_counts.high -eq 1 -and
        $fj.profile_classes[1].path_reported -eq $false -and
        ($fj.profile_classes[1].positions -join ',') -ceq '2,3' -and
        ($fj.profile_classes[1].record_ids -join ',') -ceq "$bId,$cId" -and
        $fj.profile_classes[2].representative_record_id -ceq $dId -and
        $fj.profile_classes[2].severity_statement_counts.medium -eq 1 -and
        $fj.position_profile_classes[2].exact_anchor_count -eq 0 -and
        $fj.profile_runs[1].start_position -eq 2 -and
        $fj.profile_runs[1].end_position -eq 3 -and
        $fj.transition_events.Count -eq 2 -and
        $fj.transition_events[1].transition_kind -ceq 'became_reported' -and
        $fj.transition_events[1].reported_after_unreported_gap -and
        -not $fj.transition_events[1].returns_to_prior_profile) 'EC-033 class members, full absence runs or saved-severity distinctions were truncated.'
    # EC-034: the exact saved quote-anchor behind src/A is complete even
    # though the path is omitted from the global Top=1 profile hotspot.
    $anchorA = $focused.anchor_journeys
    Check ($anchorA.path -ceq 'src/A.txt' -and $anchorA.independent_of_sequence_top -and
        $anchorA.counts.distinct_exact_anchor_union_count -eq 1 -and
        $anchorA.counts.finding_statement_occurrences -eq 2 -and
        $anchorA.counts.reappeared_after_at_least_one_unreported_position_count -eq 1 -and
        $anchorA.counts.severity_distribution_varied_across_reported_positions_count -eq 1 -and
        $anchorA.counts.presence_transitions_across_adjacent_pairs_count -eq 2 -and
        $anchorA.counts.retained_severity_histogram_transition_count -eq 0 -and
        $anchorA.anchors.Count -eq 1 -and
        $anchorA.anchors[0].presence_pattern -ceq '1001' -and
        $anchorA.anchors[0].presence_runs.Count -eq 3 -and
        $anchorA.anchors[0].transition_events.Count -eq 2 -and
        $anchorA.anchors[0].transition_events[1].reported_after_unreported_gap -and
        $anchorA.anchors[0].observations_in_caller_order[0].severity_statement_counts.high -eq 1 -and
        $anchorA.anchors[0].observations_in_caller_order[1].severity_statement_counts -eq $null -and
        $anchorA.anchors[0].observations_in_caller_order[3].severity_statement_counts.medium -eq 1 -and
        $anchorA.reporting_record_count_distribution[1].distinct_exact_anchor_count -eq 1) 'EC-034 lost full presence, gap return, severity and statement history of an omitted path anchor.'
    $gapCohorts = $focused.anchor_cohorts
    Check ($gapCohorts.path -ceq 'src/A.txt' -and $gapCohorts.independent_of_sequence_top -and
        $gapCohorts.counts.distinct_presence_pattern_cohort_count -eq 1 -and
        $gapCohorts.counts.reappeared_after_gap_exact_anchor_count -eq 1 -and
        $gapCohorts.counts.severity_varied_exact_anchor_count -eq 1 -and
        $gapCohorts.cohorts[0].presence_pattern -ceq '1001' -and
        $gapCohorts.cohorts[0].lifecycle_shape -ceq 'reappeared_after_gap' -and
        ($gapCohorts.cohorts[0].anchor_indices_in_anchor_journeys -join ',') -ceq '1' -and
        $gapCohorts.cohorts[0].observations_in_caller_order[3].severity_statement_counts.medium -eq 1 -and
        $gapCohorts.adjacent_step_totals[0].previous_only_exact_anchor_count -eq 1 -and
        $gapCohorts.adjacent_step_totals[2].next_only_exact_anchor_count -eq 1 -and
        $gapCohorts.counts.retained_severity_histogram_transition_count -eq 0) 'EC-035 lost gap-group presence and nonadjacent severity variation.'
    $aFocusWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",
        '-SequenceTop','20','-SequencePath','src/A.txt')
    $fjWide = $aFocusWide.data.path_focus.profile_journey
    Check ($fjWide.included_in_global_transition_hotspots -and
        ($fjWide.profile_classes | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($fj.profile_classes | ConvertTo-Json -Depth 32 -Compress) -and
        ($fjWide.position_profile_classes | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($fj.position_profile_classes | ConvertTo-Json -Depth 32 -Compress) -and
        ($fjWide.profile_runs | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($fj.profile_runs | ConvertTo-Json -Depth 32 -Compress) -and
        ($fjWide.transition_events | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($fj.transition_events | ConvertTo-Json -Depth 32 -Compress) -and
        ($aFocusWide.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($profileWide.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress)) 'EC-033 changing Top 1 to 20 altered focused membership/runs/events or the complete global pairwise profile.'
    Check (($aFocusWide.data.path_focus.anchor_journeys | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($anchorA | ConvertTo-Json -Depth 32 -Compress)) 'EC-034 focused exact-anchor histories depend on SequenceTop.'
    Check (($aFocusWide.data.path_focus.anchor_cohorts | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($gapCohorts | ConvertTo-Json -Depth 32 -Compress)) 'EC-035 cohorts depend on SequenceTop.'
    $ft = $focused.anchor_trajectory
    Check ($ft.scope -eq 'exact_path_within_selected_records_in_caller_order_not_time' -and
        $ft.counts.distinct_exact_anchor_union_count -eq 1 -and
        $ft.counts.reappeared_after_at_least_one_unreported_position_count -eq 1 -and
        $ft.counts.presence_transitions_across_adjacent_pairs_count -eq 2 -and
        $ft.counts.severity_distribution_varied_across_reported_positions_count -eq 1 -and
        $ft.previews.reappeared_after_gap[0].presence_pattern -ceq '1001') 'Focused trajectory did not reuse full exact-anchor semantics.'
    Check (($aFocus.data.path_index | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($trajectoryFour.data.path_index | ConvertTo-Json -Depth 32 -Compress)) 'Path selector changed the full path index or its ordinal path ordering.'
    Check ($aFocus.data.steps[0].counts.previous_only_exact_anchor_count -eq
        $trajectoryFour.data.steps[0].counts.previous_only_exact_anchor_count -and
        $aFocus.data.anchor_trajectory.counts.distinct_exact_anchor_union_count -eq 6 -and
        $aFocus.data.record_summaries[0].finding_statement_count -eq 4) 'Path focus changed the unfiltered Sequence contract.'
    $lower = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",'-SequencePath','src/a.txt')
    Check ($lower.data.path_focus.matching_record_count -eq 2 -and
        $lower.data.path_focus.anchor_trajectory.counts.reappeared_after_at_least_one_unreported_position_count -eq 0 -and
        $lower.data.path_focus.record_summaries[0].matching_exact_anchor_count -eq 0) 'Case-insensitive path matching changed exact anchor groups.'
    $lowerJourney = $lower.data.path_focus.profile_journey
    Check ($lowerJourney.path -ceq 'src/a.txt' -and
        $lowerJourney.counts.reporting_position_count -eq 2 -and
        $lowerJourney.counts.distinct_profile_class_count -eq 2 -and
        $lowerJourney.counts.profile_transition_count -eq 2 -and
        $lowerJourney.counts.return_to_unreported_profile_count -eq 1 -and
        $lowerJourney.counts.reported_after_unreported_gap_count -eq 0 -and
        ($lowerJourney.position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,2,1' -and
        $lowerJourney.transition_events[1].returns_to_unreported_profile) 'EC-033 exact-case focus mistook an unreported-class return for a reported defect return.'
    Check ($lower.data.path_focus.anchor_journeys.anchors.Count -eq 1 -and
        $lower.data.path_focus.anchor_journeys.anchors[0].presence_pattern -ceq '0110' -and
        $lower.data.path_focus.anchor_journeys.counts.presence_transitions_across_adjacent_pairs_count -eq 2) 'EC-034 case-sensitive source path must not absorb uppercase anchors.'
    $lowerRefs = $lower.data.path_focus.anchor_finding_refs
    Check ($lowerRefs.anchors.Count -eq 1 -and
        ($lowerRefs.positions | ForEach-Object { $_.finding_statement_count }) -join ',' -ceq '0,1,1,0' -and
        ($lowerRefs.anchors[0].references_in_caller_order | ForEach-Object { $_.position }) -join ',' -ceq '2,3' -and
        $lowerRefs.counts.finding_reference_occurrences -eq 2) 'EC-039 collapsed case-distinct saved paths or lost selected report positions.' 
    $overlap = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",'-SequencePath','file Ω.txt')
    Check ($overlap.data.path_focus.matching_record_count -eq 4 -and
        $overlap.data.path_focus.matching_finding_statement_count -eq 5 -and
        $overlap.data.path_focus.anchor_trajectory.counts.reported_in_every_record_count -eq 1 -and
        $overlap.data.path_focus.record_summaries[0].matching_finding_statement_count -eq 2 -and
        $overlap.data.path_focus.anchor_trajectory.previews.reported_in_every_record[0].observations_in_caller_order[0].severity_counts.info -eq 1 -and
        $overlap.data.path_focus.anchor_trajectory.previews.reported_in_every_record[0].observations_in_caller_order[0].severity_counts.high -eq 1) 'Focused matching statements were incorrectly deduplicated.'
    $multi = $overlap.data.path_focus.profile_journey
    Check ($multi.counts.finding_statement_occurrences -eq 5 -and
        $multi.counts.reporting_position_count -eq 4 -and
        $multi.position_profile_classes[0].exact_anchor_count -eq 1 -and
        $multi.position_profile_classes[0].finding_statement_count -eq 2 -and
        $multi.position_profile_classes[0].severity_statement_counts.info -eq 1 -and
        $multi.position_profile_classes[0].severity_statement_counts.high -eq 1 -and
        $multi.position_profile_classes[1].finding_statement_count -eq 1) 'EC-033 flattened Finding-statement multiplicity within one exact saved anchor.'
    $multiAnchors = $overlap.data.path_focus.anchor_journeys
    Check ($multiAnchors.anchors.Count -eq 1 -and
        $multiAnchors.counts.reported_exact_anchor_position_occurrences -eq 4 -and
        $multiAnchors.counts.finding_statement_occurrences -eq 5 -and
        $multiAnchors.counts.retained_severity_histogram_transition_count -eq 2 -and
        $multiAnchors.anchors[0].presence_pattern -ceq '1111' -and
        $multiAnchors.anchors[0].presence_runs.Count -eq 1 -and
        $multiAnchors.anchors[0].transition_events.Count -eq 2 -and
        $multiAnchors.anchors[0].observations_in_caller_order[0].finding_statement_count -eq 2 -and
        $multiAnchors.position_totals[0].severity_statement_counts.info -eq 1 -and
        $multiAnchors.position_totals[0].severity_statement_counts.high -eq 1) 'EC-034 incorrectly deduplicated two saved Finding statements on one Unicode-path anchor.'
    $unicodeRefs = $overlap.data.path_focus.anchor_finding_refs
    Check ($unicodeRefs.anchors.Count -eq 1 -and $unicodeRefs.positions.Count -eq 4 -and
        $unicodeRefs.counts.finding_reference_occurrences -eq 5 -and
        $unicodeRefs.counts.reported_exact_anchor_position_occurrences -eq 4 -and
        $unicodeRefs.positions[0].finding_statement_count -eq 2 -and
        $unicodeRefs.positions[0].finding_refs[0].finding_id -ceq 'F1' -and
        $unicodeRefs.positions[0].finding_refs[0].severity -ceq 'info' -and
        $unicodeRefs.positions[0].finding_refs[1].finding_id -ceq 'F2' -and
        $unicodeRefs.positions[0].finding_refs[1].severity -ceq 'high' -and
        $unicodeRefs.anchors[0].references_in_caller_order[0].finding_refs.Count -eq 2 -and
        $unicodeRefs.positions[3].record_id -ceq $dId) 'EC-039 collapsed duplicate statements on a single Unicode-path anchor.'
    $unicodePairRefs = $overlap.data.path_focus.anchor_pair_finding_refs
    Check ($unicodePairRefs.pair_count -eq 6 -and
        $unicodePairRefs.pairs[0].changed_anchors.Count -eq 1 -and
        $unicodePairRefs.pairs[0].changed_anchors[0].contrast_kind -ceq 'retained_changed_severity' -and
        $unicodePairRefs.pairs[0].changed_anchors[0].left_finding_refs.Count -eq 2 -and
        ($unicodePairRefs.pairs[0].changed_anchors[0].left_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $unicodePairRefs.pairs[0].changed_anchors[0].right_finding_refs.Count -eq 1 -and
        $unicodePairRefs.pairs[0].changed_anchors[0].severity_statement_delta.info -eq -1) 'EC-040 discarded a second saved Finding on one Unicode-path exact anchor.'
    $unicodeFindingPairs = $overlap.data.path_focus.finding_pair_lookup
    Check ($unicodeFindingPairs.positions.Count -eq 4 -and
        $unicodeFindingPairs.counts.original_finding_reference_count -eq 5 -and
        $unicodeFindingPairs.counts.complete_finding_pair_incidence_count -eq 15 -and
        $unicodeFindingPairs.pairs[0].changed_left_finding_pair_incidence_count -eq 2 -and
        $unicodeFindingPairs.pairs[0].changed_right_finding_pair_incidence_count -eq 1 -and
        $unicodeFindingPairs.positions[0].finding_refs[0].anchor_index_in_anchor_journeys -eq 1 -and
        $unicodeFindingPairs.positions[0].finding_refs[1].anchor_index_in_anchor_journeys -eq 1) 'EC-041 collapsed repeated original Findings at one Unicode-path exact quote anchor.'
    # EC-042: a seed Finding on a Unicode literal path must not collapse the
    # second original ID attached to its identical six-field quote anchor.
    $unicodeSelected = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",
        '-SequencePath','file Ω.txt',
        '-SequenceFindingRecordId',$aId,'-SequenceFindingId','F2')
    $unicodeSelectedAnchor = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",
        '-SequencePath','file Ω.txt','-SequenceAnchorIndex','1')
    Check ($unicodeSelectedAnchor.data.path_focus.selected_anchor.counts.reported_position_count -eq 4 -and
        $unicodeSelectedAnchor.data.path_focus.selected_anchor.counts.original_record_scoped_finding_statement_occurrences -eq 5 -and
        ($unicodeSelectedAnchor.data.path_focus.selected_anchor.positions[0].original_record_scoped_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $unicodeSelectedAnchor.data.path_focus.selected_anchor.compared_pairs.Count -eq 6 -and
        ($unicodeSelectedAnchor.data.path_focus.selected_anchor | ConvertTo-Json -Depth 32 -Compress) -notmatch
            'Fixture local text|temporary untracked text|recommended') 'EC-043 Unicode path or same-anchor ID multiplicity leaked text or dropped records.'

    $unicodeSelectedPair = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",
        '-SequencePath','file Ω.txt','-SequencePairIndex','1')
    Check ($unicodeSelectedPair.data.path_focus.selected_pair.anchors.Count -eq 1 -and
        $unicodeSelectedPair.data.path_focus.selected_pair.anchors[0].left.original_record_scoped_finding_refs.Count -eq 2 -and
        ($unicodeSelectedPair.data.path_focus.selected_pair.anchors[0].left.original_record_scoped_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        ($unicodeSelectedPair.data.path_focus.selected_pair | ConvertTo-Json -Depth 32 -Compress) -notmatch
            'Fixture local text|temporary untracked text|recommended') 'EC-044 lost Unicode saved path or multiple original scoped Findings on one anchor.'

    $unicodeSelectedF2 = $unicodeSelected.data.path_focus.selected_finding
    Check ($unicodeSelectedF2.original_position -eq 1 -and
        $unicodeSelectedF2.original_finding_id -ceq 'F2' -and
        $unicodeSelectedF2.anchor_presence_pattern_in_caller_order -ceq '1111' -and
        $unicodeSelectedF2.counts.anchor_reported_position_count -eq 4 -and
        $unicodeSelectedF2.counts.original_record_scoped_finding_statement_occurrences_at_anchor -eq 5 -and
        $unicodeSelectedF2.counts.counterpart_record_scoped_finding_reference_appearances_at_other_positions -eq 3 -and
        $unicodeSelectedF2.compared_pairs.Count -eq 3 -and
        ($unicodeSelectedF2.positions[0].original_record_scoped_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $unicodeSelectedF2.positions[0].saved_finding_statement_count_at_anchor -eq 2 -and
        ($unicodeSelectedF2.positions | ForEach-Object { $_.saved_finding_statement_count_at_anchor }) -join ',' -ceq '2,1,1,1' -and
        ($unicodeSelectedF2 | ConvertTo-Json -Depth 32 -Compress) -notmatch 'Fixture local text|temporary untracked text|recommended') 'EC-042 failed Unicode exact path, multiplicity of IDs on one anchor or non-prose safe focus.'

    # Deliberately reverse the order of saved Findings in one checked record:
    # references must still be sorted by exact Finding ID, and not include
    # saved model prose from the original record's free-text fields.
    $outOfOrder = Clone-Record -Record $a
    $outOfOrder.checked_findings = @(
        $a.checked_findings[1], $a.checked_findings[0],
        $a.checked_findings[2], $a.checked_findings[3])
    $outOfOrder.summary = 'EC039 Finding ordering fixture only.'
    $outOfOrderId = Store-Record -Record $outOfOrder -Folder $store
    $sortedRefView = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$outOfOrderId,$zeroId",'-SequencePath','file Ω.txt')
    $sortedRefs = $sortedRefView.data.path_focus.anchor_finding_refs
    Check ($sortedRefs.positions.Count -eq 2 -and
        ($sortedRefs.positions[0].finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        ($sortedRefs.anchors[0].references_in_caller_order[0].finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $sortedRefs.positions[1].finding_refs.Count -eq 0 -and
        ($sortedRefs | ConvertTo-Json -Depth 32 -Compress) -notmatch 'Fixture local text|temporary untracked text|recommended') 'EC-039 failed deterministic Finding ID order or leaked saved Finding prose.'
 
    $multiCohorts = $overlap.data.path_focus.anchor_cohorts
    Check ($multiCohorts.cohorts.Count -eq 1 -and
        $multiCohorts.cohorts[0].presence_pattern -ceq '1111' -and
        $multiCohorts.cohorts[0].lifecycle_shape -ceq 'every_position' -and
        $multiCohorts.cohorts[0].finding_statement_occurrences -eq 5 -and
        $multiCohorts.cohorts[0].observations_in_caller_order[0].severity_statement_counts.info -eq 1 -and
        $multiCohorts.cohorts[0].observations_in_caller_order[0].severity_statement_counts.high -eq 1 -and
        $multiCohorts.counts.retained_severity_histogram_transition_count -eq 2) 'EC-035 cohort deduplicated same-anchor Finding statements or severity-only events.'
    foreach ($unknownPath in @('SRC/A.txt','src/*','src/missing.txt')) {
        $absent = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
            '-Mode','Sequence','-SequenceRecordIds',"$aId,$bId,$cId,$dId",'-SequencePath',$unknownPath)
        Check (-not $absent.data.path_focus.path_found_in_selected_records -and
            $absent.data.path_focus.matching_record_count -eq 0 -and
            $absent.data.path_focus.anchor_trajectory.counts.distinct_exact_anchor_union_count -eq 0 -and
            $absent.data.path_focus.anchor_trajectory.reporting_record_count_distribution.Count -eq 4 -and
            $absent.data.anchor_trajectory.counts.distinct_exact_anchor_union_count -eq 6) 'Unmatched or wildcard-looking literal path polluted full totals.'
        $notFoundJourney = $absent.data.path_focus.profile_journey
        Check ($notFoundJourney.path -ceq $unknownPath -and
            -not $notFoundJourney.path_found_in_selected_records -and
            -not $notFoundJourney.included_in_global_transition_hotspots -and
            $notFoundJourney.counts.reporting_position_count -eq 0 -and
            $notFoundJourney.counts.unreported_position_count -eq 4 -and
            $notFoundJourney.counts.distinct_profile_class_count -eq 1 -and
            $notFoundJourney.counts.reported_profile_class_count -eq 0 -and
            $notFoundJourney.counts.unreported_profile_class_count -eq 1 -and
            $notFoundJourney.counts.profile_transition_count -eq 0 -and
            $notFoundJourney.counts.profile_run_count -eq 1 -and
            $notFoundJourney.profile_classes[0].member_count -eq 4 -and
            ($notFoundJourney.profile_classes[0].positions -join ',') -ceq '1,2,3,4' -and
            $notFoundJourney.profile_runs[0].length_in_selected_positions -eq 4 -and
            $notFoundJourney.transition_events.Count -eq 0) 'EC-033 no-match path must yield one unreported class/run without inventing global paths.'
        $missingAnchors = $absent.data.path_focus.anchor_journeys
        Check ($missingAnchors.path -ceq $unknownPath -and
            -not $missingAnchors.path_found_in_selected_records -and
            $missingAnchors.counts.distinct_exact_anchor_union_count -eq 0 -and
            $missingAnchors.counts.finding_statement_occurrences -eq 0 -and
            $missingAnchors.counts.anchor_transition_event_count -eq 0 -and
            $missingAnchors.anchors.Count -eq 0 -and
            $missingAnchors.position_totals.Count -eq 4 -and
            $missingAnchors.adjacent_step_totals.Count -eq 3 -and
            $missingAnchors.reporting_record_count_distribution.Count -eq 4 -and
            $missingAnchors.reporting_record_count_distribution[0].distinct_exact_anchor_count -eq 0) 'EC-034 no-match path generated fictitious exact anchors, changes or support.'
        $noCohorts = $absent.data.path_focus.anchor_cohorts
        Check ($noCohorts.cohorts.Count -eq 0 -and
            $noCohorts.counts.distinct_presence_pattern_cohort_count -eq 0 -and
            $noCohorts.counts.finding_statement_occurrences -eq 0 -and
            $noCohorts.position_totals.Count -eq 4 -and
            $noCohorts.position_totals[0].reported_exact_anchor_count -eq 0 -and
            $noCohorts.adjacent_step_totals.Count -eq 3) 'EC-035 invented a cohort for an unreported literal saved path.'

        $noPairs = $absent.data.path_focus.anchor_pairwise
        Check ($noPairs.pair_count -eq 6 -and $noPairs.pairs.Count -eq 6 -and
            $noPairs.anchor_pair_frequencies.Count -eq 0 -and
            $noPairs.counts.identical_saved_path_profile_pair_count -eq 6 -and
            $noPairs.counts.both_unreported_path_pair_count -eq 6 -and
            $noPairs.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 0 -and
            $noPairs.counts.shared_anchor_with_internal_unreported_position_pair_occurrences -eq 0 -and
            ($noPairs.caller_distance_distribution | ForEach-Object { $_.compared_pair_count }) -join ',' -ceq '3,2,1' -and
            $noPairs.pairs[5].left_position -eq 3 -and $noPairs.pairs[5].right_position -eq 4 -and
            $noPairs.pairs[5].same_saved_path_profile -and
            $noPairs.pairs[5].both_unreported_path) 'EC-036 unreported literal path must still yield complete empty pair comparisons.' 
        $noDetails = $absent.data.path_focus.anchor_pair_details
        Check (-not $noDetails.path_found_in_selected_records -and
            $noDetails.pair_count -eq 6 -and $noDetails.pairs.Count -eq 6 -and
            $noDetails.ranked_pairs.Count -eq 6 -and
            $noDetails.counts.different_saved_path_profile_pair_count -eq 0 -and
            $noDetails.counts.left_only_anchor_pair_occurrences -eq 0 -and
            $noDetails.counts.shared_cross_gap_and_severity_changed_anchor_pair_occurrences -eq 0 -and
            $noDetails.pairs[0].left_only_anchor_indices.Count -eq 0 -and
            $noDetails.pairs[0].retained_changed_severity_anchor_indices.Count -eq 0 -and
            $noDetails.pairs[0].both_unreported_anchor_indices.Count -eq 0 -and
            $noDetails.pairs[0].finding_statement_count_delta -eq 0 -and
            $noDetails.pairs[5].changed_exact_anchor_count -eq 0 -and
            $noDetails.pairs[5].severity_statement_delta_all_reported_anchors.high -eq 0) 'EC-037 no-match or wildcard-looking literal path invented anchors, deltas or changed pairs.'
        $noLookup = $absent.data.path_focus.anchor_pair_lookup
        Check (-not $noLookup.path_found_in_selected_records -and
            $noLookup.pair_count -eq 6 -and
            $noLookup.anchors.Count -eq 0 -and $noLookup.ranked_anchors.Count -eq 0 -and
            $noLookup.counts.distinct_exact_anchor_count -eq 0 -and
            $noLookup.counts.changed_anchor_pair_occurrences -eq 0 -and
            $noLookup.counts.shared_with_internal_unreported_position_anchor_pair_occurrences -eq 0) 'EC-038 fabricated anchor-to-pair members for an absent literal or wildcard-looking saved path.'
        $noRefs = $absent.data.path_focus.anchor_finding_refs
        Check (-not $noRefs.path_found_in_selected_records -and $noRefs.independent_of_sequence_top -and
            $noRefs.anchors.Count -eq 0 -and $noRefs.positions.Count -eq 4 -and
            $noRefs.counts.finding_reference_occurrences -eq 0 -and
            $noRefs.counts.reported_exact_anchor_position_occurrences -eq 0 -and
            ($noRefs.positions | ForEach-Object { $_.finding_statement_count }) -join ',' -ceq '0,0,0,0' -and
            $noRefs.positions[0].finding_refs.Count -eq 0 -and
            $noRefs.positions[3].reported_anchor_indices_in_anchor_journeys.Count -eq 0) 'EC-039 invented Finding references for an absent literal or wildcard-looking path.' 
        $noPairRefs = $absent.data.path_focus.anchor_pair_finding_refs
        Check ($noPairRefs.pair_count -eq 6 -and $noPairRefs.pairs.Count -eq 6 -and
            -not $noPairRefs.path_found_in_selected_records -and
            $noPairRefs.counts.pairs_with_changed_exact_anchor_count -eq 0 -and
            $noPairRefs.counts.changed_finding_reference_occurrences -eq 0 -and
            $noPairRefs.pairs[0].changed_anchors.Count -eq 0 -and
            $noPairRefs.pairs[5].changed_anchors.Count -eq 0) 'EC-040 invented pair Finding ID evidence for a no-match or wildcard-looking literal.'
        $noFindingPairs = $absent.data.path_focus.finding_pair_lookup
        Check (-not $noFindingPairs.path_found_in_selected_records -and
            $noFindingPairs.independent_of_sequence_top -and
            $noFindingPairs.pair_count -eq 6 -and $noFindingPairs.pairs.Count -eq 6 -and
            $noFindingPairs.positions.Count -eq 4 -and
            $noFindingPairs.counts.original_finding_reference_count -eq 0 -and
            $noFindingPairs.counts.complete_finding_pair_incidence_count -eq 0 -and
            $noFindingPairs.counts.changed_anchor_finding_pair_incidence_count -eq 0 -and
            $noFindingPairs.counts.stable_anchor_finding_pair_incidence_count -eq 0 -and
            ($noFindingPairs.positions | ForEach-Object { $_.finding_refs.Count }) -join ',' -ceq '0,0,0,0') 'EC-041 invented Finding-to-pair links for a literal no-match or wildcard-looking requested path.'
    }
    Check (($aFocus.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($trajectoryFour.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress)) 'EC-033 path focus changed global all-pairs classes, transitions or rank ordering.'
    Check ($null -eq $trajectoryFour.data.path_focus) 'Omitted SequencePath unexpectedly activated a path focus.'
    Check (($aFocus.data.baseline_drift | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($trajectoryFour.data.baseline_drift | ConvertTo-Json -Depth 32 -Compress)) 'Optional SequencePath changed full-selection baseline comparisons.'

    # Force preview omissions INSIDE the path-filtered union. All selected
    # bodies and all 3 anchors must still contribute after Top=1 clipping.
    $pathHeavy = Clone-Record -Record $seed
    $pathHeavy.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'focus/README.md' -Sha ('a'*64) -Severity 'info'),
        (New-Finding -Original $orig -Id 'F2' -Path 'focus/README.md' -Sha ('b'*64) -Severity 'high'),
        (New-Finding -Original $orig -Id 'F3' -Path 'focus/README.md' -Sha ('c'*64) -Severity 'critical')
    ); $pathHeavy.finding_count = 3; $pathHeavy.summary = 'Three distinct saved anchors under one historical path.'
    $pathHeavyId = Store-Record -Record $pathHeavy -Folder $store
    $clipped = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$pathHeavyId,$bId",'-SequenceTop','1',
        '-SequencePath','focus/README.md')
    Check ($clipped.data.path_focus.matching_finding_statement_count -eq 3 -and
        $clipped.data.path_focus.steps[0].counts.previous_only_exact_anchor_count -eq 3 -and
        $clipped.data.path_focus.steps[0].omitted_previews.previous_only -eq 2 -and
        $clipped.data.path_focus.steps[0].previews.previous_only.Count -eq 1 -and
        $clipped.data.path_focus.anchor_trajectory.counts.distinct_exact_anchor_union_count -eq 3 -and
        $clipped.data.path_focus.anchor_trajectory.omitted_previews.reported_once -eq 2 -and
        $clipped.data.path_focus.anchor_trajectory.previews_truncated) 'Focused preview caps reduced counted anchors or misreported omissions.'
    $clippedJourney = $clipped.data.path_focus.profile_journey
    Check ($clippedJourney.counts.reporting_position_count -eq 1 -and
        $clippedJourney.position_profile_classes[0].exact_anchor_count -eq 3 -and
        $clippedJourney.position_profile_classes[0].finding_statement_count -eq 3 -and
        $clippedJourney.counts.profile_transition_count -eq 1 -and
        $clippedJourney.transition_events[0].previous_only_exact_anchor_count -eq 3 -and
        $clippedJourney.profile_classes.Count -eq 2 -and
        $clippedJourney.profile_classes[0].exact_anchor_count -eq 3) 'EC-033 focused profile lost anchors when other preview categories were clipped.'
    $heavyAnchors = $clipped.data.path_focus.anchor_journeys
    Check ($heavyAnchors.anchors.Count -eq 3 -and
        $heavyAnchors.counts.finding_statement_occurrences -eq 3 -and
        $heavyAnchors.counts.presence_transitions_across_adjacent_pairs_count -eq 3 -and
        $heavyAnchors.counts.anchor_transition_event_count -eq 3 -and
        $heavyAnchors.position_totals[0].reported_exact_anchor_count -eq 3 -and
        $heavyAnchors.position_totals[1].reported_exact_anchor_count -eq 0 -and
        $heavyAnchors.reporting_record_count_distribution[0].distinct_exact_anchor_count -eq 3 -and
        $heavyAnchors.anchors[0].presence_pattern -ceq '10' -and
        $heavyAnchors.anchors[1].presence_pattern -ceq '10' -and
        $heavyAnchors.anchors[2].presence_pattern -ceq '10' -and
        $heavyAnchors.anchors[2].transition_events[0].transition_kind -ceq 'became_unreported') 'EC-034 lost two of three exact anchors because old trajectory previews were clipped to Top=1.'
    $heavyCohorts = $clipped.data.path_focus.anchor_cohorts
    Check ($heavyCohorts.cohorts.Count -eq 1 -and
        $heavyCohorts.cohorts[0].presence_pattern -ceq '10' -and
        $heavyCohorts.cohorts[0].distinct_exact_anchor_count -eq 3 -and
        ($heavyCohorts.cohorts[0].anchor_indices_in_anchor_journeys -join ',') -ceq '1,2,3' -and
        $heavyCohorts.cohorts[0].observations_in_caller_order[0].finding_statement_count -eq 3 -and
        $heavyCohorts.adjacent_step_totals[0].previous_only_exact_anchor_count -eq 3) 'EC-035 cohorts clipped or double-counted three same-pattern exact anchors.'

    $heavyPairs = $clipped.data.path_focus.anchor_pairwise
    Check ($heavyPairs.pair_count -eq 1 -and
        $heavyPairs.pairs[0].left_only_exact_anchor_count -eq 3 -and
        $heavyPairs.pairs[0].right_only_exact_anchor_count -eq 0 -and
        $heavyPairs.pairs[0].retained_exact_anchor_count -eq 0 -and
        $heavyPairs.counts.zero_shared_anchor_nonempty_union_pair_count -eq 1 -and
        $heavyPairs.anchor_pair_frequencies.Count -eq 3 -and
        ($heavyPairs.anchor_pair_frequencies | ForEach-Object { $_.contrasting_reported_unreported_pair_count }) -join ',' -ceq '1,1,1') 'EC-036 counted only visible Top=1 anchor previews instead of all three checked anchors.'
    $heavyDetails = $clipped.data.path_focus.anchor_pair_details
    Check ($heavyDetails.pair_count -eq 1 -and
        ($heavyDetails.pairs[0].left_only_anchor_indices -join ',') -ceq '1,2,3' -and
        $heavyDetails.pairs[0].right_only_anchor_indices.Count -eq 0 -and
        $heavyDetails.pairs[0].retained_changed_severity_anchor_indices.Count -eq 0 -and
        $heavyDetails.pairs[0].changed_exact_anchor_count -eq 3 -and
        $heavyDetails.pairs[0].left_only_finding_statement_count -eq 3 -and
        $heavyDetails.pairs[0].severity_statement_delta_all_reported_anchors.info -eq -1 -and
        $heavyDetails.pairs[0].severity_statement_delta_all_reported_anchors.high -eq -1 -and
        $heavyDetails.pairs[0].severity_statement_delta_all_reported_anchors.critical -eq -1) 'EC-037 lost hidden Top=1 left-only anchors or the signed severity delta.'
    $heavyLookup = $clipped.data.path_focus.anchor_pair_lookup
    Check ($heavyLookup.anchors.Count -eq 3 -and
        ($heavyLookup.ranked_anchors | ForEach-Object { $_.anchor_index_in_anchor_journeys }) -join ',' -ceq '1,2,3' -and
        ($heavyLookup.anchors | ForEach-Object { $_.changed_pair_count }) -join ',' -ceq '1,1,1' -and
        ($heavyLookup.anchors[2].left_only_pair_indices -join ',') -ceq '1' -and
        $heavyLookup.anchors[2].retained_changed_severity_events.Count -eq 0) 'EC-038 inverted only the Top=1 preview instead of all three exact anchors.'
    $heavyRefs = $clipped.data.path_focus.anchor_finding_refs
    Check ($heavyRefs.independent_of_sequence_top -and
        $heavyRefs.anchors.Count -eq 3 -and $heavyRefs.positions.Count -eq 2 -and
        $heavyRefs.counts.finding_reference_occurrences -eq 3 -and
        $heavyRefs.counts.reported_exact_anchor_position_occurrences -eq 3 -and
        ($heavyRefs.positions[0].reported_anchor_indices_in_anchor_journeys -join ',') -ceq '1,2,3' -and
        ($heavyRefs.positions[0].finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2,F3' -and
        $heavyRefs.positions[1].finding_refs.Count -eq 0 -and
        $heavyRefs.anchors[2].references_in_caller_order[0].finding_refs.Count -eq 1) 'EC-039 Finding references omitted Top-clipped anchors or a zero-Finding selected report.' 

    # EC-035: multiple simultaneous exact presence cohorts in caller order.
    # A:1111, B/E:1001 (B changes severity only across the reporting gap),
    # C:0100, D:0110. Only the complete saved-Finding evidence is grouped.
    $cohortOne = Clone-Record -Record $seed
    $cohortOne.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'cohort/path.ps1' -Sha ('1'*64) -Severity 'info'),
        (New-Finding -Original $orig -Id 'F2' -Path 'cohort/path.ps1' -Sha ('2'*64) -Severity 'high'),
        (New-Finding -Original $orig -Id 'F3' -Path 'cohort/path.ps1' -Sha ('5'*64) -Severity 'low')
    ); $cohortOne.finding_count = 3; $cohortOne.summary = 'Cohort fixture position one.'
    $cohortOneId = Store-Record -Record $cohortOne -Folder $store
    $cohortTwo = Clone-Record -Record $seed
    $cohortTwo.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'cohort/path.ps1' -Sha ('1'*64) -Severity 'info'),
        (New-Finding -Original $orig -Id 'F2' -Path 'cohort/path.ps1' -Sha ('3'*64) -Severity 'critical'),
        (New-Finding -Original $orig -Id 'F3' -Path 'cohort/path.ps1' -Sha ('4'*64) -Severity 'medium')
    ); $cohortTwo.finding_count = 3; $cohortTwo.summary = 'Cohort fixture position two.'
    $cohortTwoId = Store-Record -Record $cohortTwo -Folder $store
    $cohortThree = Clone-Record -Record $seed
    $cohortThree.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'cohort/path.ps1' -Sha ('1'*64) -Severity 'info'),
        (New-Finding -Original $orig -Id 'F2' -Path 'cohort/path.ps1' -Sha ('4'*64) -Severity 'medium')
    ); $cohortThree.finding_count = 2; $cohortThree.summary = 'Cohort fixture position three.'
    $cohortThreeId = Store-Record -Record $cohortThree -Folder $store
    $cohortFour = Clone-Record -Record $seed
    $cohortFour.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'cohort/path.ps1' -Sha ('1'*64) -Severity 'info'),
        (New-Finding -Original $orig -Id 'F2' -Path 'cohort/path.ps1' -Sha ('2'*64) -Severity 'medium'),
        (New-Finding -Original $orig -Id 'F3' -Path 'cohort/path.ps1' -Sha ('5'*64) -Severity 'low')
    ); $cohortFour.finding_count = 3; $cohortFour.summary = 'Cohort fixture position four.'
    $cohortFourId = Store-Record -Record $cohortFour -Folder $store
    $cohortView = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequenceTop','1','-SequencePath','cohort/path.ps1')
    $cohorts = $cohortView.data.path_focus.anchor_cohorts
    Check ($cohorts.counts.distinct_presence_pattern_cohort_count -eq 4 -and
        $cohorts.counts.distinct_exact_anchor_union_count -eq 5 -and
        $cohorts.counts.reported_exact_anchor_position_occurrences -eq 11 -and
        $cohorts.counts.finding_statement_occurrences -eq 11 -and
        $cohorts.counts.every_position_exact_anchor_count -eq 1 -and
        $cohorts.counts.one_position_exact_anchor_count -eq 1 -and
        $cohorts.counts.contiguous_partial_exact_anchor_count -eq 1 -and
        $cohorts.counts.reappeared_after_gap_exact_anchor_count -eq 2 -and
        $cohorts.counts.severity_varied_exact_anchor_count -eq 1 -and
        $cohorts.counts.presence_transitions_across_adjacent_pairs_count -eq 8 -and
        $cohorts.counts.retained_severity_histogram_transition_count -eq 0) 'EC-035 failed complete 4-pattern partition, shape totals or nonadjacent saved-severity variation.'
    Check (($cohorts.cohorts | ForEach-Object { $_.presence_pattern }) -join ',' -ceq '0100,0110,1001,1111' -and
        ($cohorts.cohorts | ForEach-Object { $_.distinct_exact_anchor_count }) -join ',' -ceq '1,1,2,1' -and
        ($cohorts.cohorts[2].present_positions -join ',') -ceq '1,4' -and
        ($cohorts.cohorts[2].absent_positions -join ',') -ceq '2,3' -and
        $cohorts.cohorts[2].severity_varied_exact_anchor_count -eq 1 -and
        $cohorts.cohorts[2].observations_in_caller_order[0].severity_statement_counts.high -eq 1 -and
        $cohorts.cohorts[2].observations_in_caller_order[3].severity_statement_counts.medium -eq 1 -and
        ($cohorts.position_totals | ForEach-Object { $_.reported_exact_anchor_count }) -join ',' -ceq '3,3,2,3' -and
        ($cohorts.adjacent_step_totals | ForEach-Object { $_.previous_only_exact_anchor_count }) -join ',' -ceq '2,1,1' -and
        ($cohorts.adjacent_step_totals | ForEach-Object { $_.next_only_exact_anchor_count }) -join ',' -ceq '2,0,2') 'EC-035 pattern ordering, cross-group severity multiplicity or step conservation is inconsistent.'
    # EC-042: the caller can pinpoint one ORIGINAL (record ID, Finding ID)
    # and get a single untruncated direct journey with the other reports'
    # actual original scoped IDs (no invented cross-report match).
    $selectedB = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequenceTop','1','-SequencePath','cohort/path.ps1',
        '-SequenceFindingRecordId',$cohortOneId,'-SequenceFindingId','F2')
    $findingB = $selectedB.data.path_focus.selected_finding
    Check ($findingB.original_record_id -ceq $cohortOneId -and
        $findingB.original_position -eq 1 -and $findingB.original_finding_id -ceq 'F2' -and
        $findingB.original_saved_severity -ceq 'high' -and
        $findingB.independent_of_sequence_top -and
        $findingB.anchor_presence_pattern_in_caller_order -ceq '1001' -and
        $findingB.counts.anchor_reported_position_count -eq 2 -and
        $findingB.counts.original_record_scoped_finding_statement_occurrences_at_anchor -eq 2 -and
        $findingB.counts.counterpart_record_scoped_finding_reference_appearances_at_other_positions -eq 1 -and
        $findingB.counts.changed_anchor_pair_count -eq 3 -and
        $findingB.counts.stable_anchor_pair_count -eq 0 -and
        $findingB.counts.pairs_with_internal_unreported_position_count -eq 1 -and
        $findingB.positions.Count -eq 4 -and $findingB.compared_pairs.Count -eq 3 -and
        ($findingB.positions | ForEach-Object { $_.saved_finding_statement_count_at_anchor }) -join ',' -ceq '1,0,0,1' -and
        ($findingB.compared_pairs | ForEach-Object { $_.pair_index }) -join ',' -ceq '1,2,3' -and
        ($findingB.compared_pairs | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq 'left_only,left_only,retained_changed_severity' -and
        $findingB.compared_pairs[2].shared_with_internal_unreported_position -and
        $findingB.compared_pairs[2].counterpart_original_record_scoped_finding_refs[0].finding_id -ceq 'F2' -and
        $findingB.compared_pairs[2].counterpart_original_record_scoped_finding_refs[0].severity -ceq 'medium' -and
        $findingB.compared_pairs[2].counterpart_record_id -cne $cohortOneId) 'EC-042 lost exact-scoped original Finding navigation, gap status, counterpart ID, severity or pair order.'
    Check ($selectedB.data.path_focus.finding_pair_lookup.counts.complete_finding_pair_incidence_count -eq 33 -and
        $selectedB.data.pairwise_profile.pairs.Count -eq $cohortView.data.pairwise_profile.pairs.Count -and
        $null -eq $cohortView.data.path_focus.selected_finding) 'EC-042 targeted Finding changed pre-existing Sequence results or activated without explicit selectors.'

    # EC-043: drill into a canonical anchor regardless of which original
    # record supplied a seed Finding. There are SIX report pairs for four
    # records; pair 4 reports the anchor in NEITHER endpoint (not omitted).
    $selectedAnchorB = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/path.ps1','-SequenceTop','1',
        '-SequenceAnchorIndex',([string]$findingB.anchor_index_in_anchor_journeys))
    $anchorB = $selectedAnchorB.data.path_focus.selected_anchor
    Check ($anchorB.scope -ceq 'one_explicit_canonical_exact_saved_quote_anchor_all_selected_positions_and_all_pairs' -and
        $anchorB.anchor_index_in_anchor_journeys -eq $findingB.anchor_index_in_anchor_journeys -and
        $anchorB.independent_of_sequence_top -and
        $anchorB.anchor_presence_pattern_in_caller_order -ceq '1001' -and
        $anchorB.positions.Count -eq 4 -and $anchorB.compared_pairs.Count -eq 6 -and
        $anchorB.counts.reported_position_count -eq 2 -and
        $anchorB.counts.original_record_scoped_finding_statement_occurrences -eq 2 -and
        $anchorB.counts.left_only_pair_count -eq 2 -and
        $anchorB.counts.right_only_pair_count -eq 2 -and
        $anchorB.counts.retained_same_severity_pair_count -eq 0 -and
        $anchorB.counts.retained_changed_severity_pair_count -eq 1 -and
        $anchorB.counts.both_unreported_pair_count -eq 1 -and
        $anchorB.counts.changed_pair_count -eq 5 -and
        $anchorB.counts.shared_with_internal_unreported_position_pair_count -eq 1 -and
        ($anchorB.compared_pairs | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq
            'left_only,left_only,retained_changed_severity,both_unreported,right_only,right_only' -and
        $anchorB.compared_pairs[2].saved_severity_statement_delta_right_minus_left.high -eq -1 -and
        $anchorB.compared_pairs[2].saved_severity_statement_delta_right_minus_left.medium -eq 1 -and
        $anchorB.compared_pairs[2].shared_with_internal_unreported_position -and
        $anchorB.compared_pairs[3].left_saved_finding_statement_count_at_anchor -eq 0 -and
        $anchorB.compared_pairs[3].right_saved_finding_statement_count_at_anchor -eq 0 -and
        $anchorB.positions[0].original_record_scoped_finding_refs[0].severity -ceq 'high' -and
        $anchorB.positions[3].original_record_scoped_finding_refs[0].severity -ceq 'medium') 'EC-043 lost an original ID, a signed delta or one of the six complete pair classes.'
    Check ($null -eq $selectedB.data.path_focus.selected_anchor -and
        $null -eq $cohortView.data.path_focus.selected_anchor -and
        ($selectedAnchorB.data.path_focus.anchor_pair_lookup | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($cohortView.data.path_focus.anchor_pair_lookup | ConvertTo-Json -Depth 32 -Compress) -and
        $null -eq $selectedAnchorB.data.path_focus.selected_finding) 'EC-043 changed the default or prior per-Finding results.'
    $anchorBWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/path.ps1','-SequenceTop','20',
        '-SequenceAnchorIndex',([string]$findingB.anchor_index_in_anchor_journeys))
    Check (($anchorB | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($anchorBWide.data.path_focus.selected_anchor | ConvertTo-Json -Depth 32 -Compress)) 'EC-043 selected anchor details depend on preview Top.'
    $selectedBWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequenceTop','20','-SequencePath','cohort/path.ps1',
        '-SequenceFindingRecordId',$cohortOneId,'-SequenceFindingId','F2')
    Check (($findingB | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($selectedBWide.data.path_focus.selected_finding | ConvertTo-Json -Depth 32 -Compress)) 'EC-042 selected Finding direct navigation was clipped by SequenceTop.'

    $selectedStable = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/path.ps1',
        '-SequenceFindingRecordId',$cohortTwoId,'-SequenceFindingId','F1')
    $stableF1 = $selectedStable.data.path_focus.selected_finding
    Check ($stableF1.original_position -eq 2 -and
        $stableF1.anchor_presence_pattern_in_caller_order -ceq '1111' -and
        $stableF1.counts.changed_anchor_pair_count -eq 0 -and
        $stableF1.counts.stable_anchor_pair_count -eq 3 -and
        $stableF1.counts.counterpart_record_scoped_finding_reference_appearances_at_other_positions -eq 3 -and
        ($stableF1.compared_pairs | ForEach-Object { $_.pair_index }) -join ',' -ceq '1,4,5' -and
        ($stableF1.compared_pairs | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq 'retained_same_severity,retained_same_severity,retained_same_severity' -and
        ($stableF1.compared_pairs | ForEach-Object { $_.counterpart_original_record_scoped_finding_refs[0].finding_id }) -join ',' -ceq 'F1,F1,F1' -and
        -not $stableF1.compared_pairs[0].shared_with_internal_unreported_position) 'EC-042 failed to navigate retained same-histogram evidence or same-ID spelling without matching identity.'

    # EC-044: select one canonical PAIR instead of one anchor or Finding.
    # Pair #3 is (caller positions 1,4), with all five exact anchors:
    # A same, B retained severity changed across two unreported positions,
    # C/D neither reported, E same despite an intermediate reporting gap.
    $selectedPairGap = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequenceTop','1','-SequencePath','cohort/path.ps1','-SequencePairIndex','3')
    $pairGap = $selectedPairGap.data.path_focus.selected_pair
    Check ($pairGap.scope -ceq 'one_explicit_canonical_report_pair_all_exact_saved_quote_anchors' -and
        $pairGap.pair_index_in_anchor_pair_details -eq 3 -and
        $pairGap.left_position -eq 1 -and $pairGap.right_position -eq 4 -and
        $pairGap.left_record_id -ceq $cohortOneId -and
        $pairGap.right_record_id -ceq $cohortFourId -and
        $pairGap.counts.distinct_exact_anchor_union_count -eq 5 -and
        $pairGap.anchors.Count -eq 5 -and
        ($pairGap.anchors | ForEach-Object { $_.anchor_index_in_anchor_journeys }) -join ',' -ceq '1,2,3,4,5' -and
        ($pairGap.anchors | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq
            'retained_same_severity,retained_changed_severity,both_unreported,both_unreported,retained_same_severity' -and
        $pairGap.counts.left_only_anchor_count -eq 0 -and
        $pairGap.counts.right_only_anchor_count -eq 0 -and
        $pairGap.counts.retained_same_severity_anchor_count -eq 2 -and
        $pairGap.counts.retained_changed_severity_anchor_count -eq 1 -and
        $pairGap.counts.both_unreported_anchor_count -eq 2 -and
        $pairGap.counts.changed_anchor_count -eq 1 -and
        $pairGap.counts.shared_with_internal_unreported_position_anchor_count -eq 2 -and
        $pairGap.counts.left_original_finding_statement_count -eq 3 -and
        $pairGap.counts.right_original_finding_statement_count -eq 3 -and
        $pairGap.counts.left_changed_anchor_original_finding_reference_occurrences -eq 1 -and
        $pairGap.counts.right_changed_anchor_original_finding_reference_occurrences -eq 1 -and
        $pairGap.saved_finding_statement_count_delta_right_minus_left -eq 0 -and
        $pairGap.saved_severity_statement_delta_right_minus_left.high -eq -1 -and
        $pairGap.saved_severity_statement_delta_right_minus_left.medium -eq 1 -and
        $pairGap.anchors[1].shared_with_internal_unreported_position -and
        $pairGap.anchors[1].left.original_record_scoped_finding_refs[0].finding_id -ceq 'F2' -and
        $pairGap.anchors[1].left.original_record_scoped_finding_refs[0].severity -ceq 'high' -and
        $pairGap.anchors[1].right.original_record_scoped_finding_refs[0].finding_id -ceq 'F2' -and
        $pairGap.anchors[1].right.original_record_scoped_finding_refs[0].severity -ceq 'medium' -and
        $pairGap.anchors[4].shared_with_internal_unreported_position -and
        -not $pairGap.anchors[4].anchor_changed_in_pair -and
        $pairGap.anchors[2].left.original_record_scoped_finding_refs.Count -eq 0 -and
        $pairGap.anchors[2].right.original_record_scoped_finding_refs.Count -eq 0 -and
        $null -eq $pairGap.anchors[2].left.saved_severity_statement_counts -and
        $pairGap.anchors[2].saved_severity_statement_delta_right_minus_left.info -eq 0) 'EC-044 direct pair projection lost unchanged/unreported anchors, original ID scopes, reporting gaps or signed deltas.'
    Check ($null -eq $selectedPairGap.data.path_focus.selected_anchor -and
        $null -eq $selectedPairGap.data.path_focus.selected_finding -and
        $null -eq $selectedB.data.path_focus.selected_pair -and
        $null -eq $cohortView.data.path_focus.selected_pair -and
        ($selectedPairGap.data.path_focus.anchor_pair_details | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($cohortView.data.path_focus.anchor_pair_details | ConvertTo-Json -Depth 32 -Compress)) 'EC-044 altered default or existing anchor/Finding outputs.'
    $selectedPairGapWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequenceTop','20','-SequencePath','cohort/path.ps1','-SequencePairIndex','3')
    Check (($pairGap | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($selectedPairGapWide.data.path_focus.selected_pair | ConvertTo-Json -Depth 32 -Compress)) 'EC-044 complete selected report pair depends on SequenceTop preview.'
    $selectedPairFirst = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/path.ps1','-SequencePairIndex','1')
    $pairFirst = $selectedPairFirst.data.path_focus.selected_pair
    Check ($pairFirst.left_position -eq 1 -and $pairFirst.right_position -eq 2 -and
        ($pairFirst.anchors | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq
            'retained_same_severity,left_only,right_only,right_only,left_only' -and
        $pairFirst.counts.left_only_anchor_count -eq 2 -and
        $pairFirst.counts.right_only_anchor_count -eq 2 -and
        $pairFirst.counts.changed_anchor_count -eq 4 -and
        $pairFirst.counts.shared_with_internal_unreported_position_anchor_count -eq 0 -and
        $pairFirst.saved_severity_statement_delta_right_minus_left.critical -eq 1 -and
        $pairFirst.saved_severity_statement_delta_right_minus_left.high -eq -1 -and
        $pairFirst.saved_severity_statement_delta_right_minus_left.medium -eq 1 -and
        $pairFirst.saved_severity_statement_delta_right_minus_left.low -eq -1 -and
        $pairFirst.anchors[1].right.original_record_scoped_finding_refs.Count -eq 0 -and
        $pairFirst.anchors[2].left.original_record_scoped_finding_refs.Count -eq 0) 'EC-044 one-sided anchor contrast confused per-record original Finding references.'

    $selectedAnchorStable = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/path.ps1',
        '-SequenceAnchorIndex',([string]$stableF1.anchor_index_in_anchor_journeys))
    Check ($selectedAnchorStable.data.path_focus.selected_anchor.anchor_presence_pattern_in_caller_order -ceq '1111' -and
        $selectedAnchorStable.data.path_focus.selected_anchor.counts.retained_same_severity_pair_count -eq 6 -and
        $selectedAnchorStable.data.path_focus.selected_anchor.counts.changed_pair_count -eq 0 -and
        ($selectedAnchorStable.data.path_focus.selected_anchor.compared_pairs | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq
            'retained_same_severity,retained_same_severity,retained_same_severity,retained_same_severity,retained_same_severity,retained_same_severity') 'EC-043 turned fully stable saved histograms into pair changes.'


    $selectedLate = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/path.ps1',
        '-SequenceFindingRecordId',$cohortFourId,'-SequenceFindingId','F2')
    Check ($selectedLate.data.path_focus.selected_finding.original_position -eq 4 -and
        $selectedLate.data.path_focus.selected_finding.original_saved_severity -ceq 'medium' -and
        ($selectedLate.data.path_focus.selected_finding.compared_pairs | ForEach-Object { $_.pair_index }) -join ',' -ceq '3,5,6' -and
        ($selectedLate.data.path_focus.selected_finding.compared_pairs | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq 'retained_changed_severity,right_only,right_only' -and
        $selectedLate.data.path_focus.selected_finding.compared_pairs[0].counterpart_original_record_scoped_finding_refs[0].severity -ceq 'high') 'EC-042 reversed caller pair orientation or cross-record saved severity scopes.'

    $wrongFinding = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/path.ps1',
        '-SequenceFindingRecordId',$cohortOneId,'-SequenceFindingId','f2')
    Check ($wrongFinding.reason_code -eq 'CODE_SHOW_SEQUENCE_FINDING_NOT_FOUND' -and $null -eq $wrongFinding.data) 'EC-042 case-insensitive or missing original Finding ID was silently accepted.'
    $wrongFindingPath = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequencePath','cohort/PATH.ps1',
        '-SequenceFindingRecordId',$cohortOneId,'-SequenceFindingId','F2')
    Check ($wrongFindingPath.reason_code -eq 'CODE_SHOW_SEQUENCE_FINDING_NOT_FOUND' -and $null -eq $wrongFindingPath.data) 'EC-042 reinterpreted requested saved path using case folding.'

    $cohortWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$cohortTwoId,$cohortThreeId,$cohortFourId",
        '-SequenceTop','20','-SequencePath','cohort/path.ps1')
    Check (($cohortWide.data.path_focus.anchor_cohorts | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($cohorts | ConvertTo-Json -Depth 32 -Compress)) 'EC-035 multi-pattern complete cohort result changed with preview Top.'
    # EC-039: each pair (saved record ID, Finding ID) locates exactly one
    # checked statement, and every anchor/position ledger entry is navigable.
    # Reused local spelling F1 in four reports MUST stay record-scoped.
    $refs = $cohortView.data.path_focus.anchor_finding_refs
    Check ($refs.scope -ceq 'complete_saved_record_scoped_Finding_ID_navigation_for_explicit_exact_path' -and
        $refs.independent_of_sequence_top -and
        $refs.finding_id_scope -ceq 'within_own_selected_record_only_not_cross_record_identity' -and
        $refs.counts.distinct_exact_anchor_union_count -eq 5 -and
        $refs.counts.finding_reference_occurrences -eq 11 -and
        $refs.counts.reported_exact_anchor_position_occurrences -eq 11 -and
        $refs.counts.selected_positions_with_focused_findings_count -eq 4 -and
        $refs.anchors.Count -eq 5 -and $refs.positions.Count -eq 4 -and
        ($refs.positions | ForEach-Object { $_.finding_statement_count }) -join ',' -ceq '3,3,2,3' -and
        ($refs.positions[0].finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2,F3' -and
        ($refs.positions[0].finding_refs | ForEach-Object { $_.anchor_index_in_anchor_journeys }) -join ',' -ceq '1,2,5' -and
        ($refs.positions[1].reported_anchor_indices_in_anchor_journeys -join ',') -ceq '1,3,4' -and
        $refs.positions[0].finding_refs[0].severity -ceq 'info' -and
        $refs.positions[1].finding_refs[1].severity -ceq 'critical' -and
        $refs.positions[1].record_id -ceq $cohortTwoId -and
        $refs.positions[3].record_id -ceq $cohortFourId) 'EC-039 by-record Finding reference lookup has wrong IDs, anchor indexes, severity or total.'
    Check (($refs.anchors | ForEach-Object { $_.presence_pattern }) -join ',' -ceq '1111,1001,0100,0110,1001' -and
        ($refs.anchors | ForEach-Object { $_.reporting_record_count }) -join ',' -ceq '4,2,1,2,2' -and
        ($refs.anchors[1].references_in_caller_order | ForEach-Object { $_.record_id }) -join ',' -ceq "$cohortOneId,$cohortFourId" -and
        $refs.anchors[1].references_in_caller_order[0].finding_refs[0].finding_id -ceq 'F2' -and
        $refs.anchors[1].references_in_caller_order[0].finding_refs[0].severity -ceq 'high' -and
        $refs.anchors[1].references_in_caller_order[1].finding_refs[0].finding_id -ceq 'F2' -and
        $refs.anchors[1].references_in_caller_order[1].finding_refs[0].severity -ceq 'medium' -and
        $refs.anchors[0].references_in_caller_order[0].finding_refs[0].finding_id -ceq 'F1' -and
        $refs.anchors[0].references_in_caller_order[3].finding_refs[0].finding_id -ceq 'F1' -and
        $refs.anchors[0].references_in_caller_order[0].record_id -cne
            $refs.anchors[0].references_in_caller_order[3].record_id) 'EC-039 per-anchor report-scoped Finding IDs or saved severity witnesses are not stable.'
    Check (($cohortWide.data.path_focus.anchor_finding_refs | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($refs | ConvertTo-Json -Depth 32 -Compress)) 'EC-039 changed complete Finding lookup with SequenceTop 1 versus 20.' 

    # EC-036: six complete unordered pairs for four caller-selected reports.
    # Pair 1->4 retains A/B/E; B changes histogram across TWO unreported
    # positions, while E does not. This is not an adjacent severity event.
    $anchorPairs = $cohortView.data.path_focus.anchor_pairwise
    Check ($anchorPairs.pair_count -eq 6 -and $anchorPairs.pairs.Count -eq 6 -and
        $anchorPairs.independent_of_sequence_top -and
        $anchorPairs.counts.identical_saved_path_profile_pair_count -eq 0 -and
        $anchorPairs.counts.differing_saved_path_profile_pair_count -eq 6 -and
        $anchorPairs.counts.severity_only_difference_pair_count -eq 1 -and
        $anchorPairs.counts.pair_with_anchor_membership_difference_count -eq 5 -and
        $anchorPairs.counts.mixed_anchor_and_severity_difference_pair_count -eq 0 -and
        $anchorPairs.counts.left_only_exact_anchor_pair_occurrences -eq 8 -and
        $anchorPairs.counts.right_only_exact_anchor_pair_occurrences -eq 7 -and
        $anchorPairs.counts.retained_exact_anchor_pair_occurrences -eq 9 -and
        $anchorPairs.counts.both_unreported_exact_anchor_pair_occurrences -eq 6 -and
        $anchorPairs.counts.retained_changed_severity_histogram_anchor_pair_occurrences -eq 1 -and
        $anchorPairs.counts.retained_identical_severity_histogram_anchor_pair_occurrences -eq 8 -and
        $anchorPairs.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 15 -and
        $anchorPairs.counts.pair_with_internal_reporting_gap_for_shared_anchor_count -eq 1 -and
        $anchorPairs.counts.shared_anchor_with_internal_unreported_position_pair_occurrences -eq 2) 'EC-036 missed exact complete nonadjacent pairwise membership, severity changes or internal reporting gaps.'
    Check (($anchorPairs.pairs | ForEach-Object { "$($_.left_position)-$($_.right_position)" }) -join ',' -ceq
            '1-2,1-3,1-4,2-3,2-4,3-4' -and
        ($anchorPairs.pairs | ForEach-Object { $_.anchor_symmetric_difference_count }) -join ',' -ceq
            '4,3,0,1,4,3' -and
        $anchorPairs.pairs[2].same_saved_path_profile -eq $false -and
        $anchorPairs.pairs[2].severity_only_difference -and
        $anchorPairs.pairs[2].retained_exact_anchor_count -eq 3 -and
        $anchorPairs.pairs[2].retained_changed_severity_histogram_anchor_count -eq 1 -and
        $anchorPairs.pairs[2].shared_anchor_with_internal_unreported_position_count -eq 2 -and
        $anchorPairs.pairs[2].left_finding_statement_count -eq 3 -and
        $anchorPairs.pairs[2].right_finding_statement_count -eq 3 -and
        $anchorPairs.pairs[3].left_only_exact_anchor_count -eq 1 -and
        $anchorPairs.pairs[3].right_only_exact_anchor_count -eq 0) 'EC-036 pair ordering, directionality or gap-vs-retained-severity attribution is wrong.'
    Check ($anchorPairs.anchor_pair_frequencies.Count -eq 5 -and
        ($anchorPairs.anchor_pair_frequencies | ForEach-Object { $_.compared_reported_pair_count }) -join ',' -ceq
            '6,1,0,1,1' -and
        ($anchorPairs.anchor_pair_frequencies | ForEach-Object { $_.contrasting_reported_unreported_pair_count }) -join ',' -ceq
            '0,4,3,4,4' -and
        ($anchorPairs.anchor_pair_frequencies | ForEach-Object { $_.retained_changed_severity_histogram_pair_count }) -join ',' -ceq
            '0,1,0,0,0' -and
        ($anchorPairs.anchor_pair_frequencies | ForEach-Object { $_.shared_with_internal_unreported_position_pair_count }) -join ',' -ceq
            '0,1,0,0,1' -and
        $anchorPairs.anchor_pair_frequencies[4].anchor_index_in_anchor_journeys -eq 5 -and
        ($anchorPairs.caller_distance_distribution | ForEach-Object { $_.compared_pair_count }) -join ',' -ceq
            '3,2,1' -and
        ($anchorPairs.caller_distance_distribution | ForEach-Object { $_.shared_anchor_with_internal_unreported_position_occurrences }) -join ',' -ceq
            '0,0,2') 'EC-036 lost canonical anchor references, combinatorial pair frequencies or full caller-distance bins.'
    Check (($cohortWide.data.path_focus.anchor_pairwise | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($anchorPairs | ConvertTo-Json -Depth 32 -Compress)) 'EC-036 complete path-pairwise result changed with SequenceTop.'

    # EC-037: complete, navigable pair-by-pair anchor classification, not
    # just category counts. Canonical indices are A=1,B=2,C=3,D=4,E=5.
    # Pair 1->4 is severity-only B(high -> medium) despite B/E having
    # unreported positions 2/3. Cross-gap is OVERLAPPING, not a sixth bucket.
    $pairDetails = $cohortView.data.path_focus.anchor_pair_details
    $firstDetail = $pairDetails.pairs[0]
    $gapDetail = $pairDetails.pairs[2]
    Check ($pairDetails.pair_count -eq 6 -and $pairDetails.pairs.Count -eq 6 -and
        $pairDetails.independent_of_sequence_top -and
        $pairDetails.counts.different_saved_path_profile_pair_count -eq 6 -and
        $pairDetails.counts.left_only_anchor_pair_occurrences -eq 8 -and
        $pairDetails.counts.right_only_anchor_pair_occurrences -eq 7 -and
        $pairDetails.counts.retained_same_severity_anchor_pair_occurrences -eq 8 -and
        $pairDetails.counts.retained_changed_severity_anchor_pair_occurrences -eq 1 -and
        $pairDetails.counts.both_unreported_anchor_pair_occurrences -eq 6 -and
        $pairDetails.counts.shared_with_internal_unreported_position_anchor_pair_occurrences -eq 2 -and
        $pairDetails.counts.shared_cross_gap_and_severity_changed_anchor_pair_occurrences -eq 1) 'EC-037 pair-by-pair canonical classification contradicted existing untruncated pair totals.'
    Check (($firstDetail.left_only_anchor_indices -join ',') -ceq '2,5' -and
        ($firstDetail.right_only_anchor_indices -join ',') -ceq '3,4' -and
        ($firstDetail.retained_same_severity_anchor_indices -join ',') -ceq '1' -and
        $firstDetail.retained_changed_severity_anchor_indices.Count -eq 0 -and
        $firstDetail.both_unreported_anchor_indices.Count -eq 0 -and
        $firstDetail.shared_with_internal_unreported_position_anchor_indices.Count -eq 0 -and
        $firstDetail.changed_exact_anchor_count -eq 4 -and
        $firstDetail.finding_statement_count_delta -eq 0 -and
        $firstDetail.severity_statement_delta_all_reported_anchors.critical -eq 1 -and
        $firstDetail.severity_statement_delta_all_reported_anchors.high -eq -1 -and
        $firstDetail.severity_statement_delta_all_reported_anchors.medium -eq 1 -and
        $firstDetail.severity_statement_delta_all_reported_anchors.low -eq -1 -and
        $firstDetail.severity_statement_delta_all_reported_anchors.info -eq 0) 'EC-037 1->2 classified anchors incorrectly or lost signed saved-severity statement differences.'
    Check ($gapDetail.pair_index -eq 3 -and $gapDetail.left_position -eq 1 -and
        $gapDetail.right_position -eq 4 -and
        $gapDetail.left_only_anchor_indices.Count -eq 0 -and
        $gapDetail.right_only_anchor_indices.Count -eq 0 -and
        ($gapDetail.retained_same_severity_anchor_indices -join ',') -ceq '1,5' -and
        ($gapDetail.retained_changed_severity_anchor_indices -join ',') -ceq '2' -and
        ($gapDetail.both_unreported_anchor_indices -join ',') -ceq '3,4' -and
        ($gapDetail.shared_with_internal_unreported_position_anchor_indices -join ',') -ceq '2,5' -and
        $gapDetail.retained_changed_severity_details.Count -eq 1 -and
        $gapDetail.retained_changed_severity_details[0].anchor_index_in_anchor_journeys -eq 2 -and
        $gapDetail.retained_changed_severity_details[0].shared_with_internal_unreported_position -and
        $gapDetail.retained_changed_severity_details[0].severity_statement_delta.high -eq -1 -and
        $gapDetail.retained_changed_severity_details[0].severity_statement_delta.medium -eq 1 -and
        $gapDetail.severity_statement_delta_retained_anchors.high -eq -1 -and
        $gapDetail.severity_statement_delta_retained_anchors.medium -eq 1 -and
        $gapDetail.changed_exact_anchor_count -eq 1 -and
        $gapDetail.left_only_finding_statement_count -eq 0 -and
        $gapDetail.right_only_finding_statement_count -eq 0 -and
        $gapDetail.retained_left_finding_statement_count -eq 3 -and
        $gapDetail.retained_right_finding_statement_count -eq 3) 'EC-037 confused cross-gap overlapping membership with a real adjacent severity event.'
    Check (($pairDetails.ranked_pairs | ForEach-Object { $_.pair_index }) -join ',' -ceq
            '1,5,2,6,3,4' -and
        ($pairDetails.ranked_pairs | ForEach-Object { $_.changed_exact_anchor_count }) -join ',' -ceq
            '4,4,3,3,1,1' -and
        $pairDetails.ranked_pairs[4].shared_with_internal_unreported_position_anchor_count -eq 2) 'EC-037 changed-pair ranking was unstable or suppressed the across-gap tie break.'
    Check (($cohortWide.data.path_focus.anchor_pair_details | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($pairDetails | ConvertTo-Json -Depth 32 -Compress)) 'EC-037 complete per-pair details changed with preview SequenceTop.'

    # EC-038: inverse lookup must avoid scanning all EC-037 pairs to find
    # each exact saved quote anchor's contrasting report pairs. Canonical
    # A/B/C/D/E indices are 1..5. The five categories partition all SIX
    # report pairs for EVERY anchor; cross-gap remains an overlapping tag.
    $lookup = $cohortView.data.path_focus.anchor_pair_lookup
    $aLookup = $lookup.anchors[0]
    $bLookup = $lookup.anchors[1]
    $cLookup = $lookup.anchors[2]
    $dLookup = $lookup.anchors[3]
    $eLookup = $lookup.anchors[4]
    Check ($lookup.path -ceq 'cohort/path.ps1' -and $lookup.pair_count -eq 6 -and
        $lookup.independent_of_sequence_top -and
        $lookup.anchors.Count -eq 5 -and $lookup.ranked_anchors.Count -eq 5 -and
        $lookup.counts.distinct_exact_anchor_count -eq 5 -and
        $lookup.counts.anchors_differing_in_at_least_one_pair_count -eq 4 -and
        $lookup.counts.anchors_with_retained_severity_difference_count -eq 1 -and
        $lookup.counts.anchors_shared_across_an_internal_reporting_gap_count -eq 2 -and
        $lookup.counts.changed_anchor_pair_occurrences -eq 16 -and
        $lookup.counts.left_only_anchor_pair_occurrences -eq 8 -and
        $lookup.counts.right_only_anchor_pair_occurrences -eq 7 -and
        $lookup.counts.retained_same_severity_anchor_pair_occurrences -eq 8 -and
        $lookup.counts.retained_changed_severity_anchor_pair_occurrences -eq 1 -and
        $lookup.counts.both_unreported_anchor_pair_occurrences -eq 6 -and
        $lookup.counts.shared_with_internal_unreported_position_anchor_pair_occurrences -eq 2 -and
        $lookup.counts.shared_cross_gap_and_severity_changed_anchor_pair_occurrences -eq 1) 'EC-038 failed complete per-anchor/all-pairs category conservation.'
    Check ($aLookup.anchor_index_in_anchor_journeys -eq 1 -and
        $aLookup.presence_pattern -ceq '1111' -and $aLookup.changed_pair_count -eq 0 -and
        $aLookup.changed_pair_indices.Count -eq 0 -and
        ($aLookup.retained_same_severity_pair_indices -join ',') -ceq '1,2,3,4,5,6' -and
        $aLookup.shared_with_internal_unreported_position_pair_indices.Count -eq 0 -and
        $aLookup.retained_changed_severity_events.Count -eq 0 -and
        $bLookup.presence_pattern -ceq '1001' -and $bLookup.changed_pair_count -eq 5 -and
        ($bLookup.left_only_pair_indices -join ',') -ceq '1,2' -and
        ($bLookup.right_only_pair_indices -join ',') -ceq '5,6' -and
        ($bLookup.retained_changed_severity_pair_indices -join ',') -ceq '3' -and
        ($bLookup.both_unreported_pair_indices -join ',') -ceq '4' -and
        ($bLookup.changed_pair_indices -join ',') -ceq '1,2,3,5,6' -and
        ($bLookup.shared_with_internal_unreported_position_pair_indices -join ',') -ceq '3') 'EC-038 missed the complete constant-versus-A/B/A-with-a-gap anchor contrast.'
    Check ($bLookup.retained_changed_severity_events.Count -eq 1 -and
        $bLookup.retained_changed_severity_events[0].pair_index -eq 3 -and
        $bLookup.retained_changed_severity_events[0].left_position -eq 1 -and
        $bLookup.retained_changed_severity_events[0].right_position -eq 4 -and
        $bLookup.retained_changed_severity_events[0].shared_with_internal_unreported_position -and
        $bLookup.retained_changed_severity_events[0].finding_statement_count_delta -eq 0 -and
        $bLookup.retained_changed_severity_events[0].severity_statement_delta.high -eq -1 -and
        $bLookup.retained_changed_severity_events[0].severity_statement_delta.medium -eq 1 -and
        ($cLookup.right_only_pair_indices -join ',') -ceq '1' -and
        ($cLookup.left_only_pair_indices -join ',') -ceq '4,5' -and
        ($cLookup.both_unreported_pair_indices -join ',') -ceq '2,3,6' -and
        ($dLookup.changed_pair_indices -join ',') -ceq '1,2,5,6' -and
        ($dLookup.retained_same_severity_pair_indices -join ',') -ceq '4' -and
        ($eLookup.changed_pair_indices -join ',') -ceq '1,2,5,6' -and
        ($eLookup.retained_same_severity_pair_indices -join ',') -ceq '3' -and
        ($eLookup.shared_with_internal_unreported_position_pair_indices -join ',') -ceq '3' -and
        $eLookup.retained_changed_severity_events.Count -eq 0) 'EC-038 inverted an exclusive category, gap overlap, or signed retained severity witness incorrectly.'
    Check (($lookup.ranked_anchors | ForEach-Object { $_.anchor_index_in_anchor_journeys }) -join ',' -ceq
            '2,5,4,3,1' -and
        ($lookup.ranked_anchors | ForEach-Object { $_.changed_pair_count }) -join ',' -ceq
            '5,4,4,3,0' -and
        $lookup.ranked_anchors[1].shared_with_internal_unreported_position_pair_count -eq 1 -and
        $lookup.ranked_anchors[2].shared_with_internal_unreported_position_pair_count -eq 0) 'EC-038 change-frequency ranking dropped zero-change anchors or lost tie-breaking.'
    Check (($cohortWide.data.path_focus.anchor_pair_lookup | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($lookup | ConvertTo-Json -Depth 32 -Compress)) 'EC-038 complete inverse pair index changed with preview SequenceTop.'

    # EC-040: every pair projects only changed exact anchors, with the
    # ORIGINAL scoped Finding IDs on each side and no inferred ID matches.
    # These six reports-pairs cover one-sided, severity-only, cross-gap,
    # same-severity stable anchors, repeated cross-record F1/F2 and Top=1.
    $pairRefs = $cohortView.data.path_focus.anchor_pair_finding_refs
    $firstWitness = $pairRefs.pairs[0]
    $gapWitness = $pairRefs.pairs[2]
    Check ($pairRefs.path -ceq 'cohort/path.ps1' -and
        $pairRefs.independent_of_sequence_top -and
        $pairRefs.finding_id_scope -ceq 'separate_within_each_original_saved_record_no_cross_record_Finding_matches' -and
        $pairRefs.pair_count -eq 6 -and $pairRefs.pairs.Count -eq 6 -and
        $pairRefs.counts.pairs_with_changed_exact_anchor_count -eq 6 -and
        $pairRefs.counts.changed_exact_anchor_pair_occurrences -eq 16 -and
        $pairRefs.counts.left_only_anchor_pair_occurrences -eq 8 -and
        $pairRefs.counts.right_only_anchor_pair_occurrences -eq 7 -and
        $pairRefs.counts.retained_changed_severity_anchor_pair_occurrences -eq 1 -and
        $pairRefs.counts.left_changed_finding_reference_occurrences -eq 9 -and
        $pairRefs.counts.right_changed_finding_reference_occurrences -eq 8 -and
        $pairRefs.counts.changed_finding_reference_occurrences -eq 17 -and
        ($pairRefs.pairs | ForEach-Object { $_.changed_exact_anchor_count }) -join ',' -ceq '4,3,1,1,4,3') 'EC-040 failed complete changed-pair canonical anchor and saved Finding-reference occurrence conservation.'
    Check ($firstWitness.pair_index -eq 1 -and
        $firstWitness.left_record_id -ceq $cohortOneId -and
        $firstWitness.right_record_id -ceq $cohortTwoId -and
        $firstWitness.changed_exact_anchor_count -eq 4 -and
        ($firstWitness.changed_anchors | ForEach-Object { $_.anchor_index_in_anchor_journeys }) -join ',' -ceq '2,3,4,5' -and
        ($firstWitness.changed_anchors | ForEach-Object { $_.contrast_kind }) -join ',' -ceq 'left_only,right_only,right_only,left_only' -and
        $firstWitness.changed_anchors[0].left_finding_refs.Count -eq 1 -and
        $firstWitness.changed_anchors[0].left_finding_refs[0].finding_id -ceq 'F2' -and
        $firstWitness.changed_anchors[0].left_finding_refs[0].severity -ceq 'high' -and
        $firstWitness.changed_anchors[0].right_finding_refs.Count -eq 0 -and
        $firstWitness.changed_anchors[1].left_finding_refs.Count -eq 0 -and
        $firstWitness.changed_anchors[1].right_finding_refs[0].finding_id -ceq 'F2' -and
        $firstWitness.changed_anchors[1].right_finding_refs[0].severity -ceq 'critical') 'EC-040 lost one-sided exact record-scoped Finding IDs or mixed canonical order.'
    Check ($gapWitness.pair_index -eq 3 -and $gapWitness.left_position -eq 1 -and
        $gapWitness.right_position -eq 4 -and
        $gapWitness.changed_anchors.Count -eq 1 -and
        $gapWitness.changed_anchors[0].anchor_index_in_anchor_journeys -eq 2 -and
        $gapWitness.changed_anchors[0].contrast_kind -ceq 'retained_changed_severity' -and
        $gapWitness.changed_anchors[0].shared_with_internal_unreported_position -and
        $gapWitness.changed_anchors[0].left_record_id -ceq $cohortOneId -and
        $gapWitness.changed_anchors[0].right_record_id -ceq $cohortFourId -and
        $gapWitness.changed_anchors[0].left_finding_refs[0].finding_id -ceq 'F2' -and
        $gapWitness.changed_anchors[0].left_finding_refs[0].severity -ceq 'high' -and
        $gapWitness.changed_anchors[0].right_finding_refs[0].finding_id -ceq 'F2' -and
        $gapWitness.changed_anchors[0].right_finding_refs[0].severity -ceq 'medium' -and
        $gapWitness.changed_anchors[0].finding_statement_count_delta -eq 0 -and
        $gapWitness.changed_anchors[0].severity_statement_delta.high -eq -1 -and
        $gapWitness.changed_anchors[0].severity_statement_delta.medium -eq 1 -and
        $gapWitness.left_changed_finding_reference_occurrences -eq 1 -and
        $gapWitness.right_changed_finding_reference_occurrences -eq 1 -and
        $gapWitness.changed_anchors[0].left_record_id -cne
            $gapWitness.changed_anchors[0].right_record_id) 'EC-040 merged same-spelling Finding IDs across distinct reports or lost the cross-gap signed severity witness.'
    Check (($cohortWide.data.path_focus.anchor_pair_finding_refs | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($pairRefs | ConvertTo-Json -Depth 32 -Compress)) 'EC-040 full changed-pair Finding witnesses depend on SequenceTop.'
    # EC-041: invert every original scoped Finding into ALL three pair
    # appearances, retaining stable anchor-class evidence (which EC-040
    # deliberately omits). Same F2 spelling in four records stays four IDs.
    $findingPairs = $cohortView.data.path_focus.finding_pair_lookup
    $originalOneF1 = $findingPairs.positions[0].finding_refs[0]
    $originalOneF2 = $findingPairs.positions[0].finding_refs[1]
    $originalFourF2 = $findingPairs.positions[3].finding_refs[1]
    Check ($findingPairs.scope -ceq 'every_original_record_scoped_Finding_ID_to_all_involving_saved_report_pairs' -and
        $findingPairs.finding_id_scope -ceq 'original_record_only_no_cross_record_Finding_identity' -and
        $findingPairs.independent_of_sequence_top -and
        $findingPairs.path -ceq 'cohort/path.ps1' -and
        $findingPairs.pair_count -eq 6 -and $findingPairs.pairs.Count -eq 6 -and
        $findingPairs.positions.Count -eq 4 -and
        $findingPairs.counts.original_finding_reference_count -eq 11 -and
        $findingPairs.counts.complete_finding_pair_incidence_count -eq 33 -and
        $findingPairs.counts.changed_anchor_finding_pair_incidence_count -eq 17 -and
        $findingPairs.counts.stable_anchor_finding_pair_incidence_count -eq 16 -and
        $findingPairs.counts.left_only_finding_pair_incidence_count -eq 8 -and
        $findingPairs.counts.right_only_finding_pair_incidence_count -eq 7 -and
        $findingPairs.counts.retained_changed_severity_finding_pair_incidence_count -eq 2 -and
        $findingPairs.counts.retained_same_severity_finding_pair_incidence_count -eq 16 -and
        $findingPairs.counts.shared_internal_unreported_gap_finding_pair_incidence_count -eq 4 -and
        $findingPairs.counts.findings_with_at_least_one_changed_anchor_pair_count -eq 7 -and
        $findingPairs.counts.findings_with_only_stable_anchor_pairs_count -eq 4 -and
        ($findingPairs.positions | ForEach-Object { $_.finding_reference_count }) -join ',' -ceq '3,3,2,3') 'EC-041 lost original Finding coverage, stable pair membership, categories or full pair marginals.'
    Check ($originalOneF1.finding_id -ceq 'F1' -and
        $originalOneF1.changed_anchor_pair_incidence_count -eq 0 -and
        $originalOneF1.stable_anchor_pair_incidence_count -eq 3 -and
        ($originalOneF1.compared_pairs | ForEach-Object { $_.pair_index }) -join ',' -ceq '1,2,3' -and
        ($originalOneF1.compared_pairs | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq 'retained_same_severity,retained_same_severity,retained_same_severity' -and
        $originalOneF2.finding_id -ceq 'F2' -and
        $originalOneF2.severity -ceq 'high' -and
        $originalOneF2.anchor_index_in_anchor_journeys -eq 2 -and
        ($originalOneF2.compared_pairs | ForEach-Object { $_.pair_index }) -join ',' -ceq '1,2,3' -and
        ($originalOneF2.compared_pairs | ForEach-Object { $_.anchor_pair_class }) -join ',' -ceq 'left_only,left_only,retained_changed_severity' -and
        $originalOneF2.compared_pairs[2].counterpart_position -eq 4 -and
        $originalOneF2.compared_pairs[2].counterpart_record_id -ceq $cohortFourId -and
        $originalOneF2.compared_pairs[2].counterpart_finding_statement_count -eq 1 -and
        $originalOneF2.compared_pairs[2].shared_with_internal_unreported_position -and
        $originalFourF2.finding_id -ceq 'F2' -and
        $originalFourF2.severity -ceq 'medium' -and
        $originalFourF2.compared_pairs[0].this_side -ceq 'right' -and
        $originalFourF2.compared_pairs[0].pair_index -eq 3 -and
        $originalFourF2.compared_pairs[0].anchor_pair_class -ceq 'retained_changed_severity' -and
        $originalFourF2.compared_pairs[0].counterpart_record_id -ceq $cohortOneId -and
        $findingPairs.positions[0].record_id -cne $findingPairs.positions[3].record_id) 'EC-041 merged same-spelling cross-record Findings or lost exact reverse pair navigation.'
    Check ($findingPairs.pairs[0].changed_left_finding_pair_incidence_count -eq 2 -and
        $findingPairs.pairs[0].changed_right_finding_pair_incidence_count -eq 2 -and
        $findingPairs.pairs[0].stable_left_finding_pair_incidence_count -eq 1 -and
        $findingPairs.pairs[0].stable_right_finding_pair_incidence_count -eq 1 -and
        $findingPairs.pairs[2].changed_left_finding_pair_incidence_count -eq 1 -and
        $findingPairs.pairs[2].changed_right_finding_pair_incidence_count -eq 1 -and
        $findingPairs.pairs[2].stable_left_finding_pair_incidence_count -eq 2 -and
        $findingPairs.pairs[2].stable_right_finding_pair_incidence_count -eq 2) 'EC-041 pair-side totals do not reconstruct complete saved pair evidence.'
    Check (($cohortWide.data.path_focus.finding_pair_lookup | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($findingPairs | ConvertTo-Json -Depth 32 -Compress)) 'EC-041 full original Finding-to-pair index depends on SequenceTop.'
    Check (($findingPairs | ConvertTo-Json -Depth 32 -Compress) -notmatch
        'Fixture local text|temporary untracked text|recommended') 'EC-041 exposed raw source or free-form model prose through navigation.'
    Check (($pairRefs | ConvertTo-Json -Depth 32 -Compress) -notmatch
        'Fixture local text|temporary untracked text|recommended') 'EC-040 disclosed model prose or raw source inside pair Finding witnesses.'

    # Mixed membership churn AND changed severity on a retained exact anchor
    # must be counted as one differing pair, not a severity-only pair.
    $mixedContrast = Clone-Record -Record $seed
    $mixedContrast.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'cohort/path.ps1' -Sha ('1'*64) -Severity 'critical'),
        (New-Finding -Original $orig -Id 'F2' -Path 'cohort/path.ps1' -Sha ('6'*64) -Severity 'low')
    ); $mixedContrast.finding_count = 2
    $mixedContrast.summary = 'Mixed retained severity and quote-anchor membership.'
    $mixedContrastId = Store-Record -Record $mixedContrast -Folder $store
    $mixedView = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$cohortOneId,$mixedContrastId",
        '-SequenceTop','1','-SequencePath','cohort/path.ps1')
    $mixedPair = $mixedView.data.path_focus.anchor_pairwise
    Check ($mixedPair.pair_count -eq 1 -and
        $mixedPair.pairs[0].left_reported_exact_anchor_count -eq 3 -and
        $mixedPair.pairs[0].right_reported_exact_anchor_count -eq 2 -and
        $mixedPair.pairs[0].retained_exact_anchor_count -eq 1 -and
        $mixedPair.pairs[0].left_only_exact_anchor_count -eq 2 -and
        $mixedPair.pairs[0].right_only_exact_anchor_count -eq 1 -and
        $mixedPair.pairs[0].retained_changed_severity_histogram_anchor_count -eq 1 -and
        $mixedPair.counts.mixed_anchor_and_severity_difference_pair_count -eq 1 -and
        $mixedPair.counts.severity_only_difference_pair_count -eq 0 -and
        -not $mixedPair.pairs[0].same_saved_path_profile) 'EC-036 lost or misclassified simultaneous anchor churn and retained severity change.'
    $mixedDetails = $mixedView.data.path_focus.anchor_pair_details
    Check ($mixedDetails.pair_count -eq 1 -and
        ($mixedDetails.pairs[0].left_only_anchor_indices -join ',') -ceq '2,3' -and
        ($mixedDetails.pairs[0].right_only_anchor_indices -join ',') -ceq '4' -and
        ($mixedDetails.pairs[0].retained_changed_severity_anchor_indices -join ',') -ceq '1' -and
        $mixedDetails.pairs[0].changed_exact_anchor_count -eq 4 -and
        $mixedDetails.pairs[0].retained_changed_severity_details.Count -eq 1 -and
        $mixedDetails.pairs[0].retained_changed_severity_details[0].severity_statement_delta.critical -eq 1 -and
        $mixedDetails.pairs[0].retained_changed_severity_details[0].severity_statement_delta.info -eq -1) 'EC-037 mixed membership and retained severity delta was not navigable or independent.'
    $mixedLookup = $mixedView.data.path_focus.anchor_pair_lookup
    Check ($mixedLookup.anchors.Count -eq 4 -and
        $mixedLookup.counts.changed_anchor_pair_occurrences -eq 4 -and
        $mixedLookup.counts.anchors_with_retained_severity_difference_count -eq 1 -and
        ($mixedLookup.anchors[0].retained_changed_severity_pair_indices -join ',') -ceq '1' -and
        $mixedLookup.anchors[0].retained_changed_severity_events.Count -eq 1 -and
        $mixedLookup.anchors[0].retained_changed_severity_events[0].severity_statement_delta.critical -eq 1 -and
        $mixedLookup.anchors[0].retained_changed_severity_events[0].severity_statement_delta.info -eq -1 -and
        ($mixedLookup.anchors[1].left_only_pair_indices -join ',') -ceq '1' -and
        ($mixedLookup.anchors[3].right_only_pair_indices -join ',') -ceq '1') 'EC-038 failed to invert simultaneous one-sided anchor changes and a retained severity delta.'

    $focusedJson = $aFocus | ConvertTo-Json -Depth 32 -Compress
    Check (-not $focusedJson.Contains('private sequence quote') -and
        -not $focusedJson.Contains('temporary untracked text')) 'Path-focused result leaked raw source or model prose.'

    # Same saved path in adjacent records but completely DIFFERENT anchors:
    # path presence is 11 with 0 transitions, anchor presence transitions = 2.
    # Two statements on the first anchor must remain two Finding statements.
    $shiftLeft = Clone-Record -Record $seed
    $shiftLeft.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'stable/path.ps1' -Sha ('1'*64) -Severity 'low'),
        (New-Finding -Original $orig -Id 'F2' -Path 'stable/path.ps1' -Sha ('1'*64) -Severity 'high')
    ); $shiftLeft.finding_count = 2; $shiftLeft.summary = 'Two reports on one quote anchor.'
    $shiftLeftId = Store-Record -Record $shiftLeft -Folder $store
    $shiftRight = Clone-Record -Record $seed
    $shiftRight.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'stable/path.ps1' -Sha ('2'*64) -Severity 'medium')
    ); $shiftRight.finding_count = 1; $shiftRight.summary = 'One different anchor under the same path.'
    $shiftRightId = Store-Record -Record $shiftRight -Folder $store
    $samePath = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$shiftLeftId,$shiftRightId",'-SequenceTop','1')
    $shift = $samePath.data.path_index
    Check ($shift.counts.distinct_saved_path_count -eq 1 -and
        $shift.counts.path_presence_transitions_across_adjacent_pairs_count -eq 0 -and
        $shift.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 2 -and
        $shift.counts.distinct_exact_anchor_union_count -eq 2 -and
        $shift.counts.finding_statement_count_across_selected_records -eq 3 -and
        $shift.paths.Count -eq 1 -and -not $shift.paths_truncated -and
        $shift.paths[0].presence_pattern -ceq '11' -and
        $shift.paths[0].observations_in_caller_order[0].finding_statement_count -eq 2 -and
        $shift.paths[0].observations_in_caller_order[1].finding_statement_count -eq 1) 'Reported path continuity was confused with exact-anchor retention or statement multiplicity.'
    $shiftStep = $shift.step_deltas[0]
    Check ($shift.step_deltas.Count -eq 1 -and
        $shiftStep.counts.previous_reported_path_count -eq 1 -and
        $shiftStep.counts.next_reported_path_count -eq 1 -and
        $shiftStep.counts.retained_path_count -eq 1 -and
        $shiftStep.counts.retained_path_with_anchor_churn_count -eq 1 -and
        $shiftStep.counts.previous_only_path_count -eq 0 -and
        $shiftStep.counts.next_only_path_count -eq 0 -and
        $shiftStep.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 2 -and
        $shiftStep.counts.changed_path_count -eq 1 -and
        $shiftStep.changed_paths[0].path_status -ceq 'retained' -and
        $shiftStep.changed_paths[0].previous_finding_statement_count -eq 2 -and
        $shiftStep.changed_paths[0].next_finding_statement_count -eq 1) 'Path continuity hid complete anchor replacement or repeated statements.'

    $shiftAtlas = $samePath.data.pairwise_profile.path_disagreement
    Check ($shiftAtlas.counts.distinct_saved_path_union_count -eq 1 -and
        $shiftAtlas.counts.one_sided_path_pair_occurrences -eq 0 -and
        $shiftAtlas.counts.retained_path_anchor_churn_pair_occurrences -eq 1 -and
        $shiftAtlas.counts.retained_path_severity_change_pair_occurrences -eq 0 -and
        $shiftAtlas.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 2 -and
        $shiftAtlas.hotspots[0].path -ceq 'stable/path.ps1' -and
        $shiftAtlas.hotspots[0].differing_pairs[0].exact_anchor_symmetric_difference_count -eq 2) 'Same-path anchor replacement vanished from the pairwise path attribution.'

    # A retained quote severity change and two one-sided anchors in the
    # SAME retained path overlap; neither category may suppress the other.
    $mixedLeft = Clone-Record -Record $seed
    $mixedLeft.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'mixed/path.ps1' -Sha ('1'*64) -Severity 'low'),
        (New-Finding -Original $orig -Id 'F2' -Path 'mixed/path.ps1' -Sha ('2'*64) -Severity 'medium')
    ); $mixedLeft.finding_count = 2
    $mixedLeftId = Store-Record -Record $mixedLeft -Folder $store
    $mixedRight = Clone-Record -Record $seed
    $mixedRight.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'mixed/path.ps1' -Sha ('1'*64) -Severity 'high'),
        (New-Finding -Original $orig -Id 'F2' -Path 'mixed/path.ps1' -Sha ('3'*64) -Severity 'medium')
    ); $mixedRight.finding_count = 2
    $mixedRightId = Store-Record -Record $mixedRight -Folder $store
    $mixed = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$mixedLeftId,$mixedRightId",'-SequenceTop','1')
    $mixedAtlas = $mixed.data.pairwise_profile.path_disagreement
    Check ($mixedAtlas.counts.distinct_saved_path_union_count -eq 1 -and
        $mixedAtlas.counts.changed_path_pair_occurrences -eq 1 -and
        $mixedAtlas.counts.one_sided_path_pair_occurrences -eq 0 -and
        $mixedAtlas.counts.retained_path_anchor_churn_pair_occurrences -eq 1 -and
        $mixedAtlas.counts.retained_path_severity_change_pair_occurrences -eq 1 -and
        $mixedAtlas.counts.severity_histogram_only_difference_path_pair_occurrences -eq 0 -and
        $mixedAtlas.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 2 -and
        $mixedAtlas.counts.retained_severity_changed_anchor_pair_occurrences -eq 1 -and
        $mixedAtlas.hotspots[0].differing_pairs[0].retained_severity_distribution_changed_count -eq 1 -and
        -not $mixedAtlas.hotspots[0].differing_pairs[0].severity_histogram_only_difference) 'Retained-path overlap between exact-anchor churn and severity histogram difference was double-counted or lost.'

    # A retained exact quote with a changed severity *statement* mix must
    # appear in changed_paths even though its presence-transition score is 0.
    $severityLeft = Clone-Record -Record $seed
    $severityLeft.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'steady/path.ps1' -Sha ('3'*64) -Severity 'low')
    ); $severityLeft.finding_count = 1; $severityLeft.summary = 'Retained quote, earlier severity.'
    $severityLeftId = Store-Record -Record $severityLeft -Folder $store
    $severityRight = Clone-Record -Record $severityLeft
    $severityRight.checked_findings[0].severity = 'critical'
    $severityRight.summary = 'Retained quote, later severity.'
    $severityRightId = Store-Record -Record $severityRight -Folder $store
    $severityOnly = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$severityLeftId,$severityRightId",'-SequenceTop','1')
    $severityStep = $severityOnly.data.path_index.step_deltas[0]
    Check ($severityStep.counts.retained_path_count -eq 1 -and
        $severityStep.counts.retained_path_with_anchor_churn_count -eq 0 -and
        $severityStep.counts.retained_path_with_severity_distribution_change_count -eq 1 -and
        $severityStep.counts.retained_severity_distribution_changed_count -eq 1 -and
        $severityStep.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 0 -and
        $severityStep.counts.changed_path_count -eq 1 -and
        $severityStep.changed_paths.Count -eq 1 -and
        $severityStep.changed_paths[0].path -ceq 'steady/path.ps1' -and
        $severityStep.changed_paths[0].path_status -ceq 'retained' -and
        $severityStep.changed_paths[0].retained_severity_distribution_changed_count -eq 1 -and
        -not $severityStep.changed_paths_truncated) 'Severity-only changes disappeared when quote-anchor transition was zero.'

    $severityBaseline = $severityOnly.data.baseline_drift
    Check ($severityBaseline.comparison_count -eq 1 -and
        $severityBaseline.counts.severity_histogram_only_difference_position_count -eq 1 -and
        $severityBaseline.comparisons[0].counts.exact_anchor_symmetric_difference_count -eq 0 -and
        $severityBaseline.comparisons[0].counts.retained_severity_distribution_changed_count -eq 1 -and
        $severityBaseline.comparisons[0].counts.changed_path_count -eq 1 -and
        $severityBaseline.comparisons[0].changed_paths[0].comparison_status -ceq 'retained' -and
        -not $severityBaseline.comparisons[0].matches_baseline_profile) 'Severity-only baseline difference disappeared without anchor churn.'

    $severityPairs = $severityOnly.data.pairwise_profile
    Check ($severityPairs.pair_count -eq 1 -and
        $severityPairs.counts.matching_profile_pair_count -eq 0 -and
        $severityPairs.counts.differing_profile_pair_count -eq 1 -and
        $severityPairs.counts.severity_histogram_only_difference_pair_count -eq 1 -and
        $severityPairs.counts.path_presence_difference_pair_count -eq 0 -and
        $severityPairs.counts.exact_anchor_presence_difference_pair_count -eq 0 -and
        $severityPairs.counts.changed_path_pair_occurrences -eq 1 -and
        $severityPairs.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 0 -and
        $severityPairs.pairs[0].severity_histogram_only_difference -and
        $severityPairs.pairs[0].counts.retained_severity_distribution_changed_count -eq 1) 'All-pairs profile dropped a severity-histogram-only difference.'

    $severityAtlas = $severityPairs.path_disagreement
    Check ($severityAtlas.counts.distinct_saved_path_union_count -eq 1 -and
        $severityAtlas.counts.changed_path_pair_occurrences -eq 1 -and
        $severityAtlas.counts.one_sided_path_pair_occurrences -eq 0 -and
        $severityAtlas.counts.retained_path_anchor_churn_pair_occurrences -eq 0 -and
        $severityAtlas.counts.retained_path_severity_change_pair_occurrences -eq 1 -and
        $severityAtlas.counts.severity_histogram_only_difference_path_pair_occurrences -eq 1 -and
        $severityAtlas.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 0 -and
        $severityAtlas.hotspots[0].differing_pairs[0].severity_histogram_only_difference) 'All-pairs path view missed a severity-only change with no anchor presence change.'

    $severityClasses = $severityPairs.path_profile_classes
    Check ($severityClasses.counts.distinct_saved_path_union_count -eq 1 -and
        $severityClasses.counts.paths_with_multiple_profile_classes_count -eq 1 -and
        $severityClasses.counts.paths_with_unreported_positions_count -eq 0 -and
        $severityClasses.counts.total_path_profile_class_count -eq 2 -and
        $severityClasses.counts.reported_path_profile_class_count -eq 2 -and
        $severityClasses.counts.unreported_path_profile_class_count -eq 0 -and
        $severityClasses.counts.differing_path_pair_occurrences -eq 1 -and
        $severityClasses.hotspots[0].path -ceq 'steady/path.ps1' -and
        $severityClasses.hotspots[0].profile_classes[0].exact_anchor_count -eq 1 -and
        $severityClasses.hotspots[0].profile_classes[1].exact_anchor_count -eq 1 -and
        $severityClasses.hotspots[0].profile_classes[0].finding_statement_count -eq 1 -and
        $severityClasses.hotspots[0].profile_classes[1].finding_statement_count -eq 1 -and
        $severityClasses.hotspots[0].profile_classes[0].path_reported -and
        $severityClasses.hotspots[0].profile_classes[1].path_reported) 'Severity-only split must form distinct reported path classes despite identical anchor presence.'

    $severityJourney = $severityOnly.data.pairwise_profile.path_profile_transitions
    Check ($severityJourney.counts.distinct_saved_path_union_count -eq 1 -and
        $severityJourney.counts.adjacent_profile_transition_occurrences -eq 1 -and
        $severityJourney.adjacent_steps[0].retained_path_with_anchor_churn_count -eq 0 -and
        $severityJourney.adjacent_steps[0].retained_path_with_severity_change_count -eq 1 -and
        $severityJourney.adjacent_steps[0].severity_histogram_only_change_count -eq 1 -and
        $severityJourney.hotspots[0].path -ceq 'steady/path.ps1' -and
        $severityJourney.hotspots[0].transition_events[0].transition_kind -ceq 'reported_profile_changed' -and
        $severityJourney.hotspots[0].transition_events[0].severity_histogram_only_change -and
        $severityJourney.hotspots[0].transition_events[0].retained_severity_changed_anchor_count -eq 1 -and
        -not $severityJourney.hotspots[0].transition_events[0].returns_to_prior_profile) 'EC-032 discarded a severity-only transition at a retained exact anchor.'

    $severityProfile = $severityOnly.data.path_index.change_profile
    Check ($severityProfile.counts.paths_with_any_changed_step_count -eq 1 -and
        $severityProfile.counts.anchor_churn_path_step_occurrences -eq 0 -and
        $severityProfile.counts.retained_severity_only_path_step_occurrences -eq 1 -and
        $severityProfile.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 0 -and
        $severityProfile.hotspots.Count -eq 1 -and
        $severityProfile.hotspots[0].path -ceq 'steady/path.ps1' -and
        $severityProfile.hotspots[0].changed_step_count -eq 1 -and
        $severityProfile.hotspots[0].changes_in_caller_order[0].kind -ceq 'retained_severity_only' -and
        $severityProfile.hotspots[0].changes_in_caller_order[0].retained_severity_distribution_changed_count -eq 1) 'Severity-only hotspot incorrectly required an anchor churn.'
    $shiftProfile = $shift.change_profile
    Check ($shiftProfile.counts.paths_with_any_changed_step_count -eq 1 -and
        $shiftProfile.counts.anchor_churn_path_step_occurrences -eq 1 -and
        $shiftProfile.counts.retained_severity_changed_path_step_occurrences -eq 0 -and
        $shiftProfile.hotspots[0].changes_in_caller_order[0].kind -ceq 'retained_anchor_churn' -and
        $shiftProfile.hotspots[0].changes_in_caller_order[0].exact_anchor_presence_transitions_count -eq 2) 'A retained path with full anchor replacement was not classified as churn.'

    # A retained path can change its retained severity histogram AND replace
    # another exact quote anchor in the same step; both classes must survive.
    $severityPathPersistence = $severityBaseline.path_persistence
    Check ($severityPathPersistence.counts.distinct_saved_path_union_count -eq 1 -and
        $severityPathPersistence.counts.paths_ever_deviating_from_baseline_count -eq 1 -and
        $severityPathPersistence.counts.paths_with_severity_histogram_only_deviation_count -eq 1 -and
        $severityPathPersistence.counts.severity_histogram_only_deviation_path_position_occurrences -eq 1 -and
        $severityPathPersistence.counts.cumulative_exact_anchor_symmetric_difference_across_baseline_pairs_count -eq 0 -and
        $severityPathPersistence.comparison_totals[0].changed_path_count -eq 1 -and
        $severityPathPersistence.comparison_totals[0].severity_histogram_only_changed_path_count -eq 1 -and
        $severityPathPersistence.hotspots[0].deviation_from_baseline_pattern -ceq '01' -and
        $severityPathPersistence.hotspots[0].compared_positions_in_caller_order[0].retained_severity_distribution_changed_count -eq 1) 'Severity-only path baseline drift was not preserved without anchor churn.'

    $mixedLeft = Clone-Record -Record $seed
    $mixedLeft.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'mixed/path.ps1' -Sha ('4'*64) -Severity 'low'),
        (New-Finding -Original $orig -Id 'F2' -Path 'mixed/path.ps1' -Sha ('5'*64) -Severity 'info'),
        (New-Finding -Original $orig -Id 'F3' -Path 'stable/static.ps1' -Sha ('8'*64) -Severity 'high')
    ); $mixedLeft.finding_count = 3; $mixedLeft.summary = 'Mixed changed path and unchanged path.'
    $mixedLeftId = Store-Record -Record $mixedLeft -Folder $store
    $mixedRight = Clone-Record -Record $mixedLeft
    $mixedRight.checked_findings = @(
        (New-Finding -Original $orig -Id 'F1' -Path 'mixed/path.ps1' -Sha ('4'*64) -Severity 'critical'),
        (New-Finding -Original $orig -Id 'F2' -Path 'mixed/path.ps1' -Sha ('6'*64) -Severity 'info'),
        (New-Finding -Original $orig -Id 'F3' -Path 'stable/static.ps1' -Sha ('8'*64) -Severity 'high')
    ); $mixedRight.finding_count = 3; $mixedRight.summary = 'Mixed retained severity change and quote replacement.'
    $mixedRightId = Store-Record -Record $mixedRight -Folder $store
    $mixedView = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$mixedLeftId,$mixedRightId",'-SequenceTop','1')
    $mixedProfile = $mixedView.data.path_index.change_profile
    Check ($mixedView.data.path_index.step_deltas[0].counts.retained_path_with_anchor_churn_count -eq 1 -and
        $mixedView.data.path_index.step_deltas[0].counts.retained_path_with_severity_distribution_change_count -eq 1 -and
        $mixedProfile.counts.distinct_saved_path_count -eq 2 -and
        $mixedProfile.counts.paths_with_any_changed_step_count -eq 1 -and
        $mixedProfile.counts.anchor_churn_path_step_occurrences -eq 1 -and
        $mixedProfile.counts.retained_severity_changed_path_step_occurrences -eq 1 -and
        $mixedProfile.counts.retained_severity_only_path_step_occurrences -eq 0 -and
        $mixedProfile.changed_step_count_distribution[0].saved_path_count -eq 1 -and
        $mixedProfile.changed_step_count_distribution[1].saved_path_count -eq 1 -and
        $mixedProfile.hotspots[0].changes_in_caller_order[0].kind -ceq 'retained_anchor_and_severity_change' -and
        $mixedProfile.hotspots[0].changes_in_caller_order[0].exact_anchor_presence_transitions_count -eq 2 -and
        $mixedProfile.hotspots[0].changes_in_caller_order[0].retained_severity_distribution_changed_count -eq 1) 'Overlapping anchor/severity changes and unchanged path bin were incorrectly partitioned.'

    # Change at every adjacent step with zero anchor presence churn.
    $returnSeverity = Clone-Record -Record $severityLeft
    $returnSeverity.summary = 'Third distinct saved copy with initial severity.'
    $returnSeverityId = Store-Record -Record $returnSeverity -Folder $store
    $zigzag = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$severityLeftId,$severityRightId,$returnSeverityId",'-SequenceTop','1')
    $zigProfile = $zigzag.data.path_index.change_profile
    Check ($zigProfile.counts.paths_changed_in_every_adjacent_step_count -eq 1 -and
        $zigProfile.counts.paths_changed_in_multiple_steps_count -eq 1 -and
        $zigProfile.counts.changed_path_step_occurrences -eq 2 -and
        $zigProfile.counts.retained_severity_only_path_step_occurrences -eq 2 -and
        $zigProfile.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 0 -and
        $zigProfile.changed_step_count_distribution[2].saved_path_count -eq 1 -and
        $zigProfile.hotspots[0].longest_consecutive_changed_step_run -eq 2 -and
        $zigProfile.hotspots[0].changes_in_caller_order.Count -eq 2) 'A repeated severity-only path should change in every adjacent step.'

    $zigClasses = $zigzag.data.pairwise_profile.path_profile_classes
    Check ($zigClasses.counts.total_path_profile_class_count -eq 2 -and
        $zigClasses.counts.paths_with_reused_reported_profile_count -eq 1 -and
        $zigClasses.counts.paths_with_unreported_positions_count -eq 0 -and
        $zigClasses.counts.differing_path_pair_occurrences -eq 2 -and
        $zigClasses.distinct_profile_class_count_distribution[1].saved_path_count -eq 1 -and
        ($zigClasses.hotspots[0].profile_classes[0].positions -join ',') -ceq '1,3' -and
        ($zigClasses.hotspots[0].position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,1') 'Severity-only low/critical/low cycle failed class reuse without anchor replacement.'

    $zigJourney = $zigzag.data.pairwise_profile.path_profile_transitions
    Check ($zigJourney.counts.distinct_saved_path_union_count -eq 1 -and
        $zigJourney.counts.paths_with_return_to_reported_profile_count -eq 1 -and
        $zigJourney.counts.return_to_reported_profile_occurrences -eq 1 -and
        $zigJourney.counts.adjacent_profile_transition_occurrences -eq 2 -and
        $zigJourney.counts.paths_reported_again_after_unreported_gap_count -eq 0 -and
        $zigJourney.adjacent_steps[1].severity_histogram_only_change_count -eq 1 -and
        $zigJourney.hotspots[0].transition_events[1].returns_to_prior_profile -and
        $zigJourney.hotspots[0].transition_events[1].returns_to_reported_profile -and
        ($zigJourney.hotspots[0].position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,1') 'EC-032 did not detect a nonadjacent return to an unchanged reported severity profile.'

    # A/B/A returns to the SAME reported exact profile, not merely a
    # report after a gap. Severity-only changes preserve anchor membership.
    $zigFocus = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$severityLeftId,$severityRightId,$returnSeverityId",
        '-SequenceTop','1','-SequencePath','steady/path.ps1')
    $zigFocusedJourney = $zigFocus.data.path_focus.profile_journey
    Check ($zigFocusedJourney.counts.distinct_profile_class_count -eq 2 -and
        $zigFocusedJourney.counts.profile_transition_count -eq 2 -and
        $zigFocusedJourney.counts.return_to_prior_profile_count -eq 1 -and
        $zigFocusedJourney.counts.return_to_reported_profile_count -eq 1 -and
        $zigFocusedJourney.counts.return_to_unreported_profile_count -eq 0 -and
        $zigFocusedJourney.counts.reported_after_unreported_gap_count -eq 0 -and
        ($zigFocusedJourney.position_profile_classes | ForEach-Object { $_.profile_class }) -join ',' -ceq '1,2,1' -and
        $zigFocusedJourney.transition_events[0].severity_histogram_only_change -and
        $zigFocusedJourney.transition_events[1].severity_histogram_only_change -and
        $zigFocusedJourney.transition_events[1].returns_to_reported_profile -and
        $zigFocusedJourney.profile_classes[0].member_count -eq 2) 'EC-033 missed a reported-class return with unchanged exact quote anchors.'
    $zigAnchors = $zigFocus.data.path_focus.anchor_journeys
    Check ($zigAnchors.anchors.Count -eq 1 -and
        $zigAnchors.anchors[0].presence_pattern -ceq '111' -and
        $zigAnchors.anchors[0].presence_runs.Count -eq 1 -and
        $zigAnchors.anchors[0].transition_events.Count -eq 2 -and
        $zigAnchors.anchors[0].transition_events[0].transition_kind -ceq 'retained_severity_histogram_changed' -and
        $zigAnchors.anchors[0].transition_events[1].transition_kind -ceq 'retained_severity_histogram_changed' -and
        $zigAnchors.counts.presence_transitions_across_adjacent_pairs_count -eq 0 -and
        $zigAnchors.counts.retained_severity_histogram_transition_count -eq 2) 'EC-034 severity-only A/B/A must retain one presence run and two saved-severity events.'
    Check ($zigFocus.data.path_focus.anchor_cohorts.cohorts.Count -eq 1 -and
        $zigFocus.data.path_focus.anchor_cohorts.cohorts[0].presence_pattern -ceq '111' -and
        $zigFocus.data.path_focus.anchor_cohorts.cohorts[0].adjacent_step_totals[0].retained_severity_histogram_changed_count -eq 1 -and
        $zigFocus.data.path_focus.anchor_cohorts.cohorts[0].adjacent_step_totals[1].retained_severity_histogram_changed_count -eq 1) 'EC-035 missed retained exact anchor severity-only changes with unchanged presence.'

    $zigPairs = $zigFocus.data.path_focus.anchor_pairwise
    Check ($zigPairs.pair_count -eq 3 -and
        $zigPairs.counts.identical_saved_path_profile_pair_count -eq 1 -and
        $zigPairs.counts.differing_saved_path_profile_pair_count -eq 2 -and
        $zigPairs.counts.severity_only_difference_pair_count -eq 2 -and
        $zigPairs.counts.exact_anchor_symmetric_difference_pair_occurrences -eq 0 -and
        $zigPairs.counts.retained_changed_severity_histogram_anchor_pair_occurrences -eq 2 -and
        $zigPairs.pairs[1].same_saved_path_profile -and
        -not $zigPairs.pairs[1].severity_only_difference -and
        $zigPairs.anchor_pair_frequencies[0].compared_reported_pair_count -eq 3 -and
        $zigPairs.anchor_pair_frequencies[0].retained_changed_severity_histogram_pair_count -eq 2) 'EC-036 lost a true A/B/A exact saved-profile return across a nonadjacent pair.'
    $zigDetails = $zigFocus.data.path_focus.anchor_pair_details
    Check ($zigDetails.pair_count -eq 3 -and
        ($zigDetails.pairs[0].retained_changed_severity_anchor_indices -join ',') -ceq '1' -and
        ($zigDetails.pairs[1].retained_same_severity_anchor_indices -join ',') -ceq '1' -and
        ($zigDetails.pairs[2].retained_changed_severity_anchor_indices -join ',') -ceq '1' -and
        ($zigDetails.ranked_pairs | ForEach-Object { $_.pair_index }) -join ',' -ceq '1,3,2' -and
        $zigDetails.counts.left_only_anchor_pair_occurrences -eq 0 -and
        $zigDetails.counts.retained_changed_severity_anchor_pair_occurrences -eq 2) 'EC-037 introduced bogus anchor churn into a retained-severity A/B/A report return.'
    $zigLookup = $zigFocus.data.path_focus.anchor_pair_lookup
    Check ($zigLookup.anchors.Count -eq 1 -and
        $zigLookup.anchors[0].changed_pair_count -eq 2 -and
        ($zigLookup.anchors[0].retained_changed_severity_pair_indices -join ',') -ceq '1,3' -and
        ($zigLookup.anchors[0].retained_same_severity_pair_indices -join ',') -ceq '2' -and
        ($zigLookup.anchors[0].changed_pair_indices -join ',') -ceq '1,3' -and
        $zigLookup.anchors[0].retained_changed_severity_events.Count -eq 2 -and
        $zigLookup.anchors[0].left_only_pair_indices.Count -eq 0 -and
        $zigLookup.anchors[0].right_only_pair_indices.Count -eq 0) 'EC-038 mistook an A/B/A saved-severity return for one-sided disappearance.'

    $zigPersistence = $zigzag.data.baseline_drift.path_persistence
    Check ($zigPersistence.counts.distinct_saved_path_union_count -eq 1 -and
        $zigPersistence.counts.paths_ever_deviating_from_baseline_count -eq 1 -and
        $zigPersistence.counts.paths_deviating_at_last_selected_position_count -eq 0 -and
        $zigPersistence.counts.return_to_baseline_path_position_occurrences -eq 1 -and
        $zigPersistence.counts.cumulative_exact_anchor_symmetric_difference_across_baseline_pairs_count -eq 0 -and
        $zigPersistence.hotspots[0].deviation_from_baseline_pattern -ceq '010' -and
        $zigPersistence.hotspots[0].severity_histogram_only_deviation_comparison_count -eq 1 -and
        $zigPersistence.comparison_totals[1].changed_path_count -eq 0) 'A/severity-change/A return must be a profile return without anchor churn.'

    $unchanged = Clone-Record -Record $severityLeft
    $unchanged.summary = 'Another saved record with unchanged report anchors.'
    $unchangedId = Store-Record -Record $unchanged -Folder $store
    $steady = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$severityLeftId,$unchangedId")
    Check ($steady.data.path_index.step_deltas.Count -eq 1 -and
        $steady.data.path_index.step_deltas[0].counts.retained_path_count -eq 1 -and
        $steady.data.path_index.step_deltas[0].counts.changed_path_count -eq 0 -and
        $steady.data.path_index.step_deltas[0].changed_paths.Count -eq 0 -and
        $steady.data.path_index.step_deltas[0].omitted_changed_paths -eq 0) 'Two same-anchor same-severity reports fabricated a path change.'

    $steadyFocus = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$severityLeftId,$unchangedId",
        '-SequenceTop','1','-SequencePath','steady/path.ps1')
    $steadyFocusedJourney = $steadyFocus.data.path_focus.profile_journey
    Check ($steadyFocusedJourney.counts.distinct_profile_class_count -eq 1 -and
        $steadyFocusedJourney.counts.profile_transition_count -eq 0 -and
        $steadyFocusedJourney.counts.profile_run_count -eq 1 -and
        $steadyFocusedJourney.counts.longest_stable_run_in_selected_positions -eq 2 -and
        $steadyFocusedJourney.profile_classes[0].member_count -eq 2 -and
        $steadyFocusedJourney.profile_runs[0].length_in_selected_positions -eq 2 -and
        $steadyFocusedJourney.transition_events.Count -eq 0 -and
        -not $steadyFocusedJourney.included_in_global_transition_hotspots) 'EC-033 excluded a stable, correctly reported saved path from focus.'
    Check ($steadyFocus.data.path_focus.anchor_journeys.anchors.Count -eq 1 -and
        $steadyFocus.data.path_focus.anchor_journeys.anchors[0].presence_pattern -ceq '11' -and
        $steadyFocus.data.path_focus.anchor_journeys.anchors[0].presence_runs.Count -eq 1 -and
        $steadyFocus.data.path_focus.anchor_journeys.anchors[0].transition_events.Count -eq 0 -and
        $steadyFocus.data.path_focus.anchor_journeys.counts.anchor_transition_event_count -eq 0) 'EC-034 invented a change for a stable reported exact anchor.'
    Check ($steadyFocus.data.path_focus.anchor_cohorts.cohorts.Count -eq 1 -and
        $steadyFocus.data.path_focus.anchor_cohorts.cohorts[0].presence_pattern -ceq '11' -and
        $steadyFocus.data.path_focus.anchor_cohorts.counts.presence_transitions_across_adjacent_pairs_count -eq 0 -and
        $steadyFocus.data.path_focus.anchor_cohorts.counts.retained_severity_histogram_transition_count -eq 0) 'EC-035 invented a presence or severity event for stable anchor reports.'

    Check ($steadyFocus.data.path_focus.anchor_pairwise.counts.identical_saved_path_profile_pair_count -eq 1 -and
        $steadyFocus.data.path_focus.anchor_pairwise.pairs[0].retained_exact_anchor_count -eq 1 -and
        $steadyFocus.data.path_focus.anchor_pairwise.pairs[0].retained_changed_severity_histogram_anchor_count -eq 0 -and
        $steadyFocus.data.path_focus.anchor_pairwise.anchor_pair_frequencies[0].compared_reported_pair_count -eq 1) 'EC-036 invented differences for stable saved exact-anchor severity observations.'
    $steadyDetails = $steadyFocus.data.path_focus.anchor_pair_details
    Check ($steadyDetails.pair_count -eq 1 -and
        ($steadyDetails.pairs[0].retained_same_severity_anchor_indices -join ',') -ceq '1' -and
        $steadyDetails.pairs[0].changed_exact_anchor_count -eq 0 -and
        $steadyDetails.counts.different_saved_path_profile_pair_count -eq 0 -and
        $steadyDetails.pairs[0].severity_statement_delta_retained_anchors.high -eq 0) 'EC-037 fabricated deltas for an identical saved exact-anchor profile.'
    $steadyLookup = $steadyFocus.data.path_focus.anchor_pair_lookup
    Check ($steadyLookup.anchors.Count -eq 1 -and
        $steadyLookup.anchors[0].changed_pair_count -eq 0 -and
        $steadyLookup.counts.anchors_differing_in_at_least_one_pair_count -eq 0 -and
        ($steadyLookup.anchors[0].retained_same_severity_pair_indices -join ',') -ceq '1' -and
        $steadyLookup.anchors[0].retained_changed_severity_events.Count -eq 0) 'EC-038 invented pair-level differences in a stable one-anchor report.'

    Check ($steadyFocus.data.path_focus.anchor_pair_finding_refs.pair_count -eq 1 -and
        $steadyFocus.data.path_focus.anchor_pair_finding_refs.pairs[0].changed_anchors.Count -eq 0 -and
        $steadyFocus.data.path_focus.anchor_pair_finding_refs.counts.changed_finding_reference_occurrences -eq 0) 'EC-040 reported a stable exact-anchor severity histogram as a changed Finding pair.'
    $steadyFindingPairs = $steadyFocus.data.path_focus.finding_pair_lookup
    Check ($steadyFindingPairs.counts.changed_anchor_finding_pair_incidence_count -eq 0 -and
        $steadyFindingPairs.counts.original_finding_reference_count -gt 0 -and
        $steadyFindingPairs.counts.complete_finding_pair_incidence_count -eq
            $steadyFindingPairs.counts.stable_anchor_finding_pair_incidence_count -and
        $steadyFindingPairs.counts.findings_with_at_least_one_changed_anchor_pair_count -eq 0 -and
        $steadyFindingPairs.counts.findings_with_only_stable_anchor_pairs_count -eq
            $steadyFindingPairs.counts.original_finding_reference_count -and
        $steadyFindingPairs.pairs[0].changed_left_finding_pair_incidence_count -eq 0 -and
        $steadyFindingPairs.pairs[0].changed_right_finding_pair_incidence_count -eq 0) 'EC-041 dropped stable original Findings simply because no changed witness exists.'
    $steadyPersistence = $steady.data.baseline_drift.path_persistence
    Check ($steadyPersistence.counts.distinct_saved_path_union_count -eq 1 -and
        $steadyPersistence.counts.paths_never_deviating_from_baseline_count -eq 1 -and
        $steadyPersistence.counts.paths_ever_deviating_from_baseline_count -eq 0 -and
        $steadyPersistence.deviation_comparison_count_distribution[0].saved_path_count -eq 1 -and
        $steadyPersistence.deviation_comparison_count_distribution[1].saved_path_count -eq 0 -and
        $steadyPersistence.hotspots.Count -eq 0 -and
        $steadyPersistence.omitted_hotspots -eq 0 -and
        -not $steadyPersistence.hotspots_truncated) 'Unchanged anchors and severity statements must occupy the zero-deviation bin.'

    $steadyProfile = $steady.data.path_index.change_profile
    Check ($steadyProfile.counts.distinct_saved_path_count -eq 1 -and
        $steadyProfile.counts.paths_with_any_changed_step_count -eq 0 -and
        $steadyProfile.changed_step_count_distribution[0].saved_path_count -eq 1 -and
        $steadyProfile.changed_step_count_distribution[1].saved_path_count -eq 0 -and
        $steadyProfile.hotspots.Count -eq 0 -and $steadyProfile.omitted_hotspots -eq 0 -and
        -not $steadyProfile.hotspots_truncated) 'Unchanged historical path was fabricated as a hotspot.'

    Check ($samePath.data.baseline_drift.comparisons[0].counts.retained_path_with_anchor_churn_count -eq 1 -and
        $samePath.data.baseline_drift.comparisons[0].counts.exact_anchor_symmetric_difference_count -eq 2 -and
        $samePath.data.baseline_drift.comparisons[0].counts.baseline_reported_path_count -eq 1 -and
        $samePath.data.baseline_drift.comparisons[0].counts.compared_reported_path_count -eq 1) 'Retained path with entirely different anchors was treated as a baseline match.'

    $samePathFocus = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$shiftLeftId,$shiftRightId",'-SequenceTop','1',
        '-SequencePath','stable/path.ps1')
    Check ($samePathFocus.data.path_focus.anchor_trajectory.counts.distinct_exact_anchor_union_count -eq 2 -and
        $samePathFocus.data.path_index.counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 2 -and
        ($samePathFocus.data.path_index | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($shift | ConvertTo-Json -Depth 32 -Compress) -and
        ($samePathFocus.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($samePath.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress)) 'Focused call changed the all-path index, all-pairs profile or lost differing anchors.'

    Check ($samePathFocus.data.path_focus.anchor_pairwise.pair_count -eq 1 -and
        $samePathFocus.data.path_focus.anchor_pairwise.pairs[0].left_reported_exact_anchor_count -eq 1 -and
        $samePathFocus.data.path_focus.anchor_pairwise.pairs[0].left_finding_statement_count -eq 2 -and
        $samePathFocus.data.path_focus.anchor_pairwise.pairs[0].right_reported_exact_anchor_count -eq 1 -and
        $samePathFocus.data.path_focus.anchor_pairwise.pairs[0].retained_exact_anchor_count -eq 0 -and
        $samePathFocus.data.path_focus.anchor_pairwise.pairs[0].anchor_symmetric_difference_count -eq 2) 'EC-036 repeated saved Findings were incorrectly counted as distinct exact quote anchors.'
    $shiftRefs = $samePathFocus.data.path_focus.anchor_finding_refs
    Check ($shiftRefs.anchors.Count -eq 2 -and
        $shiftRefs.counts.finding_reference_occurrences -eq 3 -and
        ($shiftRefs.positions[0].finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $shiftRefs.positions[0].finding_refs[0].anchor_index_in_anchor_journeys -eq 1 -and
        $shiftRefs.positions[0].finding_refs[1].anchor_index_in_anchor_journeys -eq 1 -and
        $shiftRefs.positions[1].finding_refs[0].anchor_index_in_anchor_journeys -eq 2) 'EC-039 confused same-anchor Finding multiplicity with changed exact anchors.' 
    $shiftSelectedAnchor = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$shiftLeftId,$shiftRightId",
        '-SequencePath','stable/path.ps1','-SequenceAnchorIndex','1')
    $shiftAnchor = $shiftSelectedAnchor.data.path_focus.selected_anchor
    Check ($shiftAnchor.counts.original_record_scoped_finding_statement_occurrences -eq 2 -and
        $shiftAnchor.counts.left_only_pair_count -eq 1 -and
        $shiftAnchor.compared_pairs.Count -eq 1 -and
        $shiftAnchor.compared_pairs[0].saved_finding_statement_count_delta_right_minus_left -eq -2 -and
        ($shiftAnchor.positions[0].original_record_scoped_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $shiftAnchor.positions[1].original_record_scoped_finding_refs.Count -eq 0) 'EC-043 collapsed two original scoped Findings sharing one exact anchor.'

    $shiftPairRefs = $samePathFocus.data.path_focus.anchor_pair_finding_refs
    Check ($shiftPairRefs.pair_count -eq 1 -and
        $shiftPairRefs.pairs[0].changed_anchors.Count -eq 2 -and
        $shiftPairRefs.pairs[0].changed_anchors[0].contrast_kind -ceq 'left_only' -and
        ($shiftPairRefs.pairs[0].changed_anchors[0].left_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $shiftPairRefs.pairs[0].changed_anchors[0].right_finding_refs.Count -eq 0 -and
        $shiftPairRefs.pairs[0].changed_anchors[1].contrast_kind -ceq 'right_only' -and
        $shiftPairRefs.pairs[0].changed_anchors[1].right_finding_refs[0].finding_id -ceq 'F1' -and
        $shiftPairRefs.counts.changed_finding_reference_occurrences -eq 3) 'EC-040 lost repeated statements during total exact-anchor replacement.'
    $shiftFindingPairs = $samePathFocus.data.path_focus.finding_pair_lookup
    Check ($shiftFindingPairs.counts.original_finding_reference_count -eq 3 -and
        $shiftFindingPairs.counts.complete_finding_pair_incidence_count -eq 3 -and
        $shiftFindingPairs.counts.changed_anchor_finding_pair_incidence_count -eq 3 -and
        $shiftFindingPairs.counts.stable_anchor_finding_pair_incidence_count -eq 0 -and
        $shiftFindingPairs.counts.left_only_finding_pair_incidence_count -eq 2 -and
        $shiftFindingPairs.counts.right_only_finding_pair_incidence_count -eq 1 -and
        ($shiftFindingPairs.positions[0].finding_refs | ForEach-Object { $_.compared_pairs[0].anchor_pair_class }) -join ',' -ceq 'left_only,left_only' -and
        $shiftFindingPairs.positions[1].finding_refs[0].compared_pairs[0].anchor_pair_class -ceq 'right_only') 'EC-041 failed complete Finding-preserving one-sided anchor replacement.'
    $shiftDetails = $samePathFocus.data.path_focus.anchor_pair_details.pairs[0]
    Check (($shiftDetails.left_only_anchor_indices -join ',') -ceq '1' -and
        ($shiftDetails.right_only_anchor_indices -join ',') -ceq '2' -and
        $shiftDetails.left_only_finding_statement_count -eq 2 -and
        $shiftDetails.right_only_finding_statement_count -eq 1 -and
        $shiftDetails.finding_statement_count_delta -eq -1 -and
        $shiftDetails.severity_statement_delta_all_reported_anchors.low -eq -1 -and
        $shiftDetails.severity_statement_delta_all_reported_anchors.high -eq -1 -and
        $shiftDetails.severity_statement_delta_all_reported_anchors.medium -eq 1 -and
        $shiftDetails.severity_statement_delta_retained_anchors.high -eq 0) 'EC-037 collapsed duplicate saved Findings into one statement or mislabeled an unshared anchor.'


    $none = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @('-Mode','Sequence','-SequenceRecordIds',"$zeroId,$zero2Id")
    Check ($none.data.baseline_drift.comparison_count -eq 1 -and
        $none.data.baseline_drift.counts.matches_baseline_profile_position_count -eq 1 -and
        $none.data.baseline_drift.counts.differs_from_baseline_profile_position_count -eq 0 -and
        $none.data.baseline_drift.counts.returns_to_baseline_profile_after_previous_difference_position_count -eq 0 -and
        $none.data.baseline_drift.comparisons[0].counts.changed_path_count -eq 0 -and
        $none.data.baseline_drift.comparisons[0].changed_paths.Count -eq 0) 'Empty saved reports generated phantom baseline divergence.'
    $noneFocus = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$zeroId,$zero2Id",'-SequencePath','file Ω.txt')
    Check ($noneFocus.data.path_focus.anchor_finding_refs.positions.Count -eq 2 -and
        $noneFocus.data.path_focus.anchor_finding_refs.anchors.Count -eq 0 -and
        $noneFocus.data.path_focus.anchor_finding_refs.counts.finding_reference_occurrences -eq 0) 'EC-039 zero-Finding records invented per-report Finding reference IDs.'
    Check ($noneFocus.data.path_focus.anchor_pair_finding_refs.pair_count -eq 1 -and
        $noneFocus.data.path_focus.anchor_pair_finding_refs.pairs[0].changed_anchors.Count -eq 0 -and
        $noneFocus.data.path_focus.anchor_pair_finding_refs.counts.changed_finding_reference_occurrences -eq 0) 'EC-040 zero-Finding records produced phantom pair Finding IDs.'
    $noneFindingPairs = $noneFocus.data.path_focus.finding_pair_lookup
    Check ($noneFindingPairs.positions.Count -eq 2 -and
        $noneFindingPairs.pairs.Count -eq 1 -and
        $noneFindingPairs.counts.original_finding_reference_count -eq 0 -and
        $noneFindingPairs.counts.complete_finding_pair_incidence_count -eq 0 -and
        $noneFindingPairs.counts.findings_with_only_stable_anchor_pairs_count -eq 0 -and
        $noneFindingPairs.positions[0].finding_refs.Count -eq 0 -and
        $noneFindingPairs.positions[1].finding_refs.Count -eq 0) 'EC-041 returned phantom original ID incidence for two zero-Finding reports.'
    $noneSelectedFinding = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$zeroId,$zero2Id",
        '-SequencePath','file Ω.txt',
        '-SequenceFindingRecordId',$zeroId,'-SequenceFindingId','F1')
    Check ($noneSelectedFinding.reason_code -eq 'CODE_SHOW_SEQUENCE_FINDING_NOT_FOUND' -and
        $null -eq $noneSelectedFinding.data) 'EC-042 zero-Finding reports returned phantom original ID or partial data.'
    Check ($none.data.path_index.counts.distinct_saved_path_count -eq 0 -and
        $none.data.path_index.counts.finding_statement_count_across_selected_records -eq 0 -and
        $none.data.path_index.reporting_record_count_distribution.Count -eq 2 -and
        $none.data.path_index.paths.Count -eq 0 -and -not $none.data.path_index.paths_truncated) 'Zero-Finding reports yielded phantom historical saved paths.'
    Check ($none.data.path_index.step_deltas.Count -eq 1 -and
        $none.data.path_index.step_deltas[0].counts.previous_reported_path_count -eq 0 -and
        $none.data.path_index.step_deltas[0].counts.changed_path_count -eq 0 -and
        $none.data.path_index.step_deltas[0].counts.exact_anchor_presence_transitions_across_adjacent_pairs_count -eq 0 -and
        $none.data.path_index.step_deltas[0].changed_paths.Count -eq 0 -and
        -not $none.data.path_index.step_deltas[0].changed_paths_truncated) 'Zero-Finding pair produced phantom changed paths.'
    $emptyProfile = $none.data.path_index.change_profile
    Check ($emptyProfile.counts.distinct_saved_path_count -eq 0 -and
        $emptyProfile.counts.changed_path_step_occurrences -eq 0 -and
        $emptyProfile.changed_step_count_distribution.Count -eq 2 -and
        $emptyProfile.changed_step_count_distribution[0].saved_path_count -eq 0 -and
        $emptyProfile.changed_step_count_distribution[1].saved_path_count -eq 0 -and
        $emptyProfile.hotspots.Count -eq 0 -and -not $emptyProfile.hotspots_truncated) 'Empty checked reports generated false cross-step hotspots.'
    $emptyPairs = $none.data.pairwise_profile
    Check ($emptyPairs.pair_count -eq 1 -and
        $emptyPairs.counts.matching_profile_pair_count -eq 1 -and
        $emptyPairs.counts.differing_profile_pair_count -eq 0 -and
        $emptyPairs.counts.distinct_profile_class_count -eq 1 -and
        $emptyPairs.counts.repeated_profile_class_count -eq 1 -and
        $emptyPairs.counts.positions_in_repeated_profile_classes_count -eq 2 -and
        $emptyPairs.profile_classes[0].member_count -eq 2 -and
        $emptyPairs.changed_path_count_distribution.Count -eq 1 -and
        $emptyPairs.changed_path_count_distribution[0].changed_path_count -eq 0 -and
        $emptyPairs.changed_path_count_distribution[0].record_pair_count -eq 1) 'Two zero-Finding reports did not form one exact pairwise profile class.'

    $emptyAtlas = $emptyPairs.path_disagreement
    Check ($emptyAtlas.pair_count -eq 1 -and
        $emptyAtlas.counts.distinct_saved_path_union_count -eq 0 -and
        $emptyAtlas.counts.changed_path_pair_occurrences -eq 0 -and
        $emptyAtlas.counts.matching_path_pair_occurrences -eq 0 -and
        $emptyAtlas.differing_pair_count_distribution.Count -eq 2 -and
        $emptyAtlas.differing_pair_count_distribution[0].saved_path_count -eq 0 -and
        $emptyAtlas.differing_pair_count_distribution[1].saved_path_count -eq 0 -and
        $emptyAtlas.hotspots.Count -eq 0 -and -not $emptyAtlas.hotspots_truncated) 'Zero-Finding reports created phantom paths or omitted an all-zero distribution bin.'

    $emptyClasses = $emptyPairs.path_profile_classes
    Check ($emptyClasses.counts.distinct_saved_path_union_count -eq 0 -and
        $emptyClasses.counts.paths_with_single_profile_class_count -eq 0 -and
        $emptyClasses.counts.paths_with_multiple_profile_classes_count -eq 0 -and
        $emptyClasses.counts.total_path_profile_class_count -eq 0 -and
        $emptyClasses.counts.matching_path_pair_occurrences -eq 0 -and
        $emptyClasses.counts.differing_path_pair_occurrences -eq 0 -and
        $emptyClasses.distinct_profile_class_count_distribution.Count -eq 2 -and
        $emptyClasses.distinct_profile_class_count_distribution[0].saved_path_count -eq 0 -and
        $emptyClasses.distinct_profile_class_count_distribution[1].saved_path_count -eq 0 -and
        $emptyClasses.hotspots.Count -eq 0 -and $emptyClasses.omitted_hotspots -eq 0 -and
        -not $emptyClasses.hotspots_truncated) 'Empty saved reports fabricated a local profile class or omitted zero distribution bins.'

    $zeroJourneys = $none.data.pairwise_profile.path_profile_transitions
    Check ($zeroJourneys.counts.distinct_saved_path_union_count -eq 0 -and
        $zeroJourneys.counts.adjacent_profile_transition_occurrences -eq 0 -and
        $zeroJourneys.counts.total_profile_run_count -eq 0 -and
        $zeroJourneys.counts.longest_stable_run_in_selected_positions -eq 0 -and
        $zeroJourneys.profile_transition_count_distribution.Count -eq 2 -and
        $zeroJourneys.profile_transition_count_distribution[0].saved_path_count -eq 0 -and
        $zeroJourneys.profile_transition_count_distribution[1].saved_path_count -eq 0 -and
        $zeroJourneys.adjacent_steps.Count -eq 1 -and
        $zeroJourneys.adjacent_steps[0].changed_path_profile_count -eq 0 -and
        $zeroJourneys.hotspots.Count -eq 0 -and -not $zeroJourneys.hotspots_truncated) 'EC-032 created phantom transitions or truncated bins for zero-Finding reports.'

    Check ($none.data.anchor_trajectory.counts.distinct_exact_anchor_union_count -eq 0 -and
        $none.data.anchor_trajectory.reporting_record_count_distribution.Count -eq 2 -and
        $none.data.anchor_trajectory.previews.reported_once.Count -eq 0 -and
        -not $none.data.anchor_trajectory.previews_truncated) 'All-zero selected reports created phantom trajectories.'
    Check (-not $result.data.input_order_verified_as_chronology -and -not $result.data.absence_proves_resolution -and -not $result.data.source_revalidated) 'Unsafe proof flags were advertised.'
    $serialized = $result | ConvertTo-Json -Depth 32 -Compress
    Check (-not $serialized.Contains('private sequence quote') -and -not $serialized.Contains('temporary untracked text')) 'Raw source or model reasoning leaked in Sequence.'

    $emptyPersistence = $none.data.baseline_drift.path_persistence
    Check ($emptyPersistence.counts.distinct_saved_path_union_count -eq 0 -and
        $emptyPersistence.counts.paths_ever_deviating_from_baseline_count -eq 0 -and
        $emptyPersistence.counts.deviating_path_position_occurrences -eq 0 -and
        $emptyPersistence.deviation_comparison_count_distribution.Count -eq 2 -and
        $emptyPersistence.deviation_comparison_count_distribution[0].saved_path_count -eq 0 -and
        $emptyPersistence.comparison_totals.Count -eq 1 -and
        $emptyPersistence.comparison_totals[0].changed_path_count -eq 0 -and
        $emptyPersistence.hotspots.Count -eq 0) 'Two all-zero saved reports should produce an empty but complete baseline path persistence.'

    $reverse = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @('-Mode','Sequence','-SequenceRecordIds',"$cId,$bId,$aId")
    Check ($reverse.data.steps[0].counts.next_only_exact_anchor_count -eq 1 -and $reverse.data.steps[0].counts.previous_only_exact_anchor_count -eq 0) 'Reversing caller order did not reverse per-step omissions.'
    Check ($reverse.data.baseline_drift.baseline_record_id -ceq $cId -and
        $reverse.data.baseline_drift.comparisons[1].compared_record_id -ceq $aId -and
        $reverse.data.baseline_drift.comparisons[1].counts.baseline_only_exact_anchor_count -eq 1 -and
        $reverse.data.baseline_drift.comparisons[1].counts.compared_only_exact_anchor_count -eq 2) 'Baseline comparison ignored caller order.'
    $zeroView = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @('-Mode','Sequence','-SequenceRecordIds',"$zeroId,$bId")
    Check ($zeroView.data.steps[0].counts.retained_exact_anchor_count -eq 0 -and $zeroView.data.steps[0].counts.next_only_exact_anchor_count -eq 3) 'Zero-finding selected record incorrectly produced matches.'

    $badSyntax = @("$aId", "$aId,$aId", " $aId,$bId", "$aId,", "$($aId.ToUpperInvariant()),$bId")
    foreach ($invalid in $badSyntax) {
        $bad = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @('-Mode','Sequence','-SequenceRecordIds',$invalid)
        Check ($bad.reason_code -eq 'CODE_SHOW_SEQUENCE_RECORD_IDS_INVALID' -and $null -eq $bad.data) 'Malformed selected IDs were accepted.'
    }
    $overCap = ((0..12 | ForEach-Object { 'ci-' + $_.ToString('x64') }) -join ',')
    $tooMany = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @('-Mode','Sequence','-SequenceRecordIds',$overCap)
    Check ($tooMany.reason_code -eq 'CODE_SHOW_SEQUENCE_RECORD_IDS_INVALID') '13-entry selection bypassed 12-entry ceiling.'
    $badTop = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @('-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','21')
    Check ($badTop.reason_code -eq 'CODE_SHOW_SEQUENCE_TOP_INVALID') 'Invalid preview top was accepted.'
    foreach ($invalidPath in @('',('x' * 4097))) {
        $badPath = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @('-Mode','Sequence','-SequenceRecordIds',$query,'-SequencePath',$invalidPath)
        Check ($badPath.reason_code -eq 'CODE_SHOW_SEQUENCE_PATH_INVALID' -and $null -eq $badPath.data) 'Empty/overlong SequencePath was accepted.'
    }
    # EC-044 pair drilldown is valid even when this literal saved path was
    # never reported: the pair exists, but NO source anchor may be fabricated.
    $emptyPair = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePath','missing/**/literal.ps1','-SequencePairIndex','1')
    Check ($emptyPair.data.path_focus.selected_pair.counts.distinct_exact_anchor_union_count -eq 0 -and
        $emptyPair.data.path_focus.selected_pair.anchors.Count -eq 0 -and
        $emptyPair.data.path_focus.selected_pair.left_record_id -ceq $aId -and
        $emptyPair.data.path_focus.selected_pair.right_record_id -ceq $bId -and
        $emptyPair.data.path_focus.selected_pair.saved_finding_statement_count_delta_right_minus_left -eq 0) 'EC-044 fabricated anchors or Finding IDs for a literal absent path.'
    foreach ($badPairArgs in @(
        @('-SequencePairIndex','1'),
        @('-SequencePath','src/A.txt','-SequencePairIndex',''),
        @('-SequencePath','src/A.txt','-SequencePairIndex','0'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','01'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','067'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','67'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','-1'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','1.5'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','x'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','1','-SequenceAnchorIndex','1'),
        @('-SequencePath','src/A.txt','-SequencePairIndex','1',
            '-SequenceFindingRecordId',$aId,'-SequenceFindingId','F1')
    )) {
        $badPair = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More (
            @('-Mode','Sequence','-SequenceRecordIds',$query) + $badPairArgs)
        Check ($badPair.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_SELECTOR_INVALID' -and
            $null -eq $badPair.data) 'EC-044 accepted malformed, contextless or competing direct pair selectors.'
    }
    $missingPair = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequencePath','src/A.txt',
        '-SequencePairIndex','66')
    Check ($missingPair.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_NOT_FOUND' -and
        $null -eq $missingPair.data) 'EC-044 invented a selected report pair outside the canonical N-choose-2 range.'
    $wrongPairMode = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','List','-SequencePairIndex','1')
    $wrongPairAction = Run-CES -Action Inspect -Repo $repo -Exit 4 -More @(
        '-SequencePairIndex','1')
    Check ($wrongPairMode.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE' -and
        $wrongPairAction.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE') 'EC-044 pair selector escaped the read-only Sequence context.'

    # EC-045: select a canonical pair WITHOUT a path, and recover every saved
    # path across all chosen records (not just Top=1 hotspots). A/B/C has five
    # ordinal case-sensitive paths. B vs C leaves A-only paths absent at BOTH
    # pair endpoints; these must remain in the full union, never disappear.
    $overviewAB = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequenceTop','1','-SequencePairOverviewIndex','1')
    $overview = $overviewAB.data.selected_pair_overview
    Check ($overview.scope -ceq 'one_explicit_canonical_report_pair_all_saved_paths_in_selected_set' -and
        $null -eq $overviewAB.data.path_focus -and
        $overview.independent_of_sequence_top -and
        $overview.left_record_id -ceq $aId -and $overview.right_record_id -ceq $bId -and
        $overview.pair_index_in_pairwise_profile -eq 1 -and
        $overview.paths.Count -eq 5 -and
        ($overview.paths | ForEach-Object { $_.path }) -join ',' -ceq
            'file Ω.txt,src/A.txt,src/B.txt,src/C.txt,src/a.txt' -and
        $overview.counts.distinct_saved_path_union_count -eq 5 -and
        $overview.counts.left_reported_path_count -eq 3 -and
        $overview.counts.right_reported_path_count -eq 3 -and
        $overview.counts.retained_path_count -eq 1 -and
        $overview.counts.left_only_path_count -eq 2 -and
        $overview.counts.right_only_path_count -eq 2 -and
        $overview.counts.changed_path_count -eq 5 -and
        $overview.counts.matching_path_count -eq 0 -and
        $overview.counts.retained_changed_severity_exact_anchor_count -eq 1 -and
        $overview.counts.left_only_exact_anchor_count -eq 2 -and
        $overview.counts.right_only_exact_anchor_count -eq 2 -and
        $overview.counts.left_finding_statement_count -eq 4 -and
        $overview.counts.right_finding_statement_count -eq 3 -and
        ($overview.changed_path_indices -join ',') -ceq '1,2,3,4,5' -and
        $overview.saved_severity_statement_delta_right_minus_left.info -eq -1 -and
        $overview.saved_severity_statement_delta_right_minus_left.low -eq -1 -and
        $overview.saved_severity_statement_delta_right_minus_left.medium -eq 1 -and
        $overview.paths[0].pair_path_class -ceq 'retained_changed_profile' -and
        $overview.paths[0].left.original_record_scoped_finding_refs.Count -eq 2 -and
        ($overview.paths[0].left.original_record_scoped_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $overview.paths[0].right.original_record_scoped_finding_refs[0].finding_id -ceq 'F1' -and
        $overview.paths[0].right.original_record_scoped_finding_refs[0].severity -ceq 'high' -and
        $overview.paths[1].pair_path_class -ceq 'left_only' -and
        $overview.paths[4].pair_path_class -ceq 'right_only' -and
        $null -eq $overview.paths[1].right.saved_severity_statement_counts) 'EC-045 lost all-path A/B summary, case-sensitive paths, signed severity or original scoped Finding IDs.'
    $overviewABWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequenceTop','20','-SequencePairOverviewIndex','1')
    Check (($overview | ConvertTo-Json -Depth 32 -Compress) -ceq
        ($overviewABWide.data.selected_pair_overview | ConvertTo-Json -Depth 32 -Compress) -and
        $null -eq $result.data.selected_pair_overview -and
        ($overviewAB.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($result.data.pairwise_profile | ConvertTo-Json -Depth 32 -Compress)) 'EC-045 global pair overview changed earlier projections or depends on Top.'
    $overviewBC = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequencePairOverviewIndex','3')
    $bc = $overviewBC.data.selected_pair_overview
    Check ($bc.left_record_id -ceq $bId -and $bc.right_record_id -ceq $cId -and
        $bc.counts.changed_path_count -eq 1 -and
        $bc.counts.matching_path_count -eq 4 -and
        $bc.counts.neither_reported_path_count -eq 2 -and
        $bc.counts.left_only_path_count -eq 1 -and
        ($bc.changed_path_indices -join ',') -ceq '3' -and
        $bc.paths[1].pair_path_class -ceq 'neither_reported' -and
        $bc.paths[3].pair_path_class -ceq 'neither_reported' -and
        $bc.paths[1].left.original_record_scoped_finding_refs.Count -eq 0 -and
        $null -eq $bc.paths[1].left.saved_severity_statement_counts -and
        $bc.paths[0].pair_path_class -ceq 'retained_same_profile') 'EC-045 lost both-endpoint-unreported paths, stable path or canonical pair #3.'
    foreach ($badOverviewArgs in @(
        @('-SequencePairOverviewIndex',''),
        @('-SequencePairOverviewIndex','0'),
        @('-SequencePairOverviewIndex','01'),
        @('-SequencePairOverviewIndex','067'),
        @('-SequencePairOverviewIndex','67'),
        @('-SequencePairOverviewIndex','-1'),
        @('-SequencePairOverviewIndex','1.5'),
        @('-SequencePairOverviewIndex','x'),
        @('-SequencePairOverviewIndex','1','-SequencePath','src/A.txt'),
        @('-SequencePairOverviewIndex','1','-SequencePath','src/A.txt','-SequenceAnchorIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePath','src/A.txt','-SequencePairIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePath','src/A.txt',
            '-SequenceFindingRecordId',$aId,'-SequenceFindingId','F1')
    )) {
        $badOverview = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More (
            @('-Mode','Sequence','-SequenceRecordIds',$query) + $badOverviewArgs)
        Check ($badOverview.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_OVERVIEW_SELECTOR_INVALID' -and
            $null -eq $badOverview.data) 'EC-045 accepted malformed, contextless or conflicting global pair focus.'
    }
    $missingOverview = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequencePairOverviewIndex','66')
    Check ($missingOverview.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_NOT_FOUND' -and
        $null -eq $missingOverview.data) 'EC-045 invented an out-of-range global report pair.'
    $wrongOverviewMode = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','List','-SequencePairOverviewIndex','1')
    $wrongOverviewAction = Run-CES -Action Inspect -Repo $repo -Exit 4 -More @(
        '-SequencePairOverviewIndex','1')
    Check ($wrongOverviewMode.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE' -and
        $wrongOverviewAction.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE') 'EC-045 global pair selector escaped the read-only Sequence mode.'

    # EC-046: jump straight from an EC-045 pair overview path ordinal to the
    # complete EC-044 original-ID/quote-anchor report-pair comparison. The
    # path index is never a Top hotspot index and is not a mutable file path.
    $indexedAB = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','1',
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1')
    $abNavigation = $indexedAB.data.selected_pair_path_selection
    $abSelected = $indexedAB.data.path_focus.selected_pair
    Check ($abNavigation.scope -ceq 'one_indexed_path_within_selected_report_pair_complete_anchor_drilldown' -and
        $abNavigation.pair_index_in_pairwise_profile -eq 1 -and
        $abNavigation.path_index_in_selected_pair_overview -eq 1 -and
        $abNavigation.path -ceq 'file Ω.txt' -and
        $abNavigation.pair_path_class -ceq 'retained_changed_profile' -and
        $abNavigation.left_record_id -ceq $aId -and $abNavigation.right_record_id -ceq $bId -and
        $abNavigation.original_finding_refs_conserved -and
        $abNavigation.independent_of_sequence_top -and
        $indexedAB.data.path_focus.path -ceq 'file Ω.txt' -and
        $abSelected.path -ceq 'file Ω.txt' -and
        $abSelected.pair_index_in_anchor_pair_details -eq 1 -and
        $abSelected.counts.left_original_finding_statement_count -eq 2 -and
        $abSelected.counts.right_original_finding_statement_count -eq 1 -and
        $abNavigation.complete_anchor_union_count -eq $abSelected.anchors.Count -and
        $indexedAB.data.selected_pair_overview.paths.Count -eq 5) 'EC-046 could not resolve exact Unicode path and original ID-preserving pair focus.'

    # The indexed route is semantically IDENTICAL to the old literal-path
    # EC-044 query. Only the new navigation metadata / global overview differ.
    $literalAB = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','1',
        '-SequencePath','file Ω.txt','-SequencePairIndex','1')
    $indexedABWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','20',
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1')
    Check (($abSelected | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($literalAB.data.path_focus.selected_pair | ConvertTo-Json -Depth 32 -Compress) -and
        ($abSelected | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($indexedABWide.data.path_focus.selected_pair | ConvertTo-Json -Depth 32 -Compress) -and
        ($abNavigation | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($indexedABWide.data.selected_pair_path_selection | ConvertTo-Json -Depth 32 -Compress) -and
        ($overview | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($indexedAB.data.selected_pair_overview | ConvertTo-Json -Depth 32 -Compress) -and
        -not ($overviewAB.data.PSObject.Properties.Name -contains 'selected_pair_path_selection') -and
        -not ($result.data.PSObject.Properties.Name -contains 'selected_pair_path_selection')) 'EC-046 changed earlier results or depends on SequenceTop.'

    # For B/C path index 2, only A reported this path. EC-044's all-N
    # union must show real anchors with neither selected endpoint reporting.
    $indexedBCAbsent = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','3','-SequencePairPathIndex','2')
    $bcAbsentNavigation = $indexedBCAbsent.data.selected_pair_path_selection
    $bcAbsentPair = $indexedBCAbsent.data.path_focus.selected_pair
    Check ($bcAbsentNavigation.path -ceq 'src/A.txt' -and
        $bcAbsentNavigation.pair_index_in_pairwise_profile -eq 3 -and
        $bcAbsentNavigation.pair_path_class -ceq 'neither_reported' -and
        $bcAbsentPair.left_record_id -ceq $bId -and $bcAbsentPair.right_record_id -ceq $cId -and
        $bcAbsentPair.counts.distinct_exact_anchor_union_count -gt 0 -and
        $bcAbsentPair.counts.both_unreported_anchor_count -eq $bcAbsentPair.anchors.Count -and
        $bcAbsentPair.counts.left_original_finding_statement_count -eq 0 -and
        $bcAbsentPair.counts.right_original_finding_statement_count -eq 0 -and
        $bcAbsentPair.anchors[0].anchor_pair_class -ceq 'both_unreported' -and
        $bcAbsentPair.anchors[0].left.original_record_scoped_finding_refs.Count -eq 0 -and
        $null -eq $bcAbsentPair.anchors[0].left.saved_severity_statement_counts -and
        $bcAbsentNavigation.complete_anchor_union_count -eq
            $bcAbsentNavigation.both_endpoints_unreported_anchor_count) 'EC-046 invented original IDs for neither-endpoint path or discarded third-record anchors.'
    $indexedLowercase = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','5')
    Check ($indexedLowercase.data.selected_pair_path_selection.path -ceq 'src/a.txt' -and
        $indexedLowercase.data.path_focus.selected_pair.counts.left_original_finding_statement_count -eq 0 -and
        $indexedLowercase.data.path_focus.selected_pair.counts.right_original_finding_statement_count -gt 0 -and
        $indexedLowercase.data.selected_pair_path_selection.pair_path_class -ceq 'right_only') 'EC-046 treated path case as equivalent or used a Top-limited index.'

    foreach ($badPairPathArgs in @(
        @('-SequencePairPathIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex',''),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','0'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','01'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','-1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','481'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','9999'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1.5'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','q'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePath','src/a.txt'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequenceAnchorIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1',
            '-SequenceFindingRecordId',$aId,'-SequenceFindingId','F1')
    )) {
        $badIndexed = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More (
            @('-Mode','Sequence','-SequenceRecordIds',$query) + $badPairPathArgs)
        Check ($badIndexed.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_PATH_SELECTOR_INVALID' -and
            $null -eq $badIndexed.data) 'EC-046 accepted malformed/contextless/competing indexed path selector.'
    }
    $missingIndexedPath = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','6')
    $missingIndexedPair = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','66','-SequencePairPathIndex','1')
    $missingEmptyPath = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$zeroId,$zero2Id",
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1')
    Check ($missingIndexedPath.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_PATH_NOT_FOUND' -and
        $null -eq $missingIndexedPath.data -and
        $missingIndexedPair.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_NOT_FOUND' -and
        $null -eq $missingIndexedPair.data -and
        $missingEmptyPath.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_PATH_NOT_FOUND' -and
        $null -eq $missingEmptyPath.data) 'EC-046 fabricated non-existent selected pair path or confused pair vs path absence.'
    $wrongIndexedMode = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','List','-SequencePairPathIndex','1')
    $wrongIndexedAction = Run-CES -Action Inspect -Repo $repo -Exit 4 -More @(
        '-SequencePairPathIndex','1')
    Check ($wrongIndexedMode.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE' -and
        $wrongIndexedAction.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE') 'EC-046 escaped Sequence mode or read-only CodeShow action.'

    # EC-047: pair -> path -> ONE exact saved quote anchor with three
    # canonical ordinals, no manual case-sensitive path or six-field key.
    # This joins EC-044's two original scoped Finding sets to EC-043's
    # all-positions/all-pairs view without using SequenceTop previews.
    $indexedAnchorAB = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','1',
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1',
        '-SequencePairPathAnchorIndex','1')
    $anchorNavAB = $indexedAnchorAB.data.selected_pair_path_anchor_selection
    $anchorFullAB = $indexedAnchorAB.data.path_focus.selected_anchor
    Check ($anchorNavAB.scope -ceq 'one_indexed_exact_anchor_within_indexed_report_pair_path' -and
        $anchorNavAB.pair_index_in_pairwise_profile -eq 1 -and
        $anchorNavAB.path_index_in_selected_pair_overview -eq 1 -and
        $anchorNavAB.anchor_index_in_anchor_journeys -eq 1 -and
        $anchorNavAB.path -ceq 'file Ω.txt' -and
        $anchorNavAB.anchor.path -ceq 'file Ω.txt' -and
        $anchorNavAB.anchor_pair_class -ceq 'retained_changed_severity' -and
        $anchorNavAB.cross_view_original_finding_refs_conserved -and
        $anchorNavAB.independent_of_sequence_top -and
        $anchorNavAB.left.record_id -ceq $aId -and
        $anchorNavAB.right.record_id -ceq $bId -and
        $anchorNavAB.left.original_record_scoped_finding_refs.Count -eq 2 -and
        ($anchorNavAB.left.original_record_scoped_finding_refs | ForEach-Object { $_.finding_id }) -join ',' -ceq 'F1,F2' -and
        $anchorNavAB.right.original_record_scoped_finding_refs.Count -eq 1 -and
        $anchorNavAB.right.original_record_scoped_finding_refs[0].finding_id -ceq 'F1' -and
        $anchorFullAB.selected_record_count -eq 3 -and
        $anchorFullAB.compared_pairs.Count -eq 3 -and
        $anchorFullAB.compared_pairs[0].anchor_pair_class -ceq $anchorNavAB.anchor_pair_class -and
        $indexedAnchorAB.data.path_focus.selected_pair.anchors.Count -eq 1 -and
        $indexedAnchorAB.data.selected_pair_overview.paths.Count -eq 5) 'EC-047 three-index Unicode anchor navigation failed to preserve original endpoint IDs or all-N evidence.'

    $literalAnchorAB = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','1',
        '-SequencePath','file Ω.txt','-SequenceAnchorIndex','1')
    $indexedAnchorABWide = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,'-SequenceTop','20',
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1',
        '-SequencePairPathAnchorIndex','1')
    Check (($anchorFullAB | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($literalAnchorAB.data.path_focus.selected_anchor | ConvertTo-Json -Depth 32 -Compress) -and
        ($anchorFullAB | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($indexedAnchorABWide.data.path_focus.selected_anchor | ConvertTo-Json -Depth 32 -Compress) -and
        ($anchorNavAB | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($indexedAnchorABWide.data.selected_pair_path_anchor_selection | ConvertTo-Json -Depth 32 -Compress) -and
        ($indexedAB.data.path_focus.selected_pair | ConvertTo-Json -Depth 32 -Compress) -ceq
            ($indexedAnchorAB.data.path_focus.selected_pair | ConvertTo-Json -Depth 32 -Compress) -and
        -not ($indexedAB.data.PSObject.Properties.Name -contains 'selected_pair_path_anchor_selection') -and
        -not ($overviewAB.data.PSObject.Properties.Name -contains 'selected_pair_path_anchor_selection') -and
        -not ($result.data.PSObject.Properties.Name -contains 'selected_pair_path_anchor_selection')) 'EC-047 altered previous projections or depended on SequenceTop.'

    # B/C both omit the A-only path; the selected canonical anchor exists
    # because A is a third selected report. It MUST retain both absent
    # endpoint cells and nonempty A original Finding evidence in all-N focus.
    $indexedAnchorBC = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','3','-SequencePairPathIndex','2',
        '-SequencePairPathAnchorIndex','1')
    $absentNav = $indexedAnchorBC.data.selected_pair_path_anchor_selection
    $absentFull = $indexedAnchorBC.data.path_focus.selected_anchor
    Check ($absentNav.path -ceq 'src/A.txt' -and
        $absentNav.anchor_pair_class -ceq 'both_unreported' -and
        -not $absentNav.anchor_changed_in_pair -and
        $absentNav.left.record_id -ceq $bId -and
        $absentNav.right.record_id -ceq $cId -and
        -not $absentNav.left.reported_same_exact_saved_quote_anchor -and
        -not $absentNav.right.reported_same_exact_saved_quote_anchor -and
        $absentNav.left.original_record_scoped_finding_refs.Count -eq 0 -and
        $absentNav.right.original_record_scoped_finding_refs.Count -eq 0 -and
        $null -eq $absentNav.left.saved_severity_statement_counts -and
        $null -eq $absentNav.right.saved_severity_statement_counts -and
        $absentFull.positions[0].original_record_scoped_finding_refs.Count -gt 0 -and
        $absentFull.positions[1].original_record_scoped_finding_refs.Count -eq 0 -and
        $absentFull.positions[2].original_record_scoped_finding_refs.Count -eq 0 -and
        $absentFull.compared_pairs[2].anchor_pair_class -ceq 'both_unreported') 'EC-047 invented same-anchor IDs for two absent endpoints or dropped the third-report witness.'

    $indexedAnchorCase = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','5',
        '-SequencePairPathAnchorIndex','1')
    Check ($indexedAnchorCase.data.selected_pair_path_anchor_selection.path -ceq 'src/a.txt' -and
        $indexedAnchorCase.data.selected_pair_path_anchor_selection.anchor_pair_class -ceq 'right_only' -and
        $indexedAnchorCase.data.selected_pair_path_anchor_selection.left.original_record_scoped_finding_refs.Count -eq 0 -and
        $indexedAnchorCase.data.selected_pair_path_anchor_selection.right.original_record_scoped_finding_refs.Count -gt 0) 'EC-047 lost case-sensitive saved-path navigation or right-only original evidence.'

    foreach ($badTripleArgs in @(
        @('-SequencePairPathAnchorIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathAnchorIndex','1'),
        @('-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex',''),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','0'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','01'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','-1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','481'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','9999'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','1.2'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','x'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','1','-SequencePath','src/A.txt'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','1','-SequencePairIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','1','-SequenceAnchorIndex','1'),
        @('-SequencePairOverviewIndex','1','-SequencePairPathIndex','1','-SequencePairPathAnchorIndex','1',
            '-SequenceFindingRecordId',$aId,'-SequenceFindingId','F1')
    )) {
        $invalidTriple = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More (
            @('-Mode','Sequence','-SequenceRecordIds',$query) + $badTripleArgs)
        Check ($invalidTriple.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_PATH_ANCHOR_SELECTOR_INVALID' -and
            $null -eq $invalidTriple.data) 'EC-047 accepted malformed, contextless or competing third ordinal.'
    }
    $missingTripleAnchor = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1',
        '-SequencePairPathAnchorIndex','2')
    $missingTriplePath = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','6',
        '-SequencePairPathAnchorIndex','1')
    $missingTriplePair = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','66','-SequencePairPathIndex','1',
        '-SequencePairPathAnchorIndex','1')
    $missingTripleEmpty = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','Sequence','-SequenceRecordIds',"$zeroId,$zero2Id",
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1',
        '-SequencePairPathAnchorIndex','1')
    Check ($missingTripleAnchor.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_PATH_ANCHOR_NOT_FOUND' -and
        $missingTriplePath.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_PATH_NOT_FOUND' -and
        $missingTriplePair.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_NOT_FOUND' -and
        $missingTripleEmpty.reason_code -eq 'CODE_SHOW_SEQUENCE_PAIR_PATH_NOT_FOUND' -and
        $null -eq $missingTripleAnchor.data -and $null -eq $missingTriplePath.data -and
        $null -eq $missingTriplePair.data -and $null -eq $missingTripleEmpty.data) 'EC-047 failed to distinguish absent pair, path and anchor or leaked partial data.'
    $wrongTripleMode = Run-CES -Action CodeShow -Repo $repo -Exit 4 -More @(
        '-Mode','List','-SequencePairPathAnchorIndex','1')
    $wrongTripleAction = Run-CES -Action Inspect -Repo $repo -Exit 4 -More @(
        '-SequencePairPathAnchorIndex','1')
    Check ($wrongTripleMode.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE' -and
        $wrongTripleAction.reason_code -eq 'CODE_SHOW_SELECTORS_NOT_APPLICABLE') 'EC-047 selector escaped read-only Sequence action/mode.'

    # EC-048: fourth-level original Finding navigation. Indices are scoped to
    # the original Finding IDs at ONE endpoint of ONE indexed saved anchor.
    # Existing EC-042 full Finding journey must be IDENTICAL, not rederived.
    $fourthCommon = @('-Mode','Sequence','-SequenceRecordIds',$query,
        '-SequencePairOverviewIndex','1','-SequencePairPathIndex','1',
        '-SequencePairPathAnchorIndex','1')
    $leftFirst = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More (
        $fourthCommon + @('-SequencePairPathAnchorFindingSide','left',
                         '-SequencePairPathAnchorFindingIndex','1','-SequenceTop','1'))
    $leftSecond = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More (
        $fourthCommon + @('-SequencePairPathAnchorFindingSide','left',
                         '-SequencePairPathAnchorFindingIndex','2','-SequenceTop','1'))
    $rightFirst = Run-CES -Action CodeShow -Repo $repo -Exit 0 -More (
        $fourthCommon + @('-SequencePairPathAnchorFindingSide','right',
                         '-SequencePairPathAnchorFindingIndex','1','-SequenceTop','1'))
    $leftFirstNav = $leftFirst.data.selected_pair_path_anchor_finding_selection
    $leftSecondNav = $leftSecond.data.selected_pair_path_anchor_finding_selection
    $rightFirstNav = $rightFirst.data.selected_pair_path_anchor_finding_selection
    Check ($leftFirstNav.scope -ceq 'one_indexed_original_record_scoped_Finding_in_pair_path_anchor_endpoint' -and
        $leftFirstNav.pair_index_in_pairwise_profile -eq 1 -and
        $leftFirstNav.path_index_in_selected_pair_overview -eq 1 -and
