    $twelveConstituents = @(
        [pscustomobject]@{ Name = 'pair'; Ordinals = $twelveRows[0].original_constituent_position_pair_indices; Participation = $twelve.ordered_original_pair_duodecet_participation; Expected = 66 },
        [pscustomobject]@{ Name = 'triple'; Ordinals = $twelveRows[0].original_constituent_position_triple_indices; Participation = $twelve.ordered_original_triple_duodecet_participation; Expected = 220 },
        [pscustomobject]@{ Name = 'quartet'; Ordinals = $twelveRows[0].original_constituent_position_quartet_indices; Participation = $twelve.ordered_original_quartet_duodecet_participation; Expected = 495 },
        [pscustomobject]@{ Name = 'quintet'; Ordinals = $twelveRows[0].original_constituent_position_quintet_indices; Participation = $twelve.ordered_original_quintet_duodecet_participation; Expected = 792 },
        [pscustomobject]@{ Name = 'sextet'; Ordinals = $twelveRows[0].original_constituent_position_sextet_indices; Participation = $twelve.ordered_original_sextet_duodecet_participation; Expected = 924 },
        [pscustomobject]@{ Name = 'septet'; Ordinals = $twelveRows[0].original_constituent_position_septet_indices; Participation = $twelve.ordered_original_septet_duodecet_participation; Expected = 792 },
        [pscustomobject]@{ Name = 'octet'; Ordinals = $twelveRows[0].original_constituent_position_octet_indices; Participation = $twelve.ordered_original_octet_duodecet_participation; Expected = 495 },
        [pscustomobject]@{ Name = 'nonet'; Ordinals = $twelveRows[0].original_constituent_position_nonet_indices; Participation = $twelve.ordered_original_nonet_duodecet_participation; Expected = 220 },
        [pscustomobject]@{ Name = 'decet'; Ordinals = $twelveRows[0].original_constituent_position_decet_indices; Participation = $twelve.ordered_original_decet_duodecet_participation; Expected = 66 },
        [pscustomobject]@{ Name = 'undecet'; Ordinals = $twelveRows[0].original_constituent_position_undecet_indices; Participation = $twelve.ordered_original_undecet_duodecet_participation; Expected = 12 }
    )
    Check ($twelve.ordered_original_position_duodecet_participation.Count -eq 12 -and
