            $_.duodecets_with_additional_independent_loss_beyond_stronger_undecet -ne 0
        })).Count -eq 0) 'EC-070 lost all twelve position ancestor incidences.'
    foreach ($level in $twelveConstituents) {
        Check (@($level.Ordinals).Count -eq $level.Expected -and
            $level.Ordinals[0] -eq 1 -and
            $level.Ordinals[-1] -eq $level.Expected -and
            @($level.Participation).Count -eq $level.Expected -and
            (@($level.Participation | Where-Object {
                $_.number_of_position_duodecets_containing_constituent -ne 1 -or
                $_.duodecets_reducing_original_independent_maximum -ne 1 -or
                $_.duodecets_reducing_original_local_optimum_maximum -ne 1 -or
                $_.minimally_twelfth_order_critical_duodecets_for_original_independent_maximum -ne 0 -or
                $_.minimally_twelfth_order_critical_duodecets_for_original_local_optimum_maximum -ne 0 -or
                $_.duodecets_with_additional_independent_loss_beyond_stronger_undecet -ne 0 -or
                $_.duodecets_with_additional_original_local_optimum_loss_beyond_stronger_undecet -ne 0
            })).Count -eq 0) "EC-070 changed original $($level.Name) ancestry or original six-flag participation conservation."
    }

    $twelveTwo = $cohortTwo.data.path_focus.selected_original_finding_pair_profile_duodecet_position_withholding
    $twelveTen = $tenAView.data.path_focus.selected_original_finding_pair_profile_duodecet_position_withholding
    $twelveEleven = $elevenAllAView.data.path_focus.selected_original_finding_pair_profile_duodecet_position_withholding
    Check ($twelveTwo.counts.unordered_original_position_duodecet_count -eq 0 -and
        $null -eq $twelveTwo.counts.minimum_global_independent_family_maximum_after_twelve_withheld_positions -and
        $twelveTwo.ordered_original_pair_duodecet_participation.Count -eq 1 -and
        $twelveTen.counts.unordered_original_position_duodecet_count -eq 0 -and
        $null -eq $twelveTen.counts.maximum_global_original_local_optimum_family_maximum_after_twelve_withheld_positions -and
        $twelveEleven.counts.unordered_original_position_duodecet_count -eq 0 -and
        $twelveEleven.ordered_original_position_duodecet_participation.Count -eq 11 -and
        $null -eq $twelveEleven.counts.minimum_global_independent_family_maximum_after_twelve_withheld_positions -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_duodecet_position_withholding') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_duodecet_position_withholding')) 'EC-070 violated N2/N10/N11 absence, null-vs-zero or unchanged successful-selector-only isolation.'

    # EC-071: one cube across EVERY EC-059..070 withholding order. Rebuild
    # genuine/frozen original evidence by subset zeta (not by row flags) and
    # extract only inclusion-minimal cuts of actual saved motif evidence.
    $frontier = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_resilience_frontier
    $frontierReversed = $tripleRight.data.path_focus.selected_original_finding_pair_profile_resilience_frontier
    $frontierSmall = $cohortTwo.data.path_focus.selected_original_finding_pair_profile_resilience_frontier
    $frontierTen = $tenAView.data.path_focus.selected_original_finding_pair_profile_resilience_frontier
    $frontierEleven = $elevenAllAView.data.path_focus.selected_original_finding_pair_profile_resilience_frontier
    $frontierTwelveBySize = @($frontier.original_exclusion_cardinality_summary)
    $familyFrontiers = @($frontier.original_family_extinction_frontiers)
    Check ($frontier.scope -ceq 'complete_original_report_withholding_resilience_frontiers_exact_saved_witness_masks_no_resequencing' -and
        $frontier.counts.selected_original_report_positions -eq 12 -and
        $frontier.counts.original_exclusion_sets_including_empty -eq 4096 -and
        $frontier.counts.nonempty_original_exclusion_sets -eq 4095 -and
        $frontier.counts.original_global_independent_maximum -eq 3 -and
        $frontier.counts.original_global_frozen_maximum -eq 3 -and
        $frontier.counts.genuine_inclusion_minimal_global_first_loss_cut_count -gt 0 -and
        $frontier.counts.frozen_inclusion_minimal_global_first_loss_cut_count -gt 0 -and
        $frontier.counts.genuine_inclusion_minimal_complete_support_extinction_cut_count -gt 0 -and
        $frontier.counts.frozen_inclusion_minimal_complete_support_extinction_cut_count -gt 0 -and
        $frontier.counts.genuine_minimum_positions_for_first_global_loss -ge 1 -and
        $frontier.counts.genuine_minimum_positions_for_first_global_loss -le 12 -and
        $frontier.original_caller_position_bit_legend.Count -eq 12 -and
        ($frontier.original_caller_position_bit_legend.original_saved_record_id -join ',') -ceq ($tripleIds -join ',') -and
        $frontier.original_caller_position_bit_legend[11].exclusion_mask_bit -eq 2048 -and
        $frontier.genuine_global_loss_threshold_frontiers.Count -eq 3 -and
        $frontier.frozen_global_loss_threshold_frontiers.Count -eq 3 -and
        $frontier.genuine_global_loss_threshold_frontiers[0].residual_global_maximum_strictly_below -eq 3 -and
        $frontier.genuine_global_loss_threshold_frontiers[2].residual_global_maximum_strictly_below -eq 1 -and
        $frontierTwelveBySize.Count -eq 13 -and
        $frontierTwelveBySize[0].original_exclusion_subset_count -eq 1 -and
        $frontierTwelveBySize[6].original_exclusion_subset_count -eq 924 -and
        $frontierTwelveBySize[12].original_exclusion_subset_count -eq 1 -and
        $frontierTwelveBySize[12].minimum_independent_distinct_family_maximum -eq 0 -and
        $frontierTwelveBySize[12].minimum_frozen_distinct_family_maximum -eq 0 -and
        $frontierTwelveBySize[12].subsets_reducing_original_independent_maximum -eq 1 -and
        $familyFrontiers.Count -eq $frontier.counts.original_maximal_repeat_family_count -and
        $frontier.all_ec059_to_ec070_original_exclusion_rows_reconciled -and
        $frontier.all_six_genuine_and_frozen_original_survivor_levels_reconstructed_from_private_weighted_masks -and
        $frontier.original_full_selection_local_optima_frozen_not_reoptimized -and
        $frontier.independent_of_sequence_top -and $frontier.two_original_finding_journeys_remain_independent -and
        -not $frontier.source_git_network_reads_or_business_worktree_writes -and
        ($frontier | ConvertTo-Json -Depth 80 -Compress) -ceq
            ($frontierReversed | ConvertTo-Json -Depth 80 -Compress) -and
        -not (($frontier | ConvertTo-Json -Depth 80 -Compress) -match
            'private sequence quote|Synthetic historical sequence seed|original reasoning')) 'EC-071 lost exact full-cube evidence, minimum-cut frontiers, original IDs or privacy/seed/Top symmetry.'

    foreach ($threshold in @($frontier.genuine_global_loss_threshold_frontiers) +
        @($frontier.frozen_global_loss_threshold_frontiers)) {
        $cuts = @($threshold.inclusion_minimal_original_exclusion_masks)
        Check ($cuts.Count -eq $threshold.inclusion_minimal_cut_count -and
            $cuts.Count -gt 0 -and
            $threshold.minimum_withheld_original_positions -ge 1 -and
            (@($cuts | Where-Object { $_ -lt 1 -or $_ -ge 4096 })).Count -eq 0 -and
