    }
    foreach ($family in $familyFrontiers) {
        Check ($family.original_maximal_repeat_family_index -ge 1 -and
            $family.original_maximal_repeat_family_index -le $familyFrontiers.Count -and
            @($family.genuine_inclusion_minimal_extinction_original_exclusion_masks).Count -eq
