    }
    Check ($frontierSmall.counts.original_exclusion_sets_including_empty -eq 4 -and
        $frontierSmall.original_exclusion_cardinality_summary.Count -eq 3 -and
        $frontierSmall.original_exclusion_cardinality_summary[2].original_exclusion_subset_count -eq 1 -and
        $frontierTen.counts.original_exclusion_sets_including_empty -eq 1024 -and
        $frontierTen.original_exclusion_cardinality_summary.Count -eq 11 -and
        $frontierEleven.counts.original_exclusion_sets_including_empty -eq 2048 -and
        $frontierEleven.original_exclusion_cardinality_summary.Count -eq 12 -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_resilience_frontier') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_resilience_frontier')) 'EC-071 failed N2/N10/N11/N12 boundaries or selector/error isolation.'

    # EC-072: the exact dual of every ORIGINAL loss cut is an ORIGINAL
    # inclusion-minimal retained-position witness basis. A restoration
    # certificate for excluded p must supply a real basis intersecting that
    # cut in exactly bit(p), and no other excluded original position.
    $basisDuality = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_support_basis_duality
    $basisReversed = $tripleRight.data.path_focus.selected_original_finding_pair_profile_support_basis_duality
    $basisTwo = $cohortTwo.data.path_focus.selected_original_finding_pair_profile_support_basis_duality
    $basisTen = $tenAView.data.path_focus.selected_original_finding_pair_profile_support_basis_duality
    $basisEleven = $elevenAllAView.data.path_focus.selected_original_finding_pair_profile_support_basis_duality
    Check ($basisDuality.scope -ceq 'minimal_retained_original_witness_bases_and_exact_exclusion_cut_restoration_duality' -and
        $basisDuality.counts.original_selected_report_positions -eq 12 -and
        $basisDuality.counts.original_exclusion_masks_checked -eq 4096 -and
        $basisDuality.counts.genuine_original_global_maximum -eq 3 -and
        $basisDuality.counts.frozen_original_global_maximum -eq 3 -and
        $basisDuality.counts.genuine_global_threshold_support_basis_frontiers -eq 3 -and
        $basisDuality.counts.frozen_global_threshold_support_basis_frontiers -eq 3 -and
