        $basisDuality.genuine_global_threshold_retained_support_bases[0].original_global_family_capacity_at_least -eq 3 -and
        $basisDuality.genuine_global_threshold_retained_support_bases[0].retained_position_support_basis_and_loss_cut_restorations.inclusion_minimal_retained_support_basis_count -eq 1 -and
        $basisDuality.genuine_global_threshold_retained_support_bases[0].retained_position_support_basis_and_loss_cut_restorations.inclusion_minimal_retained_original_position_masks[0] -eq 4095 -and
        $basisDuality.frozen_global_threshold_retained_support_bases[0].retained_position_support_basis_and_loss_cut_restorations.inclusion_minimal_retained_original_position_masks[0] -eq 4095 -and
        $basisDuality.all_ec071_minimal_loss_cuts_have_exact_original_basis_hitting_set_duality -and
        $basisDuality.every_excluded_position_in_every_minimal_cut_has_a_real_minimal_basis_restoration -and
        $basisDuality.original_full_selection_frozen_optima_not_reoptimized -and
        $basisDuality.independent_of_sequence_top -and $basisDuality.two_original_finding_journeys_remain_independent -and
        -not $basisDuality.source_git_network_reads_or_business_worktree_writes -and
        ($basisDuality | ConvertTo-Json -Depth 80 -Compress) -ceq
            ($basisReversed | ConvertTo-Json -Depth 80 -Compress) -and
        -not (($basisDuality | ConvertTo-Json -Depth 80 -Compress) -match
            'private sequence quote|Synthetic historical sequence seed|original reasoning')) 'EC-072 failed N12 genuine/frozen bases, exact triple support, selector-side symmetry or no-leak boundary.'

    $dualBlocks = [System.Collections.Generic.List[object]]::new()
    foreach ($front in @($basisDuality.genuine_global_threshold_retained_support_bases) +
        @($basisDuality.frozen_global_threshold_retained_support_bases)) {
        $dualBlocks.Add($front.retained_position_support_basis_and_loss_cut_restorations)
    }
    foreach ($family in @($basisDuality.individual_original_family_retained_support_bases)) {
        $dualBlocks.Add($family.genuine_retained_position_support_basis_and_restorations)
        $dualBlocks.Add($family.frozen_retained_position_support_basis_and_restorations)
    }
    foreach ($block in $dualBlocks) {
        $bases = [int[]]$block.inclusion_minimal_retained_original_position_masks
        $certs = @($block.exact_single_position_restoration_certificates)
        Check ($bases.Count -eq $block.inclusion_minimal_retained_support_basis_count -and
            $certs.Count -eq $block.verified_ec071_inclusion_minimal_exclusion_cut_count -and
            @($block.original_retained_basis_cardinality_summary).Count -eq 13 -and
            @($block.original_position_basis_and_cut_incidence).Count -eq 12 -and
            (@($bases | Sort-Object -Unique).Count -eq $bases.Count) -and
            $block.every_ec071_original_cut_dual_and_every_excluded_position_restorable) 'EC-072 truncated an exact original minimal-support dual ledger.'
        foreach ($base in $bases) {
            Check ($base -ge 1 -and $base -le 4095 -and
                (@($bases | Where-Object { $_ -ne $base -and (($_ -band $base) -eq $_) })).Count -eq 0) 'EC-072 kept a nonminimal or fabricated real witness support basis.'
        }
        foreach ($cert in $certs) {
            $cut = [int]$cert.original_exclusion_mask
            $restored = [int[]]$cert.minimal_retained_basis_mask_for_each_restored_excluded_position
            $k = 0
            for ($p = 0; $p -lt 12; $p++) {
                $bit = 1 -shl $p
                if (($cut -band $bit) -eq 0) { continue }
                Check ($k -lt $restored.Count -and $bases -contains $restored[$k] -and
                    (($restored[$k] -band $cut) -eq $bit)) 'EC-072 fabricated a one-position restoration witness.'
                $k++
            }
            Check ($k -eq $restored.Count) 'EC-072 restoration certificates are not aligned with ascending excluded positions.'
        }
        if ($bases.Count -eq 0) {
            Check ($null -eq $block.minimum_original_positions_to_retain_for_support -and
                $certs.Count -eq 0) 'EC-072 fabricated a retained support basis or loss cut without original evidence.'
        }
    }
    Check ($basisTwo.counts.original_exclusion_masks_checked -eq 4 -and
        @($basisTwo.genuine_global_threshold_retained_support_bases).Count -eq 0 -and
        $basisTen.counts.original_exclusion_masks_checked -eq 1024 -and
        $basisEleven.counts.original_exclusion_masks_checked -eq 2048 -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_support_basis_duality') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_support_basis_duality')) 'EC-072 changed N2/N10/N11 boundaries or earlier-selector failure behavior.'

    # EC-073: every ORIGINAL retained-budget (0..N) and every directed
    # K -> K|bit(p) edge is counted exactly once, genuine and frozen.
    # A pivotal edge is an actual absent-to-present saved witness transition;
    # the restored minimal EC-072 ORIGINAL basis must include the added bit.
    $pivotality = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_pivotality
    $pivotalityReversed = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_pivotality
    $pivotalityTwo = $cohortTwo.data.path_focus.selected_original_finding_pair_profile_retention_pivotality
    $pivotalityTen = $tenAView.data.path_focus.selected_original_finding_pair_profile_retention_pivotality
    $pivotalityEleven = $elevenAllAView.data.path_focus.selected_original_finding_pair_profile_retention_pivotality
    Check ($pivotality.scope -ceq 'exact_original_retention_budget_coverage_and_single_position_evidence_pivotality' -and
        $pivotality.counts.original_selected_report_positions -eq 12 -and
        $pivotality.counts.exact_original_retained_masks_checked_per_target -eq 4096 -and
        $pivotality.counts.exact_original_directed_position_additions_checked_per_target -eq 24576 -and
        $pivotality.counts.genuine_original_global_thresholds -eq 3 -and
        $pivotality.counts.frozen_original_global_thresholds -eq 3 -and
        $pivotality.counts.original_individual_family_targets -eq $familyFrontiers.Count -and
        $pivotality.uses_ec071_exact_original_position_bit_legend_without_reindexing -and
        $pivotality.reconciles_ec072_all_minimal_retained_bases_and_position_criticality -and
        $pivotality.each_original_directed_edge_counted_once_and_all_budget_identities_verified -and
