            $cube.unsupported_retained_original_mask_count -eq 4095 -and
            $cube.minimum_retained_original_positions_with_real_support -eq 12 -and
            $cube.original_directed_single_position_addition_edge_count -eq 24576 -and
            $cube.total_evidence_pivotal_directed_addition_edges -eq 12 -and
            $cube.retained_original_budget_coverage.Count -eq 13 -and
            $cube.retained_original_budget_coverage[11].subsets_preserving_original_witness_support -eq 0 -and
            $cube.retained_original_budget_coverage[11].pivotal_one_position_additions_to_next_budget -eq 12 -and
            $cube.retained_original_budget_coverage[12].subsets_preserving_original_witness_support -eq 1 -and
            $cube.original_position_pivotal_additions.Count -eq 12 -and
            $cube.original_positions_sorted_by_evidence_pivotal_addition_count.Count -eq 12) 'EC-073 failed the real 12-position triple-only edge/coverage boundary.'
        for ($p = 0; $p -lt 12; $p++) {
