            $bit = 1 -shl $p
            Check ($one.original_caller_position -eq $p + 1 -and
                $one.original_position_bit -eq $bit -and
                $one.pivotal_addition_count_across_all_other_retained_masks -eq 1 -and
                $one.original_other_retained_masks_considered -eq 2048 -and
