        $allPivotalTargets.Add($row.frozen_original_retention_budget_coverage_and_pivotal_additions)
    }
    foreach ($cube in $allPivotalTargets) {
        $budget = @($cube.retained_original_budget_coverage)
        $positions = @($cube.original_position_pivotal_additions)
        $edgeSum = 0
        Check ($budget.Count -eq 13 -and $positions.Count -eq 12 -and
            $cube.original_retained_mask_count -eq 4096 -and
            $cube.original_directed_single_position_addition_edge_count -eq 24576 -and
            $cube.ec072_exact_minimal_original_retained_bases_reconciled -and
            $cube.all_original_budget_edge_conservation_identities_verified -and
