        for ($k = 0; $k -le 12; $k++) {
            $bin = $budget[$k]
            Check ($bin.number_of_retained_original_positions -eq $k -and
                ($bin.subsets_preserving_original_witness_support +
                    $bin.subsets_without_original_witness_support) -eq
                    $bin.possible_original_retained_subsets) 'EC-073 altered an exact retained original position budget.'
            if ($k -lt 12) {
                $byPosition = 0
                foreach ($one in $positions) {
                    $byPosition += $one.pivotal_additions_by_other_retained_budget[$k].pivotal_original_position_additions
                }
                Check ($bin.pivotal_one_position_additions_to_next_budget -eq $byPosition -and
