    $orderAttribution = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_order_attribution
    $orderAttributionReversed = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_order_attribution
    $orderTwo = $cohortTwo.data.path_focus.selected_original_finding_pair_profile_retention_order_attribution
    $orderTen = $tenAView.data.path_focus.selected_original_finding_pair_profile_retention_order_attribution
    $orderEleven = $elevenAllAView.data.path_focus.selected_original_finding_pair_profile_retention_order_attribution
    Check ($orderAttribution.scope -ceq 'exact_original_permutation_first_saved_evidence_restoration_by_step_and_pivotal_position' -and
