        -not (($orderAttribution | ConvertTo-Json -Depth 90 -Compress) -match
            'private sequence quote|Synthetic historical sequence seed|original reasoning')) 'EC-074 changed original report identity, symmetry, privacy or permutation denominator.'

    # The synthetic N12 global triple-only support needs ALL original reports.
    # Every full ordering first supports the triple at step 12, and each
    # original position can trigger that first support iff it is last.
    foreach ($target in @($orderAttribution.genuine_global_threshold_first_support_permutations[0],
        $orderAttribution.frozen_global_threshold_first_support_permutations[0])) {
        Check ($target.original_global_family_capacity_at_least -eq 3 -and
            $target.original_full_selection_global_family_capacity -eq 3) 'EC-074 changed the genuine/frozen original triple capacity.'
        $attribution = $target.exact_first_support_permutation_attribution
        $steps = @($attribution.first_support_restoration_by_retained_step)
        $positionShares = @($attribution.original_position_first_support_permutation_attribution)
        Check ($attribution.total_distinct_permutations_of_original_caller_positions -eq 479001600 -and
