            $attribution.total_full_permutations_with_exactly_one_first_support_restoration -eq 479001600 -and
            $steps.Count -eq 13 -and $positionShares.Count -eq 12 -and
            $steps[12].permutations_first_restoring_saved_evidence_at_this_step -eq 479001600 -and
            $steps[11].permutations_with_saved_evidence_after_this_step -eq 0) 'EC-074 failed exact full-set triple first-restoration boundary.'
        for ($k = 0; $k -lt 12; $k++) {
            Check ($steps[$k].permutations_first_restoring_saved_evidence_at_this_step -eq 0) 'EC-074 invented early genuine/frozen triple evidence.'
        }
        for ($p = 0; $p -lt 12; $p++) {
            $one = $positionShares[$p]
            Check ($one.original_caller_position -eq $p + 1 -and
                $one.original_position_bit -eq (1 -shl $p) -and
                $one.exact_permutations_in_which_this_position_first_restores_saved_evidence -eq 39916800 -and
                $one.original_permutations_in_full_enumeration -eq 479001600 -and
                $one.exact_reduced_attribution_fraction_numerator -eq 1 -and
                $one.exact_reduced_attribution_fraction_denominator -eq 12 -and
                $one.earliest_possible_first_support_step -eq 12 -and
                $one.latest_possible_first_support_step -eq 12 -and
                $one.by_first_support_step.Count -eq 12 -and
                $one.by_first_support_step[11].full_original_permutations_restored_by_this_position_at_this_step -eq 39916800 -and
                $one.original_ec073_minimal_real_restoration_certificate.real_ec072_inclusion_minimal_basis_now_supported -eq 4095) 'EC-074 misattributed an exact ORIGINAL last-position permutation.'
        }
    }

    # Each target has two INDEPENDENT exact calculations of first-support
    # permutations: differences in cumulative budget support and the sum of
    # full-ordering weights of each EC-073 ORIGINAL directed pivotal edge.
    $allOrderPairs = [System.Collections.Generic.List[object]]::new()
    for ($i = 0; $i -lt $orderAttribution.genuine_global_threshold_first_support_permutations.Count; $i++) {
        $allOrderPairs.Add([pscustomobject]@{
            Orders = $orderAttribution.genuine_global_threshold_first_support_permutations[$i].exact_first_support_permutation_attribution
            Cube = $pivotality.genuine_global_threshold_retention_coverage[$i].original_retention_budget_coverage_and_pivotal_additions
        })
    }
    for ($i = 0; $i -lt $orderAttribution.frozen_global_threshold_first_support_permutations.Count; $i++) {
        $allOrderPairs.Add([pscustomobject]@{
            Orders = $orderAttribution.frozen_global_threshold_first_support_permutations[$i].exact_first_support_permutation_attribution
            Cube = $pivotality.frozen_global_threshold_retention_coverage[$i].original_retention_budget_coverage_and_pivotal_additions
        })
    }
    for ($i = 0; $i -lt $orderAttribution.individual_original_family_first_support_permutations.Count; $i++) {
        $allOrderPairs.Add([pscustomobject]@{
            Orders = $orderAttribution.individual_original_family_first_support_permutations[$i].genuine_original_first_support_permutation_attribution
            Cube = $pivotality.individual_original_family_retention_coverage[$i].genuine_original_retention_budget_coverage_and_pivotal_additions
        })
        $allOrderPairs.Add([pscustomobject]@{
            Orders = $orderAttribution.individual_original_family_first_support_permutations[$i].frozen_original_first_support_permutation_attribution
            Cube = $pivotality.individual_original_family_retention_coverage[$i].frozen_original_retention_budget_coverage_and_pivotal_additions
        })
    }
    $factorials = [long[]]::new(13)
    $factorials[0] = [long]1
    for ($j = 1; $j -le 12; $j++) { $factorials[$j] = $factorials[$j - 1] * $j }
    foreach ($pair in $allOrderPairs) {
        $a = $pair.Orders
        $cube = $pair.Cube
        $budgetRows = @($a.first_support_restoration_by_retained_step)
        $positionRows = @($a.original_position_first_support_permutation_attribution)
        Check ($a.total_distinct_permutations_of_original_caller_positions -eq $factorials[12] -and
            $budgetRows.Count -eq 13 -and $positionRows.Count -eq 12 -and
            $a.each_original_directed_pivotal_edge_weighted_by_actual_complete_permutation_multiplicity -and
            $a.first_support_step_counts_equal_independent_supported_budget_differences -and
            $a.all_full_orderings_partitioned_by_unique_first_restoration_or_never_supported -and
            $a.attribution_is_uniform_theoretical_order_combinatorics_not_observed_frequency -and
            $a.saved_evidence_attribution_does_not_prove_real_world_causality_or_repair) 'EC-074 omitted a complete original permutation evidence target.'
        $cumulative = [long]0
        $lastCumulative = [long]0
        for ($j = 0; $j -le 12; $j++) {
            $expected = [long]$cube.retained_original_budget_coverage[$j].subsets_preserving_original_witness_support *
                $factorials[$j] * $factorials[12 - $j]
            $now = $budgetRows[$j]
            Check ($now.number_of_first_original_reports_retained -eq $j -and
                $now.permutations_with_saved_evidence_after_this_step -eq $expected -and
                $now.permutations_without_saved_evidence_after_this_step -eq ($factorials[12] - $expected) -and
                $now.permutations_first_restoring_saved_evidence_at_this_step -eq ($expected - $lastCumulative)) 'EC-074 failed independently recomputed original retained-budget permutation counts.'
            $cumulative += [long]$now.permutations_first_restoring_saved_evidence_at_this_step
            $lastCumulative = $expected
        }
        $weightedPositionSum = [long]0
        for ($p = 0; $p -lt 12; $p++) {
            $one = $positionRows[$p]
            $pivot = $cube.original_position_pivotal_additions[$p]
            $perPosition = [long]0
            for ($k = 0; $k -lt 12; $k++) {
                $expected = [long]$pivot.pivotal_additions_by_other_retained_budget[$k].pivotal_original_position_additions *
                    $factorials[$k] * $factorials[11 - $k]
                Check ($one.by_first_support_step[$k].first_evidence_restoration_at_retained_step -eq ($k + 1) -and
                    $one.by_first_support_step[$k].full_original_permutations_restored_by_this_position_at_this_step -eq $expected) 'EC-074 first-restoration position ledger disagreed with a real EC-073 original directed edge.'
                $perPosition += $expected
            }
            Check ($one.exact_permutations_in_which_this_position_first_restores_saved_evidence -eq $perPosition -and
                ($one.exact_reduced_attribution_fraction_numerator * $factorials[12]) -eq
                    ($one.exact_reduced_attribution_fraction_denominator * $perPosition)) 'EC-074 exact original attribution fraction is inconsistent.'
            $weightedPositionSum += $perPosition
        }
        Check ($weightedPositionSum -eq $cumulative -and
            $weightedPositionSum -eq $a.total_full_permutations_with_exactly_one_first_support_restoration -and
            $weightedPositionSum -eq $factorials[12] * [int]($cube.full_original_selection_saved_witness_multiplicity -gt 0)) 'EC-074 lost, duplicated or fabricated a complete original ordering''s first support.'
        if ($cube.full_original_selection_saved_witness_multiplicity -eq 0) {
