                $weightedPositionSum -eq 0 -and
                $positionRows[0].exact_reduced_attribution_fraction_numerator -eq 0 -and
                $positionRows[0].exact_reduced_attribution_fraction_denominator -eq 1 -and
                $null -eq $positionRows[0].original_ec073_minimal_real_restoration_certificate) 'EC-074 fabricated original family evidence or probability on an unsupported baseline.'
        }
    }
    Check ($orderTwo.counts.exact_original_distinct_permutations_per_target -eq 2 -and
        $orderTen.counts.exact_original_distinct_permutations_per_target -eq 3628800 -and
        $orderEleven.counts.exact_original_distinct_permutations_per_target -eq 39916800 -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_order_attribution') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_order_attribution')) 'EC-074 changed N2/N10/N11 exact permutation counts or selector-failure isolation.'

    # EC-075: condition on a fixed ORIGINAL report p at every hypothetical
    # position/rank j. EVERY one of the (N-1)! complete orderings with p
    # fixed there first restores evidence before p, by p, after p, or never.
    # Cross-check original EC-072 bases, EC-073 real p-edges and EC-074 full
    # ordering margins; do not construe the invented order as chronology.
    $fixedRank = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_rank_conditioning
    $fixedRankReversed = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_rank_conditioning
    $fixedTwo = $cohortTwo.data.path_focus.selected_original_finding_pair_profile_retention_rank_conditioning
    $fixedTen = $tenAView.data.path_focus.selected_original_finding_pair_profile_retention_rank_conditioning
    $fixedEleven = $elevenAllAView.data.path_focus.selected_original_finding_pair_profile_retention_rank_conditioning
    Check ($fixedRank.scope -ceq 'exact_original_first_saved_evidence_restoration_conditioned_on_fixed_report_rank' -and
        $fixedRank.counts.original_selected_report_positions -eq 12 -and
        $fixedRank.counts.exact_original_distinct_permutations_per_target -eq 479001600 -and
        $fixedRank.counts.exact_permutations_given_one_original_position_at_one_fixed_rank -eq 39916800 -and
        $fixedRank.counts.fixed_rank_scenarios_per_target -eq 144 -and
        $fixedRank.counts.genuine_original_global_thresholds -eq 3 -and
        $fixedRank.counts.frozen_original_global_thresholds -eq 3 -and
        $fixedRank.counts.individual_original_family_targets -eq $familyFrontiers.Count -and
        $fixedRank.original_ec071_bit_legend_and_caller_order_unchanged -and
        $fixedRank.no_new_selector_or_original_evidence_read_and_no_reoptimization -and
        $fixedRank.independent_of_sequence_top_and_original_finding_seed_side -and
        $fixedRank.hypothetical_rank_is_not_authenticated_chronology_or_empirical_probability -and
        $fixedRank.no_saved_quote_body_patch_git_network_or_business_source_access -and
        $fixedRank.conditional_evidence_attribution_is_not_a_real_defect_risk_rank_or_causal_repair -and
        ($fixedRank | ConvertTo-Json -Depth 90 -Compress) -ceq
