    # N12 synthetic triple target has exactly one real minimal basis: 4095.
    # Any given p fixed before the last rank implies first support LATER;
    # when p is fixed last, p ALONE crosses the threshold in all 11! cases.
    foreach ($target in @($fixedRank.genuine_global_threshold_fixed_rank_conditioning[0],
        $fixedRank.frozen_global_threshold_fixed_rank_conditioning[0])) {
        Check ($target.original_global_family_capacity_at_least -eq 3 -and
            $target.original_full_selection_global_family_capacity -eq 3) 'EC-075 changed an original triple-only capacity.'
        $projection = $target.exact_first_support_fixed_rank_conditioning
        Check ($projection.full_original_selection_has_saved_witness_support -and
            $projection.original_position_conditioned_on_fixed_hypothetical_rank.Count -eq 12 -and
            $projection.independent_full_ordering_conservation_across_all_positions_at_each_rank.Count -eq 12) 'EC-075 did not populate every real N12 original fixed-rank scenario.'
        for ($p = 0; $p -lt 12; $p++) {
            $one = $projection.original_position_conditioned_on_fixed_hypothetical_rank[$p]
            Check ($one.original_caller_position -eq $p + 1 -and
                $one.original_position_bit -eq (1 -shl $p) -and
                $one.exact_permutations_first_restored_by_this_position_across_every_possible_fixed_rank -eq 39916800 -and
