            for ($j = 1; $j -le 12; $j++) {
                $fixed = $one.scenarios_by_fixed_hypothetical_rank[$j - 1]
                $by = if ($j -eq 12) { [long]39916800 } else { [long]0 }
                $later = if ($j -eq 12) { [long]0 } else { [long]39916800 }
