        $spectrum12.frozen_global_threshold_pair_distance_spectrum[0])) {
        $projection = $entry.exact_first_support_pair_distance_spectrum
        Check ($entry.original_global_family_capacity_at_least -eq 3 -and
            $entry.original_full_selection_global_family_capacity -eq 3 -and
            $projection.full_original_selection_has_saved_witness_support) 'EC-088 changed the genuine/frozen original full-only >=3 witness threshold.'
        foreach ($row in $projection.directed_original_report_pair_distance_spectra) {
            Check ($row.full_precedence_first_restored_by_second_report -eq 39916800 -and
                $row.full_precedence_first_restoring_after_second_report -eq 199584000 -and
                $row.full_precedence_first_restoring_between_reports -eq 0) 'EC-088 N12 full-only saved support did not reconcile to EC-076.'
            for ($g = 0; $g -le 10; $g++) {
                $case = $row.exact_distance_cases[$g]
                Check ($case.by_second -eq 3628800 -and
                    $case.after_second -eq [long](10 - $g) * [long]3628800 -and
                    $case.first_restored_between -eq 0 -and
                    $case.never -eq 0 -and
                    $case.exact_reduced_by_second_fraction_numerator -eq 1 -and
                    $case.exact_reduced_by_second_fraction_denominator -eq 11 - $g) 'EC-088 original full-only by-q conditional spectrum is not exact 1/(N-g-1).'
            }
        }
    }

    # EC-089: unordered ORIGINAL a/b reciprocity is the exact union of the
    # checked EC-088 a->b and b->a halves. It is never a report timestamp or
    # an empirical comparison of outcomes. Exercise every original target,
    # gap, endpoint bit, signed orientation contrast and restorer identity.
    $recip12 = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_pair_reciprocity
    $recipReverse = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_pair_reciprocity
    Check ($recip12.scope -ceq 'exact_original_unordered_report_pair_bidirectional_first_support_reciprocity' -and
        $recip12.counts.original_selected_report_positions -eq 12 -and
        $recip12.counts.unordered_original_report_pairs_per_target -eq 66 -and
        $recip12.counts.eligible_distances_per_unordered_pair -eq 11 -and
        $recip12.counts.exact_full_original_orderings_per_unordered_pair -eq 479001600 -and
        $recip12.counts.exact_unordered_pair_occurrences_across_all_full_original_permutations -eq 31614105600 -and
        $recip12.only_consumed_checked_ec088_and_independent_ec076_original_projections -and
        $recip12.original_ec071_bit_legend_and_caller_order_unchanged -and
        $recip12.independent_of_sequence_top_and_original_finding_seed_side -and
        $recip12.no_new_selector_or_original_evidence_read_and_no_reoptimization -and
        $recip12.no_saved_quote_body_patch_git_network_or_business_source_access -and
        $recip12.exact_incidence_fractions_are_not_empirical_probability_defect_priority_or_causal_repair -and
        ($recip12.genuine_global_threshold_pair_reciprocity[0].exact_first_support_pair_reciprocity.unordered_original_report_pair_reciprocities[0] |
            ConvertTo-Json -Depth 32 -Compress) -ceq
            ($recipReverse.genuine_global_threshold_pair_reciprocity[0].exact_first_support_pair_reciprocity.unordered_original_report_pair_reciprocities[0] |
            ConvertTo-Json -Depth 32 -Compress) -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_pair_reciprocity') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_pair_reciprocity')) 'EC-089 changed selector/seed/Top gating, target identities or native provenance.'

    foreach ($view in @($cohortTwo, $pairedLeft, $fourAView, $fiveAView,
        $sixSixView, $allSameSevenView, $eightAView, $nineAView,
        $tenAView, $elevenAllAView)) {
        $r = $view.data.path_focus.selected_original_finding_pair_profile_retention_pair_reciprocity
        $n = [int]$r.counts.original_selected_report_positions
        $factorial = [long]1
        for ($j = 2; $j -le $n; $j++) { $factorial *= $j }
        Check ($n -ge 2 -and $n -le 11 -and
            $r.counts.unordered_original_report_pairs_per_target -eq ($n * ($n - 1) / 2) -and
            $r.counts.eligible_distances_per_unordered_pair -eq $n - 1 -and
            $r.counts.exact_full_original_orderings_per_unordered_pair -eq $factorial -and
            $r.counts.exact_unordered_pair_occurrences_across_all_full_original_permutations -eq
                ([long]($n * ($n - 1) / 2) * $factorial)) 'EC-089 N2..11 lost its full N! unordered pair universe.'
        foreach ($entry in @($r.genuine_global_threshold_pair_reciprocity) +
            @($r.frozen_global_threshold_pair_reciprocity)) {
            $x = $entry.exact_first_support_pair_reciprocity
            Check ($x.every_unordered_pair_has_both_disjoint_original_precedence_directions -and
                $x.every_bidirectional_gap_reconciles_independent_ec074_via_ec088 -and
                $x.every_original_endpoint_and_intermediary_identity_mass_is_conserved -and
                $x.all_six_global_first_support_categories_match_independent_ec074_and_ec076 -and
                @($x.unordered_original_report_pair_reciprocities).Count -eq $n * ($n - 1) / 2 -and
                @($x.distance_histogram_across_unordered_original_pairs).Count -eq $n - 1) 'EC-089 N2..11 missing threshold, direction or gap.'
            foreach ($pair in $x.unordered_original_report_pair_reciprocities) {
                $a = [int]$pair.original_report_a_caller_position - 1
                $b = [int]$pair.original_report_b_caller_position - 1
                Check ($a -ge 0 -and $a -lt $b -and $b -lt $n -and
                    $pair.original_report_a_position_bit -eq (1 -shl $a) -and
                    $pair.original_report_b_position_bit -eq (1 -shl $b) -and
                    $pair.exact_full_original_orderings_with_either_endpoint_direction -eq $factorial -and
                    @($pair.distance_cases).Count -eq $n - 1 -and
                    @($pair.full_pair_first_restored_by_intervening_original_caller_position).Count -eq $n) 'EC-089 changed an ORIGINAL caller bit or pair/gap count.'
                $total = [long]0
                foreach ($gap in $pair.distance_cases) {
                    $g = [int]$gap.number_of_original_reports_strictly_between_pair
                    $expected = [long]2 * [long]($n - $g - 1)
                    for ($j = 2; $j -le ($n - 2); $j++) { $expected *= $j }
                    $total += [long]$gap.exact_full_original_orderings_with_either_endpoint_direction
                    Check ($g -ge 0 -and $g -le $n - 2 -and
                        $gap.exact_full_original_orderings_with_either_endpoint_direction -eq $expected -and
                        $gap.exact_full_original_orderings_per_endpoint_direction -eq $expected / 2 -and
                        @($gap.first_restored_by_intervening_original_caller_position).Count -eq $n) 'EC-089 produced a fabricated or incorrect reciprocal gap case.'
                }
                Check ($total -eq $factorial) 'EC-089 N2..11 reciprocal gaps do not exhaust N!.'
            }
        }
    }

    $recipTargets = [System.Collections.Generic.List[object]]::new()
    foreach ($entry in $recip12.genuine_global_threshold_pair_reciprocity) {
        $recipTargets.Add($entry.exact_first_support_pair_reciprocity)
    }
    foreach ($entry in $recip12.frozen_global_threshold_pair_reciprocity) {
        $recipTargets.Add($entry.exact_first_support_pair_reciprocity)
    }
    foreach ($entry in $recip12.individual_original_family_pair_reciprocity) {
        $recipTargets.Add($entry.genuine_original_first_support_pair_reciprocity)
        $recipTargets.Add($entry.frozen_original_first_support_pair_reciprocity)
    }
    Check ($recipTargets.Count -eq $specTargets.Count -and
        $recip12.genuine_global_threshold_pair_reciprocity.Count -eq 3 -and
        $recip12.frozen_global_threshold_pair_reciprocity.Count -eq 3 -and
        $recip12.individual_original_family_pair_reciprocity.Count -eq $spectrum12.individual_original_family_pair_distance_spectrum.Count) 'EC-089 dropped original genuine/frozen or supported/unsupported family targets.'

    for ($targetIndex = 0; $targetIndex -lt $recipTargets.Count; $targetIndex++) {
        $reciprocal = $recipTargets[$targetIndex]
        $directedSpec = $specTargets[$targetIndex]
        $pairs = @($reciprocal.unordered_original_report_pair_reciprocities)
        $rows = @($directedSpec.directed_original_report_pair_distance_spectra)
        $hist = @($reciprocal.distance_histogram_across_unordered_original_pairs)
        Check ($pairs.Count -eq 66 -and $rows.Count -eq 132 -and $hist.Count -eq 11 -and
            $reciprocal.full_original_selection_has_saved_witness_support -eq
                $directedSpec.full_original_selection_has_saved_witness_support -and
            $reciprocal.every_unordered_pair_has_both_disjoint_original_precedence_directions -and
            $reciprocal.every_bidirectional_gap_reconciles_independent_ec074_via_ec088 -and
            $reciprocal.every_original_endpoint_and_intermediary_identity_mass_is_conserved -and
            $reciprocal.all_six_global_first_support_categories_match_independent_ec074_and_ec076 -and
            $reciprocal.original_directional_contrasts_are_exact_not_probabilistic_or_chronological) 'EC-089 N12 target did not preserve checked ORIGINAL evidence boundaries.'
        $perPositionByEarlier = [long[]]::new(12)
        $perPositionByLater = [long[]]::new(12)
        $perPositionMiddle = [long[]]::new(12)
        foreach ($pair in $pairs) {
            $a = [int]$pair.original_report_a_caller_position - 1
            $b = [int]$pair.original_report_b_caller_position - 1
            $forward = $rows[$a * 11 + $b - 1]
            $reverse = $rows[$b * 11 + $a]
            $byA = [long]0
            $byB = [long]0
            $before = [long]0
            $after = [long]0
            $never = [long]0
            $between = [long]0
            $middle = [long[]]::new(12)
            Check ($a -ge 0 -and $a -lt $b -and $b -lt 12 -and
                $pair.original_report_a_position_bit -eq (1 -shl $a) -and
                $pair.original_report_b_position_bit -eq (1 -shl $b) -and
                $pair.exact_full_original_orderings_with_either_endpoint_direction -eq 479001600 -and
                @($pair.distance_cases).Count -eq 11) 'EC-089 lost N12 ORIGINAL pair/direction identity.'
            for ($g = 0; $g -le 10; $g++) {
                $case = $pair.distance_cases[$g]
                $fc = $forward.exact_distance_cases[$g]
                $rc = $reverse.exact_distance_cases[$g]
                $d = [long](11 - $g) * [long]3628800
                $aValue = [long]$fc.by_first + [long]$rc.by_second
                $bValue = [long]$fc.by_second + [long]$rc.by_first
                $delta = [long]$fc.by_second - [long]$rc.by_second
                $mass = [long]0
                foreach ($field in @('first_restoring_before_either_first_endpoint',
                    'first_restored_by_original_report_a','first_restored_by_original_report_b',
                    'first_restored_by_original_intervening_report',
                    'first_restoring_after_either_second_endpoint','never_restoring_saved_evidence')) {
                    $mass += [long]$case.$field
                }
                Check ($case.number_of_original_reports_strictly_between_pair -eq $g -and
                    $case.exact_full_original_orderings_with_either_endpoint_direction -eq (2 * $d) -and
                    $case.exact_full_original_orderings_per_endpoint_direction -eq $d -and
                    $mass -eq 2 * $d -and
                    $case.first_restored_by_original_report_a -eq $aValue -and
                    $case.first_restored_by_original_report_b -eq $bValue -and
                    $case.first_restored_when_later_in_a_before_b_direction -eq [long]$fc.by_second -and
                    $case.first_restored_when_later_in_b_before_a_direction -eq [long]$rc.by_second -and
                    $case.exact_signed_later_direction_contrast -eq $delta -and
                    [long]$case.exact_reduced_signed_later_direction_contrast_fraction.numerator * $d -eq
                        [long]$case.exact_reduced_signed_later_direction_contrast_fraction.denominator * $delta -and
                    [long]$case.exact_reduced_either_original_endpoint_first_restorer_fraction.numerator * (2 * $d) -eq
                        [long]$case.exact_reduced_either_original_endpoint_first_restorer_fraction.denominator * ($aValue + $bValue)) 'EC-089 N12 mismatch in reciprocal direction FIRST contrast or exact fraction.'
                $byA += $aValue
                $byB += $bValue
                $before += [long]$case.first_restoring_before_either_first_endpoint
                $after += [long]$case.first_restoring_after_either_second_endpoint
                $never += [long]$case.never_restoring_saved_evidence
                $between += [long]$case.first_restored_by_original_intervening_report
                $perPositionByEarlier[$a] += [long]$fc.by_first
                $perPositionByEarlier[$b] += [long]$rc.by_first
                $perPositionByLater[$a] += [long]$rc.by_second
                $perPositionByLater[$b] += [long]$fc.by_second
                $vector = @($case.first_restored_by_intervening_original_caller_position)
                Check ($vector.Count -eq 12 -and $vector[$a] -eq 0 -and $vector[$b] -eq 0) 'EC-089 credited an ORIGINAL endpoint as middle.'
                $middleSum = [long]0
                for ($j = 0; $j -lt 12; $j++) {
                    $expectedVector = [long]$fc.first_restored_between_by_original_caller_position[$j] +
                        [long]$rc.first_restored_between_by_original_caller_position[$j]
                    Check ([long]$vector[$j] -eq $expectedVector) 'EC-089 reattributed a first-restoring ORIGINAL intermediary.'
                    $middle[$j] += [long]$vector[$j]
                    $perPositionMiddle[$j] += [long]$vector[$j]
                    $middleSum += [long]$vector[$j]
                }
                Check ($middleSum -eq [long]$case.first_restored_by_original_intervening_report) 'EC-089 intermediary vector disagrees with the FIRST support ledger.'
                if (-not $reciprocal.full_original_selection_has_saved_witness_support) {
                    Check ($case.never_restoring_saved_evidence -eq 2 * $d -and
                        $aValue -eq 0 -and $bValue -eq 0 -and $middleSum -eq 0) 'EC-089 invented support for an unsupported ORIGINAL Finding.'
                }
            }
            Check ($byA -eq [long]$pair.full_pair_first_restored_by_original_report_a -and
                $byB -eq [long]$pair.full_pair_first_restored_by_original_report_b -and
                $before -eq [long]$pair.full_pair_first_restoring_before_first_endpoint -and
                $after -eq [long]$pair.full_pair_first_restoring_after_later_endpoint -and
                $never -eq [long]$pair.full_pair_never_restoring_saved_evidence -and
                $between -eq [long]$pair.full_pair_first_restored_between_endpoints -and
                $pair.full_pair_first_restored_by_earlier_endpoint + $pair.full_pair_first_restored_by_later_endpoint -eq $byA + $byB -and
                [long]$pair.exact_reduced_any_endpoint_first_restorer_fraction.numerator * 479001600 -eq
                    [long]$pair.exact_reduced_any_endpoint_first_restorer_fraction.denominator * ($byA + $byB)) 'EC-089 failed ORIGINAL unordered full N! pair conservation.'
            for ($j = 0; $j -lt 12; $j++) {
                Check ([long]$pair.full_pair_first_restored_by_intervening_original_caller_position[$j] -eq $middle[$j]) 'EC-089 failed full-pair original intermediary aggregation.'
            }
        }
        for ($g = 0; $g -le 10; $g++) {
            $sourceGap = $directedSpec.original_distance_histogram_across_all_directed_pairs[$g]
            $gap = $hist[$g]
            Check ($gap.number_of_original_reports_strictly_between_pair -eq $g -and
                $gap.exact_pair_occurrences_across_all_original_permutations -eq ([long](11 - $g) * 479001600) -and
                $gap.before_first_endpoint -eq [long]$sourceGap.before_first -and
                $gap.by_earlier_endpoint -eq [long]$sourceGap.by_first -and
                $gap.by_intervening_original_report -eq [long]$sourceGap.first_restored_between -and
                $gap.by_later_endpoint -eq [long]$sourceGap.by_second -and
                $gap.after_later_endpoint -eq [long]$sourceGap.after_second -and
                $gap.never -eq [long]$sourceGap.never -and
                @($gap.by_original_caller_position_as_intervening_report).Count -eq 12) 'EC-089 reciprocal original gap histogram differs from EC-088/074.'
        }
        for ($j = 0; $j -lt 12; $j++) {
            Check ($reciprocal.first_restored_by_original_caller_position_as_earlier_endpoint[$j] -eq $perPositionByEarlier[$j] -and
                $reciprocal.first_restored_by_original_caller_position_as_later_endpoint[$j] -eq $perPositionByLater[$j] -and
                $reciprocal.first_restored_by_original_caller_position_as_intervening_report[$j] -eq $perPositionMiddle[$j] -and
                $reciprocal.first_restored_by_original_caller_position_inside_pair_interval[$j] -eq
                    ($perPositionByEarlier[$j] + $perPositionByLater[$j] + $perPositionMiddle[$j])) 'EC-089 global ORIGINAL report FIRST-restorer identity is not conserved.'
        }
    }
    foreach ($global in @($recip12.genuine_global_threshold_pair_reciprocity[0],
        $recip12.frozen_global_threshold_pair_reciprocity[0])) {
        $projection = $global.exact_first_support_pair_reciprocity
        Check ($global.original_global_family_capacity_at_least -eq 3 -and
            $projection.full_original_selection_has_saved_witness_support) 'EC-089 lost the original N12 genuine/frozen full-only threshold.'
        foreach ($pair in $projection.unordered_original_report_pair_reciprocities) {
            Check ($pair.full_pair_first_restored_by_original_report_a -eq 39916800 -and
                $pair.full_pair_first_restored_by_original_report_b -eq 39916800 -and
                $pair.full_pair_first_restoring_after_later_endpoint -eq 399168000 -and
                $pair.full_pair_first_restored_between_endpoints -eq 0 -and
                $pair.full_pair_never_restoring_saved_evidence -eq 0) 'EC-089 N12 full-only pair FIRST support must be attributed to the final endpoint only.'
            for ($g = 0; $g -le 10; $g++) {
                $case = $pair.distance_cases[$g]
                Check ($case.first_restored_by_original_report_a -eq 3628800 -and
                    $case.first_restored_by_original_report_b -eq 3628800 -and
                    $case.first_restored_by_original_intervening_report -eq 0 -and
                    $case.exact_signed_later_direction_contrast -eq 0 -and
                    $case.exact_reduced_signed_later_direction_contrast_fraction.numerator -eq 0 -and
                    $case.exact_reduced_signed_later_direction_contrast_fraction.denominator -eq 1 -and
                    $case.exact_reduced_either_original_endpoint_first_restorer_fraction.numerator -eq 1 -and
                    $case.exact_reduced_either_original_endpoint_first_restorer_fraction.denominator -eq 11 - $g) 'EC-089 N12 full-only reciprocal gap fractions are not exact.'
            }
        }
        for ($j = 0; $j -lt 12; $j++) {
            Check ($projection.first_restored_by_original_caller_position_inside_pair_interval[$j] -eq 439084800) 'EC-089 N12 original full-only first-restorer incidence identity is wrong.'
        }
    }

    # EC-090: Per-ORIGINAL-report, role-conditional exposure is a distinct
    # denominator from first restoration. Reconcile against EC-089 pair rows
    # and identity histograms without assigning first restoration outside the
    # pair interval. All ordering counts are hypothetical and exact.
    $role12 = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_reporter_role_exposure
    $role12Reverse = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_reporter_role_exposure
    Check ($role12.scope -ceq 'exact_original_reporter_role_exposure_and_first_restoration_atlas' -and
        $role12.counts.original_selected_report_positions -eq 12 -and
        $role12.counts.original_reporter_roles_per_target -eq 12 -and
        $role12.counts.disjoint_original_distance_cases_per_reporter -eq 11 -and
        $role12.counts.hypothetical_full_original_orderings_per_unordered_pair -eq 479001600 -and
        $role12.only_consumed_checked_ec089_original_pair_reciprocity -and
        $role12.original_ec071_caller_bits_and_family_targets_unchanged -and
        $role12.independent_of_sequence_top_and_original_finding_seed_side -and
        $role12.outside_interval_first_restorer_identity_not_attributed -and
        $role12.hypothetical_role_exposure_not_empirical_probability_or_actual_chronology -and
        $role12.no_new_saved_evidence_source_git_network_or_business_write -and
        ($role12.genuine_global_threshold_reporter_role_exposure[0].exact_original_reporter_role_exposure.original_reporter_role_exposure_profiles[0] |
            ConvertTo-Json -Depth 32 -Compress) -ceq
            ($role12Reverse.genuine_global_threshold_reporter_role_exposure[0].exact_original_reporter_role_exposure.original_reporter_role_exposure_profiles[0] |
            ConvertTo-Json -Depth 32 -Compress) -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_reporter_role_exposure') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_reporter_role_exposure')) 'EC-090 lost original path/seed/Top gating or privacy provenance.'

    foreach ($view in @($cohortTwo, $pairedLeft, $fourAView, $fiveAView,
        $sixSixView, $allSameSevenView, $eightAView, $nineAView,
        $tenAView, $elevenAllAView)) {
        $atlas = $view.data.path_focus.selected_original_finding_pair_profile_retention_reporter_role_exposure
        $parent = $view.data.path_focus.selected_original_finding_pair_profile_retention_pair_reciprocity
        $n = [int]$atlas.counts.original_selected_report_positions
        $factorial = [long]1
        for ($j = 2; $j -le $n; $j++) { $factorial *= $j }
        Check ($n -ge 2 -and $n -le 11 -and
            $atlas.counts.original_reporter_roles_per_target -eq $n -and
            $atlas.counts.disjoint_original_distance_cases_per_reporter -eq $n - 1 -and
            $atlas.counts.hypothetical_full_original_orderings_per_unordered_pair -eq $factorial -and
            @($atlas.genuine_global_threshold_reporter_role_exposure).Count -eq 3 -and
            @($atlas.frozen_global_threshold_reporter_role_exposure).Count -eq 3 -and
            @($atlas.individual_original_family_reporter_role_exposure).Count -eq
                @($parent.individual_original_family_pair_reciprocity).Count) 'EC-090 N2..11 original role registry lost a family, threshold, or exact ordering universe.'
        foreach ($entry in @($atlas.genuine_global_threshold_reporter_role_exposure) +
            @($atlas.frozen_global_threshold_reporter_role_exposure)) {
            $projection = $entry.exact_original_reporter_role_exposure
            Check (@($projection.original_reporter_role_exposure_profiles).Count -eq $n -and
                @($projection.distance_first_restorer_role_histogram).Count -eq $n - 1 -and
                $projection.every_original_report_has_exact_pair_endpoint_and_nonendpoint_exposures -and
                $projection.every_original_gap_exposure_partitions_full_unordered_pair_universe -and
                $projection.every_original_role_first_restorer_count_is_within_exposure_denominator -and
                $projection.every_reporter_gap_first_restorer_reconciles_independent_ec089_pair_rows -and
                $projection.all_reporter_first_restorer_role_counts_match_independent_ec074_via_ec089 -and
                $projection.no_outside_first_restorer_identity_inferred) 'EC-090 N2..11 original role conservation flags missing.'
            foreach ($reporter in $projection.original_reporter_role_exposure_profiles) {
                $k = [int]$reporter.original_report_caller_position - 1
                Check ($k -ge 0 -and $k -lt $n -and
                    $reporter.original_report_position_bit -eq (1 -shl $k) -and
                    $reporter.original_unordered_endpoint_partners -eq $n - 1 -and
                    $reporter.original_unordered_nonendpoint_pairs -eq ([int](($n - 1) * ($n - 2) / 2)) -and
                    @($reporter.distance_cases).Count -eq $n - 1 -and
                    $reporter.full_original_ordering_role_exposure_as_earlier_endpoint -eq ([long]($n - 1) * ($factorial / 2)) -and
                    $reporter.full_original_ordering_role_exposure_as_later_endpoint -eq ([long]($n - 1) * ($factorial / 2))) 'EC-090 N2..11 original report endpoint exposure is not balanced.'
                foreach ($case in $reporter.distance_cases) {
                    $g = [int]$case.number_of_original_reports_strictly_between_pair
                    $d = [long]($n - $g - 1)
                    for ($j = 2; $j -le $n - 2; $j++) { $d *= $j }
                    $roleTotal = [long]$case.exact_role_exposure_as_earlier_endpoint +
                        [long]$case.exact_role_exposure_as_later_endpoint +
                        [long]$case.exact_role_exposure_as_strictly_intervening_report +
                        [long]$case.exact_role_exposure_outside_pair_interval
                    Check ($g -ge 0 -and $g -lt $n - 1 -and
                        $case.exact_role_exposure_as_earlier_endpoint -eq ([long]($n - 1) * $d) -and
                        $case.exact_role_exposure_as_later_endpoint -eq ([long]($n - 1) * $d) -and
                        $roleTotal -eq ([long]($n * ($n - 1) / 2) * 2 * $d) -and
                        $case.first_restored_as_earlier_endpoint -le $case.exact_role_exposure_as_earlier_endpoint -and
                        $case.first_restored_as_later_endpoint -le $case.exact_role_exposure_as_later_endpoint -and
                        $case.first_restored_as_strictly_intervening_report -le $case.exact_role_exposure_as_strictly_intervening_report -and
                        $case.first_restored_inside_pair_interval -eq
                            ($case.first_restored_as_earlier_endpoint + $case.first_restored_as_later_endpoint + $case.first_restored_as_strictly_intervening_report)) 'EC-090 N2..11 reporter role exposures lost gap mass or FIRST conservation.'
                    if ($g -eq 0) {
                        Check ($case.exact_role_exposure_as_strictly_intervening_report -eq 0 -and
                            $null -eq $case.exact_reduced_first_restorer_fraction_given_intervening_role) 'EC-090 fabricated a middle conditional denominator at gap zero.'
                    } else {
                        $fraction = $case.exact_reduced_first_restorer_fraction_given_intervening_role
                        Check ($null -ne $fraction -and
                            [long]$fraction.numerator * $case.exact_role_exposure_as_strictly_intervening_report -eq
                                [long]$fraction.denominator * $case.first_restored_as_strictly_intervening_report) 'EC-090 lost middle FIRST conditional fraction.'
                    }
                }
            }
        }
    }

    $roleTargets = [System.Collections.Generic.List[object]]::new()
    foreach ($entry in $role12.genuine_global_threshold_reporter_role_exposure) {
        $roleTargets.Add($entry.exact_original_reporter_role_exposure)
    }
    foreach ($entry in $role12.frozen_global_threshold_reporter_role_exposure) {
        $roleTargets.Add($entry.exact_original_reporter_role_exposure)
    }
    foreach ($entry in $role12.individual_original_family_reporter_role_exposure) {
        $roleTargets.Add($entry.genuine_original_reporter_role_exposure)
        $roleTargets.Add($entry.frozen_original_reporter_role_exposure)
    }
    Check ($roleTargets.Count -eq $recipTargets.Count -and
        $role12.counts.individual_original_family_targets -eq
            $recip12.counts.individual_original_family_targets) 'EC-090 N12 dropped real supported/unsupported original family targets.'
    for ($i = 0; $i -lt $roleTargets.Count; $i++) {
        $target = $roleTargets[$i]
        $parent = $recipTargets[$i]
        Check ($target.original_positions_in_reporter_role_atlas -eq 12 -and
            $target.total_distinct_full_original_permutations -eq 479001600 -and
            $target.exact_unordered_original_pair_count -eq 66 -and
            $target.full_original_selection_has_saved_witness_support -eq
                $parent.full_original_selection_has_saved_witness_support -and
            @($target.original_reporter_role_exposure_profiles).Count -eq 12 -and
            @($target.distance_first_restorer_role_histogram).Count -eq 11) 'EC-090 changed an original N12 target universe.'
        $roll = [long[]]::new(3)
        for ($k = 0; $k -lt 12; $k++) {
            $reporter = $target.original_reporter_role_exposure_profiles[$k]
            $e = [long]0
            $l = [long]0
            $m = [long]0
            $middleExposure = [long]0
            $outsideExposure = [long]0
            Check ($reporter.original_report_caller_position -eq $k + 1 -and
                $reporter.original_report_position_bit -eq (1 -shl $k) -and
                @($reporter.distance_cases).Count -eq 11) 'EC-090 N12 original caller-position reporter bit was reindexed.'
            for ($g = 0; $g -le 10; $g++) {
                $gap = $reporter.distance_cases[$g]
                $parentGap = $parent.distance_histogram_across_unordered_original_pairs[$g]
                $d = [long](11 - $g) * [long]3628800
                $earlyExposure = [long]11 * $d
                $midExposure = [long]55 * [long]2 * [long]$g * [long](11 - $g) * [long]362880
                $outExposure = [long]55 * [long]2 * [long](10 - $g) * [long](11 - $g) * [long]362880
                $incidence = [long]66 * 2 * $d
                $sumExposures = [long]$gap.exact_role_exposure_as_earlier_endpoint +
                    [long]$gap.exact_role_exposure_as_later_endpoint +
                    [long]$gap.exact_role_exposure_as_strictly_intervening_report +
                    [long]$gap.exact_role_exposure_outside_pair_interval
                Check ($gap.number_of_original_reports_strictly_between_pair -eq $g -and
                    $gap.exact_full_unordered_pair_gap_incidence_for_reporter -eq $incidence -and
                    $gap.exact_role_exposure_as_earlier_endpoint -eq $earlyExposure -and
                    $gap.exact_role_exposure_as_later_endpoint -eq $earlyExposure -and
                    $gap.exact_role_exposure_as_strictly_intervening_report -eq $midExposure -and
                    $gap.exact_role_exposure_outside_pair_interval -eq $outExposure -and
                    $sumExposures -eq $incidence -and
                    $gap.first_restored_as_earlier_endpoint -eq
                        [long]$parentGap.by_original_caller_position_as_earlier_endpoint[$k] -and
                    $gap.first_restored_as_later_endpoint -eq
                        [long]$parentGap.by_original_caller_position_as_later_endpoint[$k] -and
                    $gap.first_restored_as_strictly_intervening_report -eq
                        [long]$parentGap.by_original_caller_position_as_intervening_report[$k]) 'EC-090 N12 report-gap exposure arithmetic or independent EC-089 original identity is wrong.'
                foreach ($spec in @(@($gap.exact_reduced_first_restorer_fraction_given_earlier_endpoint, $earlyExposure, $gap.first_restored_as_earlier_endpoint),
                    @($gap.exact_reduced_first_restorer_fraction_given_later_endpoint, $earlyExposure, $gap.first_restored_as_later_endpoint),
                    @($gap.exact_reduced_first_restorer_fraction_given_any_endpoint, (2 * $earlyExposure),
                        ($gap.first_restored_as_earlier_endpoint + $gap.first_restored_as_later_endpoint)),
                    @($gap.exact_reduced_first_restorer_fraction_given_inside_pair_interval,
                        (2 * $earlyExposure + $midExposure), $gap.first_restored_inside_pair_interval))) {
                    Check ([long]$spec[0].numerator * [long]$spec[1] -eq
                        [long]$spec[0].denominator * [long]$spec[2]) 'EC-090 N12 role-conditioned exact fraction does not reproduce its FIRST numerator.'
                }
                if ($g -eq 0) {
                    Check ($null -eq $gap.exact_reduced_first_restorer_fraction_given_intervening_role -and
                        $midExposure -eq 0) 'EC-090 N12 created a forbidden middle conditional fraction.'
                } else {
                    $f = $gap.exact_reduced_first_restorer_fraction_given_intervening_role
                    Check ([long]$f.numerator * $midExposure -eq
                        [long]$f.denominator * $gap.first_restored_as_strictly_intervening_report) 'EC-090 N12 middle conditional fraction is inaccurate.'
                }
                $e += [long]$gap.first_restored_as_earlier_endpoint
                $l += [long]$gap.first_restored_as_later_endpoint
                $m += [long]$gap.first_restored_as_strictly_intervening_report
                $middleExposure += $midExposure
                $outsideExposure += $outExposure
                if (-not $target.full_original_selection_has_saved_witness_support) {
                    Check ($gap.first_restored_inside_pair_interval -eq 0 -and
                        $gap.exact_reduced_first_restorer_fraction_given_later_endpoint.numerator -eq 0) 'EC-090 invented a FIRST restorer for an originally unsupported Finding.'
                }
            }
            Check ($e -eq $reporter.first_restored_as_earlier_endpoint_across_all_gaps -and
                $l -eq $reporter.first_restored_as_later_endpoint_across_all_gaps -and
                $m -eq $reporter.first_restored_as_intervening_report_across_all_gaps -and
                $e -eq [long]$parent.first_restored_by_original_caller_position_as_earlier_endpoint[$k] -and
                $l -eq [long]$parent.first_restored_by_original_caller_position_as_later_endpoint[$k] -and
                $m -eq [long]$parent.first_restored_by_original_caller_position_as_intervening_report[$k] -and
                $e + $l + $m -eq $reporter.first_restored_inside_pair_interval_across_all_gaps -and
                $middleExposure -eq 8781696000 -and
                $outsideExposure -eq 17563392000 -and
                $reporter.full_original_ordering_role_exposure_as_strictly_intervening_report -eq $middleExposure -and
                $reporter.full_original_ordering_role_exposure_outside_pair_interval -eq $outsideExposure -and
                $reporter.full_original_ordering_role_exposure_as_earlier_endpoint -eq 2634508800 -and
                $reporter.full_original_ordering_role_exposure_as_later_endpoint -eq 2634508800) 'EC-090 N12 full-gap ORIGINAL reporter role census fails conservation.'
            $roll[0] += $e
            $roll[1] += $l
            $roll[2] += $m
        }
        Check ($roll[0] -eq $target.first_restored_by_all_original_earlier_endpoint_roles -and
            $roll[1] -eq $target.first_restored_by_all_original_later_endpoint_roles -and
            $roll[2] -eq $target.first_restored_by_all_original_intervening_roles -and
            $roll[0] + $roll[1] + $roll[2] -eq $target.first_restored_by_all_original_reporters_inside_pair_interval) 'EC-090 N12 global ORIGINAL role-ledger does not partition FIRST support.'
    }
    foreach ($entry in @($role12.genuine_global_threshold_reporter_role_exposure[0],
        $role12.frozen_global_threshold_reporter_role_exposure[0])) {
        Check ($entry.original_global_family_capacity_at_least -eq 3 -and
            $entry.original_full_selection_global_family_capacity -eq 3 -and
            $entry.exact_original_reporter_role_exposure.full_original_selection_has_saved_witness_support) 'EC-090 changed the ORIGINAL N12 full-only >=3 target.'
        foreach ($reporter in $entry.exact_original_reporter_role_exposure.original_reporter_role_exposure_profiles) {
            Check ($reporter.first_restored_as_earlier_endpoint_across_all_gaps -eq 0 -and
                $reporter.first_restored_as_later_endpoint_across_all_gaps -eq 439084800 -and
                $reporter.first_restored_as_intervening_report_across_all_gaps -eq 0 -and
                $reporter.exact_reduced_first_restorer_fraction_given_later_endpoint.numerator -eq 1 -and
                $reporter.exact_reduced_first_restorer_fraction_given_later_endpoint.denominator -eq 6) 'EC-090 N12 full-only original first-restorer role identity or exact fraction is wrong.'
            foreach ($gap in $reporter.distance_cases) {
                $g = [int]$gap.number_of_original_reports_strictly_between_pair
                Check ($gap.first_restored_as_earlier_endpoint -eq 0 -and
                    $gap.first_restored_as_later_endpoint -eq 39916800 -and
                    $gap.first_restored_as_strictly_intervening_report -eq 0 -and
                    $gap.exact_reduced_first_restorer_fraction_given_later_endpoint.numerator -eq 1 -and
                    $gap.exact_reduced_first_restorer_fraction_given_later_endpoint.denominator -eq 11 - $g) 'EC-090 N12 full-only gap-role FIRST restoration is not exactly 1/(11-g).'
            }
        }
    }

    # EC-091: Each ORIGINAL reporter has N-1 named endpoint partners, and
    # each partner contributes separate exact earlier/later FIRST incidences.
    # Reconcile every cell against checked EC-089 pair directions and EC-090
    # role/gap identities; do not promote hypothetical ordering to time.
    $partner12 = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_reporter_partner_matrix
    $partner12Reverse = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_reporter_partner_matrix
    Check ($partner12.scope -ceq 'exact_original_reporter_partner_endpoint_first_restoration_matrix' -and
        $partner12.counts.original_selected_report_positions -eq 12 -and
        $partner12.counts.original_reporter_partner_directed_cells_per_target -eq 132 -and
        $partner12.counts.exact_original_unordered_pair_count_per_target -eq 66 -and
        $partner12.counts.gap_cases_per_directed_reporter_partner_cell -eq 11 -and
        $partner12.only_consumed_checked_ec089_and_ec090_public_original_projections -and
        $partner12.original_ec071_caller_bits_and_family_targets_unchanged -and
        $partner12.independent_of_sequence_top_and_original_finding_seed_side -and
        $partner12.outside_interval_first_restorer_identity_remains_unattributed -and
        $partner12.exact_role_fractions_are_not_empirical_probabilities_or_chronology -and
        $partner12.no_new_evidence_read_reoptimization_git_network_or_business_write -and
        ($partner12.genuine_global_threshold_reporter_partner_endpoint_matrix[0].exact_original_reporter_partner_endpoint_matrix.original_reporter_partner_endpoint_profiles[0] |
            ConvertTo-Json -Depth 48 -Compress) -ceq
            ($partner12Reverse.genuine_global_threshold_reporter_partner_endpoint_matrix[0].exact_original_reporter_partner_endpoint_matrix.original_reporter_partner_endpoint_profiles[0] |
            ConvertTo-Json -Depth 48 -Compress) -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_reporter_partner_matrix') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_reporter_partner_matrix')) 'EC-091 altered original selector, seed/Top, caller identity or public projection-only boundary.'

    foreach ($view in @($cohortTwo, $pairedLeft, $fourAView, $fiveAView,
        $sixSixView, $allSameSevenView, $eightAView, $nineAView,
        $tenAView, $elevenAllAView, $tripleLeft)) {
        $actual = $view.data.path_focus.selected_original_finding_pair_profile_retention_reporter_partner_matrix
        $pairParent = $view.data.path_focus.selected_original_finding_pair_profile_retention_pair_reciprocity
        $roleParent = $view.data.path_focus.selected_original_finding_pair_profile_retention_reporter_role_exposure
        $n = [int]$actual.counts.original_selected_report_positions
        $fac = [long]1
        for ($j = 2; $j -le $n; $j++) { $fac *= [long]$j }
        Check ($actual.counts.original_reporter_partner_directed_cells_per_target -eq $n * ($n - 1) -and
            $actual.counts.exact_original_unordered_pair_count_per_target -eq $n * ($n - 1) / 2 -and
            $actual.counts.gap_cases_per_directed_reporter_partner_cell -eq $n - 1 -and
            $actual.counts.hypothetical_full_original_orderings_per_unordered_pair -eq $fac -and
            @($actual.genuine_global_threshold_reporter_partner_endpoint_matrix).Count -eq 3 -and
            @($actual.frozen_global_threshold_reporter_partner_endpoint_matrix).Count -eq 3 -and
            @($actual.individual_original_family_reporter_partner_endpoint_matrix).Count -eq
                @($pairParent.individual_original_family_pair_reciprocity).Count) 'EC-091 N2..12 original reporter-partner registry or target collection is incomplete.'
        $targets = [System.Collections.Generic.List[object]]::new()
        $pairTargets = [System.Collections.Generic.List[object]]::new()
        $roleTargets = [System.Collections.Generic.List[object]]::new()
        for ($t = 0; $t -lt 3; $t++) {
            Check ($actual.genuine_global_threshold_reporter_partner_endpoint_matrix[$t].original_global_family_capacity_at_least -eq 3 - $t -and
                $actual.frozen_global_threshold_reporter_partner_endpoint_matrix[$t].original_global_family_capacity_at_least -eq 3 - $t) 'EC-091 global genuine/frozen thresholds changed.'
            $targets.Add($actual.genuine_global_threshold_reporter_partner_endpoint_matrix[$t].exact_original_reporter_partner_endpoint_matrix)
            $pairTargets.Add($pairParent.genuine_global_threshold_pair_reciprocity[$t].exact_first_support_pair_reciprocity)
            $roleTargets.Add($roleParent.genuine_global_threshold_reporter_role_exposure[$t].exact_original_reporter_role_exposure)
            $targets.Add($actual.frozen_global_threshold_reporter_partner_endpoint_matrix[$t].exact_original_reporter_partner_endpoint_matrix)
            $pairTargets.Add($pairParent.frozen_global_threshold_pair_reciprocity[$t].exact_first_support_pair_reciprocity)
            $roleTargets.Add($roleParent.frozen_global_threshold_reporter_role_exposure[$t].exact_original_reporter_role_exposure)
        }
        for ($f = 0; $f -lt @($actual.individual_original_family_reporter_partner_endpoint_matrix).Count; $f++) {
            $x = $actual.individual_original_family_reporter_partner_endpoint_matrix[$f]
            Check ($x.original_maximal_repeat_family_index -eq $f + 1) 'EC-091 lost an original family identity.'
            $targets.Add($x.genuine_original_reporter_partner_endpoint_matrix)
            $pairTargets.Add($pairParent.individual_original_family_pair_reciprocity[$f].genuine_original_first_support_pair_reciprocity)
            $roleTargets.Add($roleParent.individual_original_family_reporter_role_exposure[$f].genuine_original_reporter_role_exposure)
            $targets.Add($x.frozen_original_reporter_partner_endpoint_matrix)
            $pairTargets.Add($pairParent.individual_original_family_pair_reciprocity[$f].frozen_original_first_support_pair_reciprocity)
            $roleTargets.Add($roleParent.individual_original_family_reporter_role_exposure[$f].frozen_original_reporter_role_exposure)
        }
        for ($t = 0; $t -lt $targets.Count; $t++) {
            $matrix = $targets[$t]
            $pairSource = $pairTargets[$t]
            $roleSource = $roleTargets[$t]
            Check ($matrix.original_positions_in_partner_universe -eq $n -and
                $matrix.exact_unordered_original_pair_count -eq $n * ($n - 1) / 2 -and
                $matrix.exact_directed_original_report_partner_count -eq $n * ($n - 1) -and
                $matrix.total_distinct_full_original_permutations -eq $fac -and
                $matrix.full_original_selection_has_saved_witness_support -eq
                    $pairSource.full_original_selection_has_saved_witness_support -and
                @($matrix.original_reporter_partner_endpoint_profiles).Count -eq $n -and
                $matrix.every_original_report_partner_is_both_direction_complete_and_symmetric -and
                $matrix.every_partner_gap_first_restorer_is_within_its_direction_denominator -and
                $matrix.every_reporter_partner_gap_and_all_gap_matches_ec090_role_exposure -and
                $matrix.all_partner_first_restorer_identity_totals_match_ec089_and_ec074_via_ec090 -and
                $matrix.outside_interval_and_intervening_first_restorer_are_not_assigned_to_endpoints -and
                $matrix.no_new_evidence_source_mask_enumeration_git_network_or_business_write) 'EC-091 target changed source support semantics or original identity/provenance.'
            $globalEarlier = [long]0
            $globalLater = [long]0
            for ($k = 0; $k -lt $n; $k++) {
                $reporter = $matrix.original_reporter_partner_endpoint_profiles[$k]
                $role = $roleSource.original_reporter_role_exposure_profiles[$k]
                $partnerEarlier = [long]0
                $partnerLater = [long]0
                Check ($reporter.original_reporter_caller_position -eq $k + 1 -and
                    $reporter.original_reporter_position_bit -eq (1 -shl $k) -and
                    $reporter.original_distinct_endpoint_partner_count -eq $n - 1 -and
                    @($reporter.partner_profiles_in_original_caller_order).Count -eq $n - 1) 'EC-091 reporter row omitted/reindexed an ORIGINAL endpoint partner.'
                $sSeen = 0
                foreach ($partner in $reporter.partner_profiles_in_original_caller_order) {
                    $s = [int]$partner.original_partner_caller_position - 1
                    Check ($s -ge 0 -and $s -lt $n -and $s -ne $k -and
                        $s -ge $sSeen -and $partner.original_partner_position_bit -eq (1 -shl $s) -and
                        @($partner.distance_cases).Count -eq $n - 1 -and
                        $partner.exact_full_original_orderings_per_reporter_endpoint_direction -eq $fac / 2) 'EC-091 partner row lost its original reporter/partner index or full directional denominator.'
                    $sSeen = $s + 1
                    $a = [Math]::Min($k, $s)
                    $b = [Math]::Max($k, $s)
                    $idx = [int]($a * (2 * $n - $a - 1) / 2 + $b - $a - 1)
                    $canonical = $pairSource.unordered_original_report_pair_reciprocities[$idx]
                    Check ($partner.original_unordered_pair_index_in_ec089 -eq $idx + 1 -and
                        $canonical.original_report_a_caller_position -eq $a + 1 -and
                        $canonical.original_report_b_caller_position -eq $b + 1) 'EC-091 pair mapping diverged from canonical EC-089 original identities.'
                    $sumEarly = [long]0
                    $sumLate = [long]0
                    for ($g = 0; $g -lt $n - 1; $g++) {
                        $gap = $partner.distance_cases[$g]
                        $source = $canonical.distance_cases[$g]
                        $d = [long]($n - $g - 1) * [long]($fac / ($n * ($n - 1)))
                        $lateExpected = if ($k -eq $a) {
                            [long]$source.first_restored_when_later_in_b_before_a_direction
                        } else {
                            [long]$source.first_restored_when_later_in_a_before_b_direction
                        }
                        $whole = if ($k -eq $a) { [long]$source.first_restored_by_original_report_a } else {
                            [long]$source.first_restored_by_original_report_b
                        }
                        $earlyExpected = $whole - $lateExpected
                        Check ($gap.number_of_original_reports_strictly_between_reporter_and_partner -eq $g -and
                            $gap.exact_full_original_orderings_with_reporter_earlier_than_partner -eq $d -and
                            $gap.exact_full_original_orderings_with_reporter_later_than_partner -eq $d -and
                            $gap.first_restored_by_reporter_as_earlier_endpoint -eq $earlyExpected -and
                            $gap.first_restored_by_reporter_as_later_endpoint -eq $lateExpected -and
                            $gap.first_restored_by_reporter_as_either_endpoint -eq $whole -and
                            $gap.exact_signed_later_minus_earlier_first_restorer_count -eq $lateExpected - $earlyExpected -and
                            $earlyExpected -ge 0 -and $lateExpected -ge 0 -and
                            $earlyExpected -le $d -and $lateExpected -le $d) 'EC-091 original report-specific endpoint direction attribution is wrong.'
                        foreach ($fractionCheck in @(@($gap.exact_reduced_first_restorer_fraction_given_reporter_earlier, $d, $earlyExpected),
                            @($gap.exact_reduced_first_restorer_fraction_given_reporter_later, $d, $lateExpected),
                            @($gap.exact_reduced_first_restorer_fraction_given_either_direction, (2 * $d), $whole),
                            @($gap.exact_reduced_signed_later_minus_earlier_fraction, $d, ($lateExpected - $earlyExpected)))) {
                            Check ([long]$fractionCheck[0].numerator * [long]$fractionCheck[1] -eq
                                [long]$fractionCheck[0].denominator * [long]$fractionCheck[2]) 'EC-091 exact signed or role-conditional pair fraction is inconsistent.'
                        }
                        if (-not $matrix.full_original_selection_has_saved_witness_support) {
                            Check ($whole -eq 0) 'EC-091 invented an ORIGINAL unsupported family FIRST restorer.'
                        }
                        $sumEarly += $earlyExpected
                        $sumLate += $lateExpected
                    }
                    Check ($sumEarly -eq $partner.first_restored_by_reporter_as_earlier_endpoint_across_all_gaps -and
                        $sumLate -eq $partner.first_restored_by_reporter_as_later_endpoint_across_all_gaps -and
                        $sumEarly + $sumLate -eq $partner.first_restored_by_reporter_as_either_endpoint_across_all_gaps -and
                        [long]$partner.exact_reduced_first_restorer_fraction_given_reporter_later.numerator * [long]($fac / 2) -eq
                            [long]$partner.exact_reduced_first_restorer_fraction_given_reporter_later.denominator * $sumLate) 'EC-091 whole-gap endpoint partner totals do not reconcile.'
                    $partnerEarlier += $sumEarly
                    $partnerLater += $sumLate
                }
                Check ($partnerEarlier -eq $role.first_restored_as_earlier_endpoint_across_all_gaps -and
                    $partnerLater -eq $role.first_restored_as_later_endpoint_across_all_gaps -and
                    $partnerEarlier -eq $reporter.first_restored_as_earlier_endpoint_across_partners -and
                    $partnerLater -eq $reporter.first_restored_as_later_endpoint_across_partners -and
                    $reporter.exact_full_ordering_exposure_as_earlier_endpoint_across_partners -eq
                        $role.full_original_ordering_role_exposure_as_earlier_endpoint -and
                    $reporter.exact_full_ordering_exposure_as_later_endpoint_across_partners -eq
                        $role.full_original_ordering_role_exposure_as_later_endpoint) 'EC-091 all-partner original role totals differ from EC-090 independent original reporter FIRST ledger.'
