                exact_reduced_reporter_share_of_all_original_endpoint_first_credit = `
                    (Get-CodeSequenceEndpointCreditConditionalShare -Credited $credits[$i] -EndpointFirst $total)
            })
        }
        return [ordered]@{
            original_positions_in_credit_graph = $n
            exact_unordered_original_pair_edge_count = $pairCount
            total_distinct_full_original_permutations = $full
            exact_total_original_pair_ordering_incidences = [long]$pairCount * $full
            full_original_selection_has_saved_witness_support = ($Case -cne 'zero')
            original_unordered_endpoint_credit_edges = $edges.ToArray()
            original_reporter_endpoint_credit_nodes = $nodes.ToArray()
            total_first_restored_by_any_original_pair_endpoint = $total
            total_neither_endpoint_first_ordering_incidences = [long]$pairCount * $full - $total
            every_original_pair_direction_and_gap_is_exhaustive_and_disjoint = $true
            every_reporter_first_credit_matches_ec089_and_ec091_original_identity = $true
            endpoint_first_only_conditional_shares_are_null_when_ineligible = $true
            all_first_restoration_mass_matches_independent_ec074_ec076_ec089 = $true
            nonendpoint_or_never_restoration_is_never_attributed_to_a_or_b = $true
            no_new_evidence_read_mask_enumeration_git_network_or_business_write = $true
        }
    }
    $cycle = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case cycle) -N 3
    Check ($cycle.exact_direct_strict_advantage_count -eq 3 -and
        $cycle.exact_strongly_connected_component_count -eq 1 -and
        $cycle.exact_nontrivial_strict_cycle_component_count -eq 1 -and
        @($cycle.original_strict_dominance_components[0].original_member_caller_positions).Count -eq 3 -and
        $cycle.exact_condensed_direct_component_arc_count -eq 0 -and
        $cycle.exact_maximum_longest_predecessor_layer -eq 0) 'EC-093 failed to collapse a directed strict 3-cycle.'
    foreach ($p in $cycle.original_reporter_strict_dominance_profiles) {
        Check ($p.exact_distinct_other_reporters_reachable_by_strict_paths -eq 2 -and
            $p.strict_component_index -eq 1) 'EC-093 lost path closure inside a strict 3-cycle.'
    }
    $tie = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case nontransitive_equal) -N 3
    Check ($tie.exact_direct_strict_advantage_count -eq 2 -and
        $tie.exact_direct_equal_credit_pair_count -eq 1 -and
        $tie.exact_equal_credit_pairs_with_no_endpoint_first -eq 0 -and
        $tie.exact_strongly_connected_component_count -eq 3 -and
        $tie.exact_condensed_direct_component_arc_count -eq 2 -and
        $tie.exact_maximum_longest_predecessor_layer -eq 2 -and
        $tie.original_reporter_strict_dominance_profiles[0].exact_distinct_other_reporters_reachable_by_strict_paths -eq 2 -and
        $tie.original_reporter_strict_dominance_profiles[2].exact_distinct_other_reporters_reachable_by_strict_paths -eq 0) 'EC-093 treated a nontransitive equal pair as a directed strict arc.'
    $zero = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case zero) -N 3
    Check ($zero.exact_direct_strict_advantage_count -eq 0 -and
        $zero.exact_direct_equal_credit_pair_count -eq 3 -and
        $zero.exact_equal_credit_pairs_with_no_endpoint_first -eq 3 -and
        $zero.exact_strongly_connected_component_count -eq 3 -and
        $zero.exact_strict_dominance_source_component_count -eq 3) 'EC-093 fabricated endpoint FIRST support or paths for an all-zero ORIGINAL graph.'
    $bad = (New-EC093SyntheticCreditGraph -Case cycle)
    $bad.original_unordered_endpoint_credit_edges[0].original_a_vs_b_endpoint_credit_relation = 'equal'
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph $bad -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-093 accepted a tampered strict pair relation.'
    $bad = (New-EC093SyntheticCreditGraph -Case cycle)
    $bad.original_reporter_endpoint_credit_nodes[0].original_pairs_with_more_endpoint_first_credit_than_partner = 2
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph $bad -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-093 accepted a corrupt original reporter wins ledger.'
    $bad = (New-EC093SyntheticCreditGraph -Case zero)
    $bad.original_unordered_endpoint_credit_edges[0].exact_reduced_a_share_given_either_endpoint_first = @{ numerator = 0; denominator = 1 }
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph $bad -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-093 accepted a fake 0/1 endpoint-FIRST conditional share.'
    Write-Output "EC-093 CodeSequence smoke checks completed: $script:checks"

    # EC-094: the SCC condensation (not the possibly cyclic reporter graph)
    # has a unique transitive reduction. Every discarded direct link must
    # have an actual shortest alternate path made only from retained links,
    # with a genuine ORIGINAL EC-089 unordered pair index for each hop.
    . (Join-Path (Split-Path -Parent $PSScriptRoot) 'scripts/codeprofileretentionendpointreduction.ps1')
    $reduction12 = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_dominance_reduction
    $reduction12Reverse = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_dominance_reduction
    Check ($reduction12.scope -ceq 'exact_original_strict_condensation_transitive_reduction_with_pair_witnesses' -and
        $reduction12.counts.original_selected_report_positions -eq 12 -and
        $reduction12.counts.original_unordered_pair_comparisons_per_target -eq 66 -and
        $reduction12.only_consumed_checked_ec093_public_original_strict_topology -and
        $reduction12.original_ec071_caller_bits_and_family_targets_unchanged -and
        $reduction12.independent_of_sequence_top_and_original_finding_seed_side -and
        $reduction12.component_route_witnesses_are_not_credit_addition_real_time_or_repair_priority -and
        $reduction12.no_new_evidence_read_reoptimization_git_network_or_business_write -and
        ($reduction12.genuine_global_threshold_endpoint_dominance_reduction[0].exact_original_strict_condensation_transitive_reduction |
            ConvertTo-Json -Depth 32 -Compress) -ceq
            ($reduction12Reverse.genuine_global_threshold_endpoint_dominance_reduction[0].exact_original_strict_condensation_transitive_reduction |
            ConvertTo-Json -Depth 32 -Compress) -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_endpoint_dominance_reduction') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_endpoint_dominance_reduction')) 'EC-094 changed ORIGINAL fifth-level selector/seed/Top stability or added output to unsuccessful selection.'

    foreach ($view in @($cohortTwo, $pairedLeft, $fourAView, $fiveAView,
        $sixSixView, $allSameSevenView, $eightAView, $nineAView,
        $tenAView, $elevenAllAView, $tripleLeft)) {
        $top = $view.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_dominance_topology
        $reduction = $view.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_dominance_reduction
        $n = [int]$top.counts.original_selected_report_positions
        $pairCount = [int]($n * ($n - 1) / 2)
        Check ($reduction.counts.original_selected_report_positions -eq $n -and
            $reduction.counts.original_maximal_repeat_family_count -eq $top.counts.original_maximal_repeat_family_count -and
            $reduction.counts.original_unordered_pair_comparisons_per_target -eq $pairCount -and
            @($reduction.genuine_global_threshold_endpoint_dominance_reduction).Count -eq 3 -and
            @($reduction.frozen_global_threshold_endpoint_dominance_reduction).Count -eq 3 -and
            @($reduction.individual_original_family_endpoint_dominance_reduction).Count -eq
                @($top.individual_original_family_endpoint_dominance_topology).Count) 'EC-094 ORIGINAL N2..12 parent/child target dimensions changed.'
        $cases = [System.Collections.Generic.List[object]]::new()
        for ($i = 0; $i -lt 3; $i++) {
            Check ($reduction.genuine_global_threshold_endpoint_dominance_reduction[$i].original_global_family_capacity_at_least -eq 3 - $i -and
                $reduction.frozen_global_threshold_endpoint_dominance_reduction[$i].original_global_family_capacity_at_least -eq 3 - $i) 'EC-094 reordered ORIGINAL global targets.'
            $cases.Add(@{
                parent = $top.genuine_global_threshold_endpoint_dominance_topology[$i].exact_original_endpoint_first_credit_strict_dominance_topology
                reduced = $reduction.genuine_global_threshold_endpoint_dominance_reduction[$i].exact_original_strict_condensation_transitive_reduction
            })
            $cases.Add(@{
                parent = $top.frozen_global_threshold_endpoint_dominance_topology[$i].exact_original_endpoint_first_credit_strict_dominance_topology
                reduced = $reduction.frozen_global_threshold_endpoint_dominance_reduction[$i].exact_original_strict_condensation_transitive_reduction
            })
        }
        for ($i = 0; $i -lt @($top.individual_original_family_endpoint_dominance_topology).Count; $i++) {
            $p = $top.individual_original_family_endpoint_dominance_topology[$i]
            $r = $reduction.individual_original_family_endpoint_dominance_reduction[$i]
            Check ($r.original_maximal_repeat_family_index -eq $i + 1 -and
                $p.original_maximal_repeat_family_index -eq $i + 1) 'EC-094 reindexed an original repeat family.'
            $cases.Add(@{ parent = $p.genuine_original_endpoint_first_credit_strict_dominance_topology;
                reduced = $r.genuine_original_strict_condensation_transitive_reduction })
            $cases.Add(@{ parent = $p.frozen_original_endpoint_first_credit_strict_dominance_topology;
                reduced = $r.frozen_original_strict_condensation_transitive_reduction })
        }
        foreach ($case in $cases) {
            $parent = $case.parent
            $r = $case.reduced
            $links = @($r.original_condensed_component_link_reduction)
            $components = @($r.original_component_reachability_after_reduction)
            $parentLinks = @($parent.original_condensed_strict_dominance_component_arcs)
            Check ($r.original_positions_in_reduction_universe -eq $n -and
                $r.exact_unordered_original_pair_count -eq $pairCount -and
                $r.total_distinct_full_original_permutations -eq $parent.total_distinct_full_original_permutations -and
                $r.full_original_selection_has_saved_witness_support -eq $parent.full_original_selection_has_saved_witness_support -and
                $r.exact_original_strict_direct_comparison_count -eq $parent.exact_direct_strict_advantage_count -and
                $r.exact_original_equal_credit_pair_count -eq $parent.exact_direct_equal_credit_pair_count -and
                $r.exact_original_equal_pairs_without_endpoint_first -eq $parent.exact_equal_credit_pairs_with_no_endpoint_first -and
                $r.exact_strongly_connected_component_count -eq @($parent.original_strict_dominance_components).Count -and
                $r.exact_original_condensed_direct_component_link_count -eq $parentLinks.Count -and
                $r.exact_original_condensed_direct_component_link_count -eq $links.Count -and
                $r.exact_indispensable_condensed_direct_component_link_count +
                    $r.exact_redundant_condensed_direct_component_link_count -eq $links.Count -and
                $r.exact_indispensable_link_underlying_direct_comparison_count +
                    $r.exact_redundant_link_underlying_direct_comparison_count -eq
                    $r.exact_original_cross_component_strict_comparison_count -and
                $r.exact_indispensable_link_direct_credit_advantage +
                    $r.exact_redundant_link_direct_credit_advantage -eq $r.exact_total_cross_component_direct_credit_advantage -and
                $r.exact_source_component_count -eq $parent.exact_strict_dominance_source_component_count -and
                $r.every_original_strict_component_path_is_preserved -and
                $r.each_discarded_direct_link_has_shortest_deterministic_alternative_with_original_pair_witnesses -and
                $r.no_equal_pair_or_no_first_credit_is_used_as_a_strict_route -and
                $r.original_direct_credit_advantages_are_not_summed_along_alternative_paths -and
                $r.no_new_evidence_read_permutation_mask_git_network_or_business_write) 'EC-094 lost ORIGINAL parent SCC/credit/condensed-link mass.'
            $kept = @{}
            for ($i = 0; $i -lt $links.Count; $i++) {
                $link = $links[$i]
                $p = $parentLinks[$i]
                $key = "$($link.dominant_component_index)/$($link.subordinate_component_index)"
                Check ($link.dominant_component_index -eq $p.dominant_component_index -and
                    $link.subordinate_component_index -eq $p.subordinate_component_index -and
                    $link.original_direct_strict_comparison_count -eq $p.original_direct_strict_comparison_count -and
                    $link.exact_sum_of_direct_strict_first_credit_advantages -eq $p.exact_sum_of_strict_first_credit_advantages -and
                    (@($link.original_ec089_unordered_pair_indices) -join ',') -ceq
                    (@($p.original_ec089_unordered_pair_indices) -join ',')) 'EC-094 modified the original direct SCC comparison margin or pair identity.'
                if ($link.indispensable_for_original_strict_component_reachability) {
                    Check ($null -eq $link.shortest_lexicographic_alternative_component_route) 'EC-094 invented an alternate route for an indispensable edge.'
                    $kept[$key] = $link
                }
            }
            $discarded = 0
            foreach ($link in $links) {
                if ($link.indispensable_for_original_strict_component_reachability) { continue }
                $discarded++
                $route = $link.shortest_lexicographic_alternative_component_route
                $path = @($route.original_component_indices)
                $pairs = @($route.original_ec089_pair_index_witness_per_hop)
                Check ($null -ne $route -and $path.Count -ge 3 -and
                    $path[0] -eq $link.dominant_component_index -and
                    $path[-1] -eq $link.subordinate_component_index -and
                    $pairs.Count -eq $path.Count - 1 -and
                    $route.exact_alternative_component_hop_count -eq $pairs.Count) 'EC-094 failed to witness a redundant ORIGINAL SCC link.'
                for ($j = 0; $j -lt $pairs.Count; $j++) {
                    $key = "$($path[$j])/$($path[$j + 1])"
                    Check ($kept.ContainsKey($key) -and
                        $pairs[$j] -in @($kept[$key].original_ec089_unordered_pair_indices)) 'EC-094 route used a removed/nonexistent pair rather than a retained SCC link.'
                }
            }
            Check ($discarded -eq $r.exact_redundant_condensed_direct_component_link_count) 'EC-094 redundant edge ledger is inconsistent.'
            for ($i = 0; $i -lt $components.Count; $i++) {
                $c = $components[$i]
                $p = $parent.original_strict_dominance_components[$i]
                Check ($c.strict_component_index -eq $i + 1 -and
                    (@($c.original_member_caller_positions) -join ',') -ceq (@($p.original_member_caller_positions) -join ',') -and
                    (@($c.original_member_position_bits) -join ',') -ceq (@($p.original_member_position_bits) -join ',') -and
                    $c.longest_strict_dominance_predecessor_layer -eq $p.longest_strict_dominance_predecessor_layer -and
                    $c.exact_reachable_other_component_count -eq @($c.reachable_other_component_indices).Count -and
                    $c.exact_ancestor_other_component_count -eq @($c.ancestor_other_component_indices).Count -and
                    $c.source_component -eq ($p.incoming_direct_component_count -eq 0) -and
                    $c.sink_component -eq ($p.outgoing_direct_component_count -eq 0)) 'EC-094 returned an inconsistent original SCC reachability summary.'
            }
            if (-not $parent.full_original_selection_has_saved_witness_support) {
                Check ($r.exact_original_condensed_direct_component_link_count -eq 0 -and
                    $r.exact_indispensable_condensed_direct_component_link_count -eq 0 -and
                    $r.exact_source_component_count -eq $n -and $r.exact_sink_component_count -eq $n -and
                    $r.exact_original_equal_pairs_without_endpoint_first -eq $pairCount) 'EC-094 invented reachability for unsupported originals.'
            }
        }
    }
    foreach ($target in @($reduction12.genuine_global_threshold_endpoint_dominance_reduction[0],
        $reduction12.frozen_global_threshold_endpoint_dominance_reduction[0])) {
        $r = $target.exact_original_strict_condensation_transitive_reduction
        Check ($r.full_original_selection_has_saved_witness_support -and
            $r.exact_original_strict_direct_comparison_count -eq 0 -and
            $r.exact_original_equal_credit_pair_count -eq 66 -and
            $r.exact_original_equal_pairs_without_endpoint_first -eq 0 -and
            $r.exact_strongly_connected_component_count -eq 12 -and
            $r.exact_source_component_count -eq 12 -and $r.exact_sink_component_count -eq 12 -and
            $r.exact_indispensable_condensed_direct_component_link_count -eq 0 -and
            $r.exact_redundant_condensed_direct_component_link_count -eq 0) 'EC-094 misinterpreted N12 positive-FIRST equal pairs as reducible strict arcs.'
    }

    $cycleReduced = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $cycle -N 3
    Check ($cycleReduced.exact_strongly_connected_component_count -eq 1 -and
        $cycleReduced.exact_original_strict_direct_comparison_count -eq 3 -and
        $cycleReduced.exact_indispensable_condensed_direct_component_link_count -eq 0 -and
        $cycleReduced.exact_source_component_count -eq 1 -and $cycleReduced.exact_sink_component_count -eq 1) 'EC-094 incorrectly tried to transitively reduce a cyclic reporter graph.'
    $tieReduced = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $tie -N 3
    Check ($tieReduced.exact_indispensable_condensed_direct_component_link_count -eq 2 -and
        $tieReduced.exact_redundant_condensed_direct_component_link_count -eq 0 -and
        $tieReduced.exact_strongly_connected_component_count -eq 3 -and
        $tieReduced.original_component_reachability_after_reduction[0].exact_reachable_other_component_count -eq 2) 'EC-094 confused nontransitive equal credit with a direct SCC link.'
    $zeroReduced = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $zero -N 3
    Check ($zeroReduced.exact_original_equal_pairs_without_endpoint_first -eq 3 -and
        $zeroReduced.exact_indispensable_condensed_direct_component_link_count -eq 0 -and
        $zeroReduced.exact_redundant_condensed_direct_component_link_count -eq 0 -and
        $zeroReduced.exact_source_component_count -eq 3 -and $zeroReduced.exact_sink_component_count -eq 3) 'EC-094 invented strict routes for all-zero originals.'
    $triangle = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case transitive_triangle) -N 3
    $triangleReduced = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $triangle -N 3
    $triangleShortcut = @($triangleReduced.original_condensed_component_link_reduction |
        Where-Object { $_.dominant_component_index -eq 1 -and $_.subordinate_component_index -eq 3 })[0]
    Check ($triangleReduced.exact_indispensable_condensed_direct_component_link_count -eq 2 -and
        $triangleReduced.exact_redundant_condensed_direct_component_link_count -eq 1 -and
        -not $triangleShortcut.indispensable_for_original_strict_component_reachability -and
        (@($triangleShortcut.shortest_lexicographic_alternative_component_route.original_component_indices) -join ',') -ceq '1,2,3' -and
        (@($triangleShortcut.shortest_lexicographic_alternative_component_route.original_ec089_pair_index_witness_per_hop) -join ',') -ceq '1,3') 'EC-094 failed to remove the N3 shortcut with two authentic retained hop witnesses.'
    $diamond = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case diamond) -N 4
    $diamondReduced = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $diamond -N 4
    $diamondShortcut = @($diamondReduced.original_condensed_component_link_reduction |
        Where-Object { $_.dominant_component_index -eq 1 -and $_.subordinate_component_index -eq 4 })[0]
    Check ($diamondReduced.exact_original_condensed_direct_component_link_count -eq 5 -and
        $diamondReduced.exact_indispensable_condensed_direct_component_link_count -eq 4 -and
        $diamondReduced.exact_redundant_condensed_direct_component_link_count -eq 1 -and
        $diamondReduced.exact_source_component_count -eq 1 -and $diamondReduced.exact_sink_component_count -eq 1 -and
        (@($diamondShortcut.shortest_lexicographic_alternative_component_route.original_component_indices) -join ',') -ceq '1,2,4' -and
        (@($diamondShortcut.shortest_lexicographic_alternative_component_route.original_ec089_pair_index_witness_per_hop) -join ',') -ceq '1,5' -and
        $diamondReduced.original_component_reachability_after_reduction[0].exact_reachable_other_component_count -eq 3) 'EC-094 did not pick the earliest shortest retained route through a N4 diamond.'
    $order4 = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case total_order_four) -N 4
    $order4Reduced = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $order4 -N 4
    $order4Shortcut = @($order4Reduced.original_condensed_component_link_reduction |
        Where-Object { $_.dominant_component_index -eq 1 -and $_.subordinate_component_index -eq 4 })[0]
    Check ($order4Reduced.exact_original_condensed_direct_component_link_count -eq 6 -and
        $order4Reduced.exact_indispensable_condensed_direct_component_link_count -eq 3 -and
        $order4Reduced.exact_redundant_condensed_direct_component_link_count -eq 3 -and
        (@($order4Shortcut.shortest_lexicographic_alternative_component_route.original_component_indices) -join ',') -ceq '1,2,3,4' -and
        (@($order4Shortcut.shortest_lexicographic_alternative_component_route.original_ec089_pair_index_witness_per_hop) -join ',') -ceq '1,4,6') 'EC-094 shortest witness incorrectly used a discarded shortcut rather than only retained N4 links.'
    $bridge4 = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case cycle_with_bridge) -N 4
    $bridge4Reduced = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $bridge4 -N 4
    $bridgeLink = @($bridge4Reduced.original_condensed_component_link_reduction)[0]
    Check ($bridge4Reduced.exact_strongly_connected_component_count -eq 2 -and
        $bridge4Reduced.exact_original_strict_direct_comparison_count -eq 6 -and
        $bridge4Reduced.exact_original_cross_component_strict_comparison_count -eq 3 -and
        $bridge4Reduced.exact_indispensable_condensed_direct_component_link_count -eq 1 -and
        $bridge4Reduced.exact_redundant_condensed_direct_component_link_count -eq 0 -and
        $bridgeLink.original_direct_strict_comparison_count -eq 3 -and
        $bridgeLink.exact_sum_of_direct_strict_first_credit_advantages -eq 6 -and
        (@($bridgeLink.original_ec089_unordered_pair_indices) -join ',') -ceq '3,5,6' -and
        $bridgeLink.indispensable_for_original_strict_component_reachability -and
        $null -eq $bridgeLink.shortest_lexicographic_alternative_component_route) 'EC-094 lost true multiplicity/direct FIRST margins on a multi-arc SCC bridge.'
    $bad = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case transitive_triangle) -N 3
    $bad.original_condensed_strict_dominance_component_arcs[0].exact_sum_of_strict_first_credit_advantages++
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $bad -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-094 accepted a corrupted parent direct credit-advantage margin.'
    $bad = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case transitive_triangle) -N 3
    $bad.original_reporter_strict_dominance_profiles[0].original_positions_reachable_by_one_or_more_strict_comparison_arcs = @(2)
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $bad -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-094 accepted a forged original reporter strict-reachability ledger.'
    $bad = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case diamond) -N 4
    $bad.original_strict_dominance_components[0].original_member_caller_positions = @(1, 2)
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $bad -N 4 } catch { $rejected = $true }
    Check $rejected 'EC-094 accepted an invented SCC grouping.'
    $bad = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case nontransitive_equal) -N 3
    $bad.original_direct_equal_credit_pairs[0].neither_endpoint_received_first_credit = $true
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $bad -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-094 accepted a false positive-FIRST equal-as-0/0 label.'
    Write-Output "EC-094 CodeSequence smoke checks completed: $script:checks"

    # EC-095: counterfactual removal of ONE whole ORIGINAL condensed link.
    # Simulate deletion in the FULL graph (redundant direct shortcuts survive)
    # and separately in the unique REDUCED DAG (no shortcuts survive).
    # Each lost ordered component pair has exact ORIGINAL reporter-pair mass.
    . (Join-Path (Split-Path -Parent $PSScriptRoot) 'scripts/codeprofileretentionendpointlinkimpact.ps1')
    $impact12 = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_link_impact
    $impact12Reverse = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_link_impact
    Check ($impact12.scope -ceq 'exact_one_original_scc_link_at_a_time_full_vs_reduced_strict_path_loss' -and
        $impact12.counts.original_selected_report_positions -eq 12 -and
        $impact12.counts.original_unordered_pair_comparisons_per_target -eq 66 -and
        $impact12.only_consumed_checked_ec093_and_ec094_original_graph_projections -and
        $impact12.original_ec071_caller_bits_and_family_targets_unchanged -and
        $impact12.independent_of_sequence_top_and_original_finding_seed_side -and
        $impact12.single_link_deletion_cannot_attest_actual_faults_or_repair_priority -and
        $impact12.no_new_evidence_read_reoptimization_git_network_or_business_write -and
        ($impact12.genuine_global_threshold_endpoint_link_impact[0].exact_single_original_scc_link_removal_reachability_impact |
            ConvertTo-Json -Depth 30 -Compress) -ceq
            ($impact12Reverse.genuine_global_threshold_endpoint_link_impact[0].exact_single_original_scc_link_removal_reachability_impact |
                ConvertTo-Json -Depth 30 -Compress) -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_endpoint_link_impact') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_endpoint_link_impact')) 'EC-095 changed ORIGINAL selector, seed, SequenceTop or added an unsuccessful output.'

    foreach ($view in @($cohortTwo, $pairedLeft, $fourAView, $fiveAView,
        $sixSixView, $allSameSevenView, $eightAView, $nineAView,
        $tenAView, $elevenAllAView, $tripleLeft)) {
        $impact = $view.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_link_impact
        $reduction = $view.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_dominance_reduction
        $n = [int]$impact.counts.original_selected_report_positions
        Check ($n -ge 2 -and $n -le 12 -and
            $impact.counts.original_maximal_repeat_family_count -eq $reduction.counts.original_maximal_repeat_family_count -and
            $impact.counts.original_unordered_pair_comparisons_per_target -eq ($n * ($n - 1) / 2) -and
            @($impact.genuine_global_threshold_endpoint_link_impact).Count -eq 3 -and
            @($impact.frozen_global_threshold_endpoint_link_impact).Count -eq 3 -and
            @($impact.individual_original_family_endpoint_link_impact).Count -eq
                @($reduction.individual_original_family_endpoint_dominance_reduction).Count) 'EC-095 lost an actual ORIGINAL N2..12 threshold or repeat family.'
        $allCases = [System.Collections.Generic.List[object]]::new()
        for ($i = 0; $i -lt 3; $i++) {
            Check ($impact.genuine_global_threshold_endpoint_link_impact[$i].original_global_family_capacity_at_least -eq 3 - $i -and
                $impact.frozen_global_threshold_endpoint_link_impact[$i].original_global_family_capacity_at_least -eq 3 - $i) 'EC-095 changed genuine/frozen threshold ordering.'
            $allCases.Add(@{
                impact = $impact.genuine_global_threshold_endpoint_link_impact[$i].exact_single_original_scc_link_removal_reachability_impact
                reduction = $reduction.genuine_global_threshold_endpoint_dominance_reduction[$i].exact_original_strict_condensation_transitive_reduction
            })
            $allCases.Add(@{
                impact = $impact.frozen_global_threshold_endpoint_link_impact[$i].exact_single_original_scc_link_removal_reachability_impact
                reduction = $reduction.frozen_global_threshold_endpoint_dominance_reduction[$i].exact_original_strict_condensation_transitive_reduction
            })
        }
        for ($i = 0; $i -lt @($impact.individual_original_family_endpoint_link_impact).Count; $i++) {
            $f = $impact.individual_original_family_endpoint_link_impact[$i]
            $r = $reduction.individual_original_family_endpoint_dominance_reduction[$i]
            Check ($f.original_maximal_repeat_family_index -eq $i + 1 -and
                $r.original_maximal_repeat_family_index -eq $i + 1) 'EC-095 invented or reordered a repeat family.'
            $allCases.Add(@{ impact = $f.genuine_exact_single_original_scc_link_removal_reachability_impact;
                reduction = $r.genuine_original_strict_condensation_transitive_reduction })
            $allCases.Add(@{ impact = $f.frozen_exact_single_original_scc_link_removal_reachability_impact;
                reduction = $r.frozen_original_strict_condensation_transitive_reduction })
        }
        foreach ($case in $allCases) {
            $r = $case.reduction
            $w = $case.impact
            $links = @($w.original_direct_component_link_single_deletion_impacts)
            $originalLinks = @($r.original_condensed_component_link_reduction)
            $fullLossSum = 0; $fullReporterSum = 0; $extraSum = 0; $extraReporterSum = 0
            Check ($w.original_positions_in_impact_universe -eq $n -and
                $w.exact_strongly_connected_component_count -eq $r.exact_strongly_connected_component_count -and
                $w.exact_original_direct_condensed_component_link_count -eq $originalLinks.Count -and
                $w.exact_indispensable_component_link_count -eq $r.exact_indispensable_condensed_direct_component_link_count -and
                $w.exact_redundant_component_link_count_with_zero_full_removal_loss -eq
                    $r.exact_redundant_condensed_direct_component_link_count -and
                $links.Count -eq $originalLinks.Count -and
                $w.each_scenario_removes_one_entire_original_scc_link_only -and
                $w.reduced_graph_only_extra_losses_are_not_losses_in_the_full_original_graph -and
                $w.no_equal_pair_or_zero_credit_pair_is_a_strict_removal_target -and
                $w.impact_is_not_chronology_probability_severity_causality_or_repair_priority -and
                $w.no_new_evidence_read_permutation_mask_git_network_or_business_write) 'EC-095 failed original reduction/impact shape and semantic boundaries.'
            for ($k = 0; $k -lt $links.Count; $k++) {
                $link = $links[$k]
                $original = $originalLinks[$k]
                $loss = $link.if_entire_original_direct_component_link_removed_from_full_dag
                Check ($link.dominant_component_index -eq $original.dominant_component_index -and
                    $link.subordinate_component_index -eq $original.subordinate_component_index -and
                    $link.original_direct_strict_comparison_count -eq $original.original_direct_strict_comparison_count -and
                    $link.exact_sum_of_direct_strict_first_credit_advantages -eq
                        $original.exact_sum_of_direct_strict_first_credit_advantages -and
                    (@($link.original_ec089_unordered_pair_indices) -join ',') -ceq
                        (@($original.original_ec089_unordered_pair_indices) -join ',') -and
                    $link.indispensable_for_original_strict_component_reachability -eq
                        $original.indispensable_for_original_strict_component_reachability -and
                    @($loss.lost_reachable_component_pairs_in_canonical_order).Count -eq
                        $loss.exact_lost_reachable_component_pair_count) 'EC-095 lost original direct SCC-link identity, pair index or positive margin.'
                $mass = 0; $previousKey = 0
                foreach ($lostPair in @($loss.lost_reachable_component_pairs_in_canonical_order)) {
                    $a = [int]$lostPair.from_strict_component_index
                    $b = [int]$lostPair.to_strict_component_index
                    $key = ($a - 1) * 13 + $b
                    $mass += [int]$lostPair.exact_ordered_original_reporter_pair_multiplicity
                    Check ($key -gt $previousKey -and $a -ne $b -and
                        $lostPair.exact_ordered_original_reporter_pair_multiplicity -eq
                            @($r.original_component_reachability_after_reduction[$a - 1].original_member_caller_positions).Count *
                            @($r.original_component_reachability_after_reduction[$b - 1].original_member_caller_positions).Count) 'EC-095 lost canonical lost-pair ordering or correct ORIGINAL SCC reporter multiplicity.'
                    $previousKey = $key
                }
                Check ($mass -eq $loss.exact_lost_reachable_original_reporter_pair_count) 'EC-095 lost FULL graph affected-reporter pair mass.'
                $fullLossSum += [int]$loss.exact_lost_reachable_component_pair_count
                $fullReporterSum += $mass
                if ($link.indispensable_for_original_strict_component_reachability) {
                    $rLoss = $link.if_same_indispensable_link_removed_from_reduced_dag
                    $extra = $link.extra_loss_only_because_redundant_shortcuts_are_absent_in_reduced_dag
                    Check ($null -ne $rLoss -and $null -ne $extra -and
                        $loss.exact_lost_reachable_component_pair_count -ge 1 -and
                        $rLoss.exact_lost_reachable_component_pair_count -eq
                            $loss.exact_lost_reachable_component_pair_count + $extra.exact_lost_reachable_component_pair_count -and
                        $rLoss.exact_lost_reachable_original_reporter_pair_count -eq
                            $loss.exact_lost_reachable_original_reporter_pair_count + $extra.exact_lost_reachable_original_reporter_pair_count) 'EC-095 conflated FULL deletion loss with REDUCED-only extra loss.'
                    $extraSum += [int]$extra.exact_lost_reachable_component_pair_count
                    $extraReporterSum += [int]$extra.exact_lost_reachable_original_reporter_pair_count
                } else {
                    Check ($null -eq $link.if_same_indispensable_link_removed_from_reduced_dag -and
                        $null -eq $link.extra_loss_only_because_redundant_shortcuts_are_absent_in_reduced_dag -and
                        $loss.exact_lost_reachable_component_pair_count -eq 0 -and
                        $mass -eq 0) 'EC-095 invented a lost path or reduced-link experiment for a redundant original link.'
                }
            }
            Check ($fullLossSum -eq $w.sum_of_component_pair_loss_incidences_across_separate_full_link_deletions -and
                $fullReporterSum -eq $w.sum_of_original_reporter_pair_loss_incidences_across_separate_full_link_deletions -and
                $extraSum -eq $w.sum_of_extra_component_pair_loss_incidences_across_separate_reduced_link_deletions -and
                $extraReporterSum -eq $w.sum_of_extra_reporter_pair_loss_incidences_across_separate_reduced_link_deletions) 'EC-095 separate counterfactual loss totals did not reconcile.'
            if (-not $r.full_original_selection_has_saved_witness_support) {
                Check ($r.exact_original_equal_pairs_without_endpoint_first -eq ($n * ($n - 1) / 2) -and
                    $w.exact_original_direct_condensed_component_link_count -eq 0 -and
                    $w.exact_baseline_reachable_nonreflexive_component_pair_count -eq 0 -and
                    $w.sum_of_component_pair_loss_incidences_across_separate_full_link_deletions -eq 0 -and
                    $w.sum_of_extra_component_pair_loss_incidences_across_separate_reduced_link_deletions -eq 0) 'EC-095 invented original strict reachability/deletion impact for an unsupported 0/0 target.'
            }
        }
    }

    $triangleImpact = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $triangle -DominanceReduction $triangleReduced -N 3
    $t12 = @($triangleImpact.original_direct_component_link_single_deletion_impacts |
        Where-Object { $_.dominant_component_index -eq 1 -and $_.subordinate_component_index -eq 2 })[0]
    $t23 = @($triangleImpact.original_direct_component_link_single_deletion_impacts |
        Where-Object { $_.dominant_component_index -eq 2 -and $_.subordinate_component_index -eq 3 })[0]
    $t13 = @($triangleImpact.original_direct_component_link_single_deletion_impacts |
        Where-Object { $_.dominant_component_index -eq 1 -and $_.subordinate_component_index -eq 3 })[0]
    Check ($triangleImpact.exact_baseline_reachable_nonreflexive_component_pair_count -eq 3 -and
        $triangleImpact.exact_indispensable_component_link_count -eq 2 -and
        $triangleImpact.exact_redundant_component_link_count_with_zero_full_removal_loss -eq 1 -and
        $t13.if_entire_original_direct_component_link_removed_from_full_dag.exact_lost_reachable_component_pair_count -eq 0 -and
        $null -eq $t13.if_same_indispensable_link_removed_from_reduced_dag -and
        $t12.if_entire_original_direct_component_link_removed_from_full_dag.exact_lost_reachable_component_pair_count -eq 1 -and
        $t12.if_same_indispensable_link_removed_from_reduced_dag.exact_lost_reachable_component_pair_count -eq 2 -and
        (@($t12.extra_loss_only_because_redundant_shortcuts_are_absent_in_reduced_dag.lost_reachable_component_pairs_in_canonical_order |
            ForEach-Object { "$($_.from_strict_component_index)>$($_.to_strict_component_index)" }) -join ',') -ceq '1>3' -and
        $t23.if_entire_original_direct_component_link_removed_from_full_dag.exact_lost_reachable_component_pair_count -eq 1 -and
        $t23.if_same_indispensable_link_removed_from_reduced_dag.exact_lost_reachable_component_pair_count -eq 2) 'EC-095 conflated triangle full direct shortcuts with the reduced-DAG counterfactual.'

    $orderImpact = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $order4 -DominanceReduction $order4Reduced -N 4
    $middle = @($orderImpact.original_direct_component_link_single_deletion_impacts |
        Where-Object { $_.dominant_component_index -eq 2 -and $_.subordinate_component_index -eq 3 })[0]
    Check ($orderImpact.exact_baseline_reachable_nonreflexive_component_pair_count -eq 6 -and
        $middle.if_entire_original_direct_component_link_removed_from_full_dag.exact_lost_reachable_component_pair_count -eq 1 -and
        $middle.if_same_indispensable_link_removed_from_reduced_dag.exact_lost_reachable_component_pair_count -eq 4 -and
        $middle.extra_loss_only_because_redundant_shortcuts_are_absent_in_reduced_dag.exact_lost_reachable_component_pair_count -eq 3) 'EC-095 missed N4 total-order redundant shortcuts preserving FULL but not REDUCED paths.'
    $diamondImpact = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $diamond -DominanceReduction $diamondReduced -N 4
    Check ($diamondImpact.exact_original_direct_condensed_component_link_count -eq 5 -and
        $diamondImpact.exact_baseline_reachable_nonreflexive_component_pair_count -eq 5 -and
        (@($diamondImpact.original_direct_component_link_single_deletion_impacts |
            Where-Object { $_.dominant_component_index -eq 1 -and $_.subordinate_component_index -eq 4 })[0]).if_entire_original_direct_component_link_removed_from_full_dag.exact_lost_reachable_component_pair_count -eq 0) 'EC-095 incorrectly treated N4 positive-credit equal 2=3 as a strict shortcut.'
    $bridgeImpact = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $bridge4 -DominanceReduction $bridge4Reduced -N 4
    $bridgeDeletion = @($bridgeImpact.original_direct_component_link_single_deletion_impacts)[0]
    Check ($bridgeImpact.exact_baseline_reachable_nonreflexive_component_pair_count -eq 1 -and
        $bridgeImpact.exact_baseline_reachable_cross_component_original_reporter_pair_count -eq 3 -and
        $bridgeDeletion.original_direct_strict_comparison_count -eq 3 -and
        (@($bridgeDeletion.original_ec089_unordered_pair_indices) -join ',') -ceq '3,5,6' -and
        $bridgeDeletion.if_entire_original_direct_component_link_removed_from_full_dag.exact_lost_reachable_component_pair_count -eq 1 -and
        $bridgeDeletion.if_entire_original_direct_component_link_removed_from_full_dag.exact_lost_reachable_original_reporter_pair_count -eq 3) 'EC-095 deleted one reporter arc instead of the ENTIRE 3-comparison SCC bridge.'
    foreach ($special in @(@{ parent=$cycle; reduced=$cycleReduced; n=3 },
        @{ parent=$zero; reduced=$zeroReduced; n=3 },
        @{ parent=$tie; reduced=$tieReduced; n=3 })) {
        $specialImpact = Get-CodeSequenceEndpointDominanceLinkImpactProjection `
            -DominanceTopology $special.parent -DominanceReduction $special.reduced -N $special.n
        if ($special.parent -eq $tie) {
            Check ($specialImpact.exact_original_direct_condensed_component_link_count -eq 2 -and
                $specialImpact.exact_redundant_component_link_count_with_zero_full_removal_loss -eq 0) 'EC-095 promoted nontransitive positive-equal ties to direct SCC links.'
        } else {
            Check ($specialImpact.exact_original_direct_condensed_component_link_count -eq 0 -and
                @($specialImpact.original_direct_component_link_single_deletion_impacts).Count -eq 0 -and
                $specialImpact.exact_baseline_reachable_nonreflexive_component_pair_count -eq 0) 'EC-095 invented deletion impacts for a single SCC cycle or 0/0 strict-empty graph.'
        }
    }
    $supported12 = $impact12.genuine_global_threshold_endpoint_link_impact[0].exact_single_original_scc_link_removal_reachability_impact
    Check ($supported12.exact_strongly_connected_component_count -eq 12 -and
        $supported12.exact_original_direct_condensed_component_link_count -eq 0 -and
        $supported12.exact_baseline_reachable_nonreflexive_component_pair_count -eq 0 -and
        $supported12.exact_baseline_reachable_cross_component_original_reporter_pair_count -eq 0) 'EC-095 invented deletion loss for N12 supported 66 positive FIRST-credit equal pairs.'
    $badReduction = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $triangle -N 3
    $badReduction.original_condensed_component_link_reduction[0].indispensable_for_original_strict_component_reachability = $false
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $triangle -DominanceReduction $badReduction -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-095 accepted a forged indispensable-link classification despite true source flags.'
    $badReduction = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $triangle -N 3
    $badReduction.original_condensed_component_link_reduction[1].exact_sum_of_direct_strict_first_credit_advantages++
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $triangle -DominanceReduction $badReduction -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-095 accepted a forged original credit margin on a full-graph shortcut.'
    $badReduction = Get-CodeSequenceEndpointDominanceReductionProjection -DominanceTopology $diamond -N 4
    $badReduction.original_condensed_component_link_reduction[2].shortest_lexicographic_alternative_component_route.original_component_indices = @(1,3,4)
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $diamond -DominanceReduction $badReduction -N 4 } catch { $rejected = $true }
    Check $rejected 'EC-095 accepted a modified EC-094 retained-only lexical witness.'
    $badTopology = Get-CodeSequenceEndpointDominanceTopologyProjection -EndpointCreditGraph (New-EC093SyntheticCreditGraph -Case transitive_triangle) -N 3
    $badTopology.original_direct_strict_credit_advantage_arcs[0].exact_strict_winner_minus_loser_first_credit_count++
    $rejected = $false
    try { $null = Get-CodeSequenceEndpointDominanceLinkImpactProjection -DominanceTopology $badTopology -DominanceReduction $triangleReduced -N 3 } catch { $rejected = $true }
    Check $rejected 'EC-095 accepted tampered EC-093 original FIRST-credit source with still-true validity flags.'

    # EC-096: simultaneous deletion of TWO different whole ORIGINAL direct
    # SCC links, retaining ALL other original links in the FULL graph.
    # Every target is considered, but only pairs with novel JOINT-ONLY loss
    # are materialized; the other pairs still contribute to full totals.
    . (Join-Path (Split-Path -Parent $PSScriptRoot) 'scripts/codeprofileretentionendpointpairinteraction.ps1')
    $double12 = $tripleLeft.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_pair_interaction
    $double12Reverse = $tripleRight.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_pair_interaction
    Check ($null -ne $double12 -and
        $double12.scope -ceq 'exact_joint_two_distinct_original_scc_full_graph_link_removal_interaction' -and
        $double12.pair_index_in_pairwise_profile -eq $impact12.pair_index_in_pairwise_profile -and
        $double12.path_index_in_selected_pair_overview -eq $impact12.path_index_in_selected_pair_overview -and
        $double12.anchor_index_in_anchor_journeys -eq $impact12.anchor_index_in_anchor_journeys -and
        $double12.path -ceq $impact12.path -and
        ($double12.genuine_global_threshold_endpoint_pair_interaction[0].exact_joint_original_scc_link_removal_interaction |
            ConvertTo-Json -Depth 32 -Compress) -ceq
            ($double12Reverse.genuine_global_threshold_endpoint_pair_interaction[0].exact_joint_original_scc_link_removal_interaction |
                ConvertTo-Json -Depth 32 -Compress) -and
        -not ($leftSecond.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_endpoint_pair_interaction') -and
        -not ($result.data.path_focus.PSObject.Properties.Name -contains 'selected_original_finding_pair_profile_retention_endpoint_pair_interaction')) 'EC-096 changed success-only ORIGINAL selector, side seed or SequenceTop.'
    foreach ($view in @($cohortTwo, $pairedLeft, $fourAView, $fiveAView,
        $sixSixView, $allSameSevenView, $eightAView, $nineAView,
        $tenAView, $elevenAllAView, $tripleLeft)) {
        $two = $view.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_pair_interaction
        $one = $view.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_link_impact
        $red = $view.data.path_focus.selected_original_finding_pair_profile_retention_endpoint_dominance_reduction
        $n = [int]$one.counts.original_selected_report_positions
        Check ($null -ne $two -and
            $two.counts.original_selected_report_positions -eq $n -and
            $two.counts.original_maximal_repeat_family_count -eq $one.counts.original_maximal_repeat_family_count -and
            @($two.genuine_global_threshold_endpoint_pair_interaction).Count -eq 3 -and
            @($two.frozen_global_threshold_endpoint_pair_interaction).Count -eq 3 -and
            @($two.individual_original_family_endpoint_pair_interaction).Count -eq
                @($one.individual_original_family_endpoint_link_impact).Count -and
            $two.only_consumed_checked_ec093_to_ec095_original_graph_projections -and
            $two.original_ec071_caller_bits_and_all_actual_family_targets_unchanged -and
            $two.independent_of_sequence_top_and_original_finding_seed_side -and
            $two.no_path_loss_is_interpreted_as_history_probability_defect_or_repair_priority -and
            $two.no_new_evidence_read_reoptimization_git_network_or_business_write) 'EC-096 lost an actual N2..12 ORIGINAL projection/target or semantic guard.'
        $targets = [System.Collections.Generic.List[object]]::new()
        for ($i = 0; $i -lt 3; $i++) {
            Check ($two.genuine_global_threshold_endpoint_pair_interaction[$i].original_global_family_capacity_at_least -eq (3 - $i) -and
                $two.frozen_global_threshold_endpoint_pair_interaction[$i].original_global_family_capacity_at_least -eq (3 - $i)) 'EC-096 changed the original genuine/frozen global threshold identities.'
            $targets.Add(@{
                double = $two.genuine_global_threshold_endpoint_pair_interaction[$i].exact_joint_original_scc_link_removal_interaction
                single = $one.genuine_global_threshold_endpoint_link_impact[$i].exact_single_original_scc_link_removal_reachability_impact
                reduced = $red.genuine_global_threshold_endpoint_dominance_reduction[$i].exact_original_strict_condensation_transitive_reduction
            })
            $targets.Add(@{
                double = $two.frozen_global_threshold_endpoint_pair_interaction[$i].exact_joint_original_scc_link_removal_interaction
                single = $one.frozen_global_threshold_endpoint_link_impact[$i].exact_single_original_scc_link_removal_reachability_impact
                reduced = $red.frozen_global_threshold_endpoint_dominance_reduction[$i].exact_original_strict_condensation_transitive_reduction
            })
        }
        for ($i = 0; $i -lt @($two.individual_original_family_endpoint_pair_interaction).Count; $i++) {
            $tf = $two.individual_original_family_endpoint_pair_interaction[$i]
            $of = $one.individual_original_family_endpoint_link_impact[$i]
            $rf = $red.individual_original_family_endpoint_dominance_reduction[$i]
            Check ($tf.original_maximal_repeat_family_index -eq $i + 1 -and
                $of.original_maximal_repeat_family_index -eq $i + 1) 'EC-096 invented/renumbered an ORIGINAL repeat family.'
            $targets.Add(@{
                double = $tf.genuine_exact_joint_original_scc_link_removal_interaction
                single = $of.genuine_exact_single_original_scc_link_removal_reachability_impact
                reduced = $rf.genuine_original_strict_condensation_transitive_reduction
