                $sparseLoss+=$novel.exact_new_component_pair_count; $sparseMass+=$novelMass
            }
            Check ($sparseLoss -eq $x.sum_of_strictly_fourteenth_only_new_component_pair_incidences_across_fourteen_link_scenarios -and
                $sparseMass -eq $x.sum_of_strictly_fourteenth_only_new_original_reporter_pair_incidences_across_fourteen_link_scenarios) 'EC-108 sparse strictly-14 rows disagree with aggregate.'
        }
