    # A separately implemented simple BFS of the ACTUAL FULL source edges
    # checks that removing all 29 U-cut edges really destroys original paths.
    function Get-EC123RawReachableOrderedPairs {
        param([object[]]$DirectLinks, [int[]]$Removed, [int]$NodeCount=11)
        $removedSet=[System.Collections.Generic.HashSet[int]]::new()
        foreach ($index in $Removed) { [void]$removedSet.Add($index) }
        $adj=@{}
        for ($node=1;$node -le $NodeCount;$node++) { $adj[$node]=[System.Collections.Generic.List[int]]::new() }
        for ($i=0;$i -lt $DirectLinks.Length;$i++) {
            if ($removedSet.Contains($i)) { continue }
            $edge=$DirectLinks[$i]
            $dominant=[int]$edge.dominant_component_index
            $subordinate=[int]$edge.subordinate_component_index
            $adj[$dominant].Add($subordinate)
        }
        $reached=[System.Collections.Generic.List[string]]::new()
        for ($source=1;$source -le $NodeCount;$source++) {
            $visited=[System.Collections.Generic.HashSet[int]]::new()
            [void]$visited.Add($source)
            $frontier=[System.Collections.Generic.Queue[int]]::new();$frontier.Enqueue($source)
            while ($frontier.Count -gt 0) {
                $current=$frontier.Dequeue()
                foreach ($neighbor in $adj[$current]) {
                    if ($visited.Add($neighbor)) { $frontier.Enqueue($neighbor) }
                }
            }
            for ($destination=1;$destination -le $NodeCount;$destination++) {
                if ($destination -ne $source -and $visited.Contains($destination)) {
                    $reached.Add("$source>$destination")
                }
            }
        }
        return ,$reached.ToArray()
    }
